pub struct RemoteLspStore {
    upstream_client: Option<AnyProtoClient>,
    upstream_project_id: u64,
    #[cfg(feature = "jvm-tools")]
    jvm_consumers: RemoteJvmConsumerIntent,
}

#[cfg(feature = "jvm-tools")]
#[derive(Default)]
struct RemoteJvmConsumerIntent {
    enabled: bool,
    connected: bool,
    generation: u64,
    requested_roots: Option<Vec<ProjectPath>>,
    accepted_roots: Vec<ProjectPath>,
    withdrawal_needed: bool,
    request_task: Option<Task<()>>,
}

#[cfg(feature = "jvm-tools")]
impl RemoteLspStore {
    fn withdraw_jvm_consumer_intent(&mut self) {
        self.jvm_consumers.accepted_roots.clear();
        drop(self.jvm_consumers.request_task.take());
        if !mem::take(&mut self.jvm_consumers.withdrawal_needed) {
            return;
        }
        let Some(generation) = self.jvm_consumers.generation.checked_add(1) else {
            log::error!("JVM connection generation exhausted; reconnect the host before retrying");
            return;
        };
        self.jvm_consumers.generation = generation;
        if let Some(client) = self.upstream_client.as_ref() {
            client
                .send(proto::SetJvmProjectConsumers {
                    project_id: self.upstream_project_id,
                    protocol_version: 1,
                    generation,
                    roots: Vec::new(),
                })
                .log_err();
        }
    }
}

#[cfg(feature = "jvm-tools")]
impl Drop for RemoteLspStore {
    fn drop(&mut self) {
        self.withdraw_jvm_consumer_intent();
    }
}

