#[cfg(feature = "jvm-tools")]
fn gradle_plugin_resolution_failed(message: &str) -> bool {
    gradle_unknown_plugin(message) && gradle_plugin_artifact_unavailable(message)
}

#[cfg(feature = "jvm-tools")]
fn gradle_unknown_plugin(message: &str) -> bool {
    message.contains("org.gradle.api.plugins.UnknownPluginException")
}

#[cfg(feature = "jvm-tools")]
fn gradle_plugin_artifact_unavailable(message: &str) -> bool {
    message.contains("could not resolve plugin artifact")
}

#[cfg(feature = "jvm-tools")]
fn emit_jvm_provider_health(
    lsp_store: &WeakEntity<LspStore>,
    server_id: LanguageServerId,
    name: &LanguageServerName,
    health: proto::ServerHealth,
    message: &str,
    cx: &mut AsyncApp,
) {
    let result = lsp_store.update(cx, |store, cx| {
        let is_current_server = store.as_local().is_some_and(|local| {
            local
                .language_server_ids
                .values()
                .any(|server| server.id == server_id)
        });
        if !is_current_server {
            return;
        }
        cx.emit(LspStoreEvent::LanguageServerUpdate {
            language_server_id: server_id,
            name: Some(name.clone()),
            message: proto::update_language_server::Variant::StatusUpdate(proto::StatusUpdate {
                message: Some(message.to_string()),
                status: Some(proto::status_update::Status::Health(health as i32)),
            }),
        });
    });
    if let Err(error) = result {
        log::debug!("JVM provider update arrived after LSP store teardown: {error:#}");
    }
}

fn language_server_startup_status_error(
    _name: &LanguageServerName,
    error: &str,
    stderr: &str,
) -> String {
    #[cfg(feature = "jvm-tools")]
    if let Some(message) = jvm_download_capability_error(_name, error, stderr)
        .or_else(|| jdtls_startup_error(_name, error, stderr))
    {
        return message.to_owned();
    }

    if stderr.is_empty() {
        error.to_owned()
    } else {
        format!("{error}\n-- stderr --\n{stderr}")
    }
}

#[cfg(feature = "jvm-tools")]
fn jvm_download_capability_error(
    name: &LanguageServerName,
    error: &str,
    stderr: &str,
) -> Option<&'static str> {
    let download_denied = [error, stderr].iter().any(|message| {
        message.contains("capability for download_file ")
            && message.contains("is not granted by the extension host")
    });
    if !download_denied {
        return None;
    }
    match name.as_ref() {
        "jdtls" => Some(
            "Java server setup download was denied by the host extension policy. Review extension download permissions on the project host and restart its application or remote server after changing grants. You can instead configure an installed server binary and restart the language server.",
        ),
        "gradle-language-server" => Some(
            "Gradle build-script server setup download was denied by the host extension policy. Review extension download permissions on the project host and restart its application or remote server after changing grants. You can instead configure a compatible installed server command and restart the language server.",
        ),
        "kotlin-lsp" => Some(
            "Kotlin LSP download was denied by the host extension policy. Review extension download permissions on the project host and restart its application or remote server after changing grants. You can instead set lsp.kotlin-lsp.binary.path to an installed server and restart the language server. A fallback needs its own download permission or installed binary; server selection remains unchanged.",
        ),
        "kotlin-language-server" => Some(
            "Kotlin fallback download was denied by the host extension policy. Review extension download permissions on the project host and restart its application or remote server after changing grants. You can instead set lsp.kotlin-language-server.binary.path to an installed server and restart the language server. Server selection remains unchanged.",
        ),
        _ => None,
    }
}

#[cfg(feature = "jvm-tools")]
fn jdtls_startup_error(
    name: &LanguageServerName,
    error: &str,
    stderr: &str,
) -> Option<&'static str> {
    if name != &LanguageServerName::new_static("jdtls") {
        return None;
    }
    let java_probe_denied = [error, stderr].iter().any(|message| {
        message.contains("Failed to determine Java version")
            && message.contains("capability for process:exec ")
            && message.contains(r#"["-version"] is not granted by the extension host"#)
    });
    if java_probe_denied {
        return Some(
            "JDTLS could not check the Java version because the host extension policy denied its process probe. Review extension process permissions for Java -version on the project host, then restart the application or remote server on that host. The host reads these grants at startup. Cached server files do not grant process permission.",
        );
    }
    let requires_java_21 = [
        "JDTLS requires at least Java version 21 to run",
        "jdtls requires at least Java 21",
    ]
    .iter()
    .any(|signature| error.contains(signature) || stderr.contains(signature));
    if requires_java_21 {
        return Some(
            "JDTLS needs JDK 21+ on the project host. Set lsp.jdtls.settings.java_home to a complete JDK 21+ and restart the language server.",
        );
    }
    (error.contains("Failed to determine Java major version")
        || stderr.contains("Failed to determine Java major version"))
    .then_some(
        "JDTLS could not determine the host JDK version. Check that lsp.jdtls.settings.java_home points to a complete JDK 21+ on the project host, then restart the language server.",
    )
}

