    #[cfg(feature = "jvm-tools")]
    fn observe_jvm_project_trust(cx: &mut Context<Self>) {
        if let Some(trusted_worktrees) = TrustedWorktrees::try_get_global(cx) {
            cx.subscribe(&trusted_worktrees, |this, _, event, cx| {
                if let TrustedWorktreesEvent::Trusted(source, _)
                | TrustedWorktreesEvent::Restricted(source, _) = event
                    && source
                        .upgrade()
                        .is_some_and(|store| store == this.worktree_store)
                {
                    this.reconcile_remote_jvm_consumer_intent(true, cx);
                }
                if let TrustedWorktreesEvent::Restricted(source, paths) = event
                    && source
                        .upgrade()
                        .is_some_and(|store| store == this.worktree_store)
                {
                    if paths
                        .iter()
                        .any(|path| matches!(path, PathTrust::AbsPath(_)))
                    {
                        this.jdtls_projects.clear();
                        this.reviewed_jvm_dependencies.clear();
                        this.jdtls_refresh_tasks.clear();
                        this.kotlin_workspace_projects.clear();
                        this.kotlin_workspace_refresh_tasks.clear();
                    } else {
                        for path in paths {
                            if let PathTrust::Worktree(worktree_id) = path {
                                this.jdtls_projects.remove(worktree_id);
                                this.reviewed_jvm_dependencies
                                    .retain(|(root, _), _| root.worktree_id != *worktree_id);
                                this.jdtls_refresh_tasks.remove(worktree_id);
                                this.kotlin_workspace_projects.remove(worktree_id);
                                this.kotlin_workspace_refresh_tasks.remove(worktree_id);
                            }
                        }
                    }
                    this.invalidate_pending_host_jvm_restarts();
                    let has_host_session = this
                        .as_local()
                        .is_some_and(|local| local.host_jvm_session.is_some());
                    if let Some(local) = this.as_local_mut() {
                        local.clear_remote_jvm_consumers();
                    }
                    let refresh_scheduled = this.restrict_jvm_language_servers(paths, cx);
                    if has_host_session && !refresh_scheduled {
                        this.refresh_server_tree(cx);
                    }
                    cx.notify();
                }
            })
            .detach();
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn restrict_jvm_language_servers(
        &mut self,
        paths: &HashSet<PathTrust>,
        cx: &mut Context<Self>,
    ) -> bool {
        let Some(local) = self.as_local_mut() else {
            return false;
        };
        let restrict_all = paths
            .iter()
            .any(|path| matches!(path, PathTrust::AbsPath(_)));
        let affected_servers = local
            .language_server_ids
            .iter()
            .filter(|(seed, _)| {
                matches!(
                    seed.name.as_ref(),
                    "jdtls" | "kotlin-lsp" | "kotlin-language-server" | "gradle-language-server"
                ) && (restrict_all || paths.contains(&PathTrust::Worktree(seed.worktree_id)))
            })
            .map(|(seed, server)| (seed.worktree_id, seed.name.clone(), server.id))
            .collect::<Vec<_>>();
        if affected_servers.is_empty() {
            return false;
        }
        let server_ids = affected_servers.iter().map(|(_, _, id)| *id).collect();
        local.lsp_tree.remove_nodes(&server_ids);
        for server_id in &server_ids {
            if matches!(
                local.language_servers.get(server_id),
                Some(LanguageServerState::Starting { .. })
            ) {
                // Waiting for startup during shutdown could run an importer after trust was revoked.
                local.language_servers.remove(server_id);
            }
        }
        let registered_buffers = local
            .registered_buffers
            .keys()
            .copied()
            .collect::<HashSet<_>>();
        let buffers = self
            .buffer_store
            .read(cx)
            .buffers()
            .filter_map(|buffer| {
                let file = File::from_dyn(buffer.read(cx).file())?;
                if !registered_buffers.contains(&buffer.read(cx).remote_id()) {
                    return None;
                }
                let selectors = affected_servers
                    .iter()
                    .filter_map(|(worktree_id, name, _)| {
                        (*worktree_id == file.worktree_id(cx))
                            .then(|| LanguageServerSelector::Name(name.clone()))
                    })
                    .collect::<HashSet<_>>();
                (!selectors.is_empty()).then_some((buffer, selectors))
            })
            .collect::<Vec<_>>();
        let stop_tasks = server_ids
            .into_iter()
            .map(|id| self.stop_local_language_server(id, cx))
            .collect::<Vec<_>>();
        cx.spawn(async move |this, cx| {
            futures::future::join_all(stop_tasks).await;
            this.update(cx, |this, cx| {
                for (buffer, selectors) in buffers {
                    if this.as_local().is_some_and(|local| {
                        local
                            .registered_buffers
                            .contains_key(&buffer.read(cx).remote_id())
                    }) {
                        this.register_buffer_with_language_servers(&buffer, selectors, true, cx);
                    }
                }
                this.refresh_server_tree(cx);
            })
            .log_err();
        })
        .detach();
        true
    }

    pub fn as_remote(&self) -> Option<&RemoteLspStore> {
        match &self.mode {
            LspStoreMode::Remote(remote_lsp_store) => Some(remote_lsp_store),
            _ => None,
        }
    }

    pub fn as_local(&self) -> Option<&LocalLspStore> {
        match &self.mode {
            LspStoreMode::Local(local_lsp_store) => Some(local_lsp_store),
            _ => None,
        }
    }

    pub fn as_local_mut(&mut self) -> Option<&mut LocalLspStore> {
        match &mut self.mode {
            LspStoreMode::Local(local_lsp_store) => Some(local_lsp_store),
            _ => None,
        }
    }

    pub fn upstream_client(&self) -> Option<(AnyProtoClient, u64)> {
        match &self.mode {
            LspStoreMode::Remote(RemoteLspStore {
                upstream_client: Some(upstream_client),
                upstream_project_id,
                ..
            }) => Some((upstream_client.clone(), *upstream_project_id)),

            LspStoreMode::Remote(RemoteLspStore {
                upstream_client: None,
                ..
            }) => None,
            LspStoreMode::Local(_) => None,
        }
    }

    pub fn new_local(
        buffer_store: Entity<BufferStore>,
        worktree_store: Entity<WorktreeStore>,
        prettier_store: Entity<PrettierStore>,
        toolchain_store: Entity<LocalToolchainStore>,
        environment: Entity<ProjectEnvironment>,
        manifest_tree: Entity<ManifestTree>,
        languages: Arc<LanguageRegistry>,
        http_client: Arc<dyn HttpClient>,
        fs: Arc<dyn Fs>,
        isolated_recipe_test: bool,
        cx: &mut Context<Self>,
    ) -> Self {
        let yarn = YarnPathStore::new(fs.clone(), cx);
        if !isolated_recipe_test {
            cx.subscribe(&buffer_store, Self::on_buffer_store_event)
                .detach();
            cx.subscribe(&worktree_store, Self::on_worktree_store_event)
                .detach();
            #[cfg(feature = "jvm-tools")]
            Self::observe_jvm_project_trust(cx);
            cx.subscribe(&prettier_store, Self::on_prettier_store_event)
                .detach();
            cx.subscribe(&toolchain_store, Self::on_toolchain_store_event)
                .detach();
            cx.observe_global::<SettingsStore>(Self::on_settings_changed)
                .detach();
            subscribe_to_binary_statuses(&languages, cx).detach();
        }

        let _maintain_workspace_config = {
            let (sender, receiver) = watch::channel();
            (
                if isolated_recipe_test {
                    Task::ready(Ok(()))
                } else {
                    Self::maintain_workspace_config(receiver, cx)
                },
                sender,
            )
        };

        Self {
            isolated_recipe_test,
            mode: LspStoreMode::Local(LocalLspStore {
                weak: cx.weak_entity(),
                worktree_store: worktree_store.clone(),

                supplementary_language_servers: Default::default(),
                languages: languages.clone(),
                language_server_ids: Default::default(),
                language_servers: Default::default(),
                last_workspace_edits_by_language_server: Default::default(),
                language_server_watched_paths: Default::default(),
                language_server_paths_watched_for_rename: Default::default(),
                language_server_dynamic_registrations: Default::default(),
                buffers_being_formatted: Default::default(),
                buffers_to_refresh_hash_set: HashSet::default(),
                buffers_to_refresh_queue: VecDeque::new(),
                _background_diagnostics_worker: Task::ready(()).shared(),
                buffer_snapshots: Default::default(),
                prettier_store,
                environment,
                http_client,
                fs,
                yarn,
                next_diagnostic_group_id: Default::default(),
                diagnostics: Default::default(),
                _subscription: cx.on_app_quit(|this, _| {
                    this.as_local_mut()
                        .unwrap()
                        .shutdown_language_servers_on_quit()
                }),
                lsp_tree: LanguageServerTree::new(
                    manifest_tree,
                    languages.clone(),
                    toolchain_store.clone(),
                ),
                toolchain_store,
                registered_buffers: HashMap::default(),
                #[cfg(feature = "jvm-tools")]
                registered_project_languages: BTreeMap::default(),
                #[cfg(feature = "jvm-tools")]
                default_jvm_project_languages_enabled: false,
                #[cfg(feature = "jvm-tools")]
                default_jvm_language_task: None,
                #[cfg(feature = "jvm-tools")]
                host_jvm_session: None,
                #[cfg(feature = "jvm-tools")]
                manual_language_server_action: std::sync::Weak::new(),
                #[cfg(feature = "jvm-tools")]
                project_settings_observer: None,
                buffers_opened_in_servers: HashMap::default(),
                buffer_pull_diagnostics_result_ids: HashMap::default(),
                workspace_pull_diagnostics_result_ids: HashMap::default(),
                restricted_worktrees_tasks: HashMap::default(),
                all_language_servers_stopped: isolated_recipe_test,
                stopped_language_servers: HashSet::default(),
                watched_manifest_filenames: ManifestProvidersStore::global(cx)
                    .manifest_file_names(),
            }),
            last_formatting_failure: None,
            downstream_client: None,
            buffer_store,
            worktree_store,
            languages: languages.clone(),
            language_server_statuses: Default::default(),
            #[cfg(feature = "jvm-tools")]
            jdtls_projects: Default::default(),
            #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
            jdtls_snapshot_reply_gate: None,
            #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
            host_jvm_language_loaded_gate: None,
            #[cfg(feature = "jvm-tools")]
            reviewed_jvm_dependencies: Default::default(),
            #[cfg(feature = "jvm-tools")]
            jdtls_refresh_tasks: Default::default(),
            #[cfg(feature = "jvm-tools")]
            kotlin_workspace_projects: Default::default(),
            #[cfg(feature = "jvm-tools")]
            kotlin_workspace_refresh_tasks: Default::default(),
            nonce: StdRng::from_os_rng().random(),
            diagnostic_summaries: HashMap::default(),
            lsp_server_capabilities: HashMap::default(),
            semantic_token_config: SemanticTokenConfig::new(cx),
            lsp_data: HashMap::default(),
            buffer_reload_tasks: HashMap::default(),
            next_hint_id: Arc::default(),
            active_entry: None,
            _maintain_workspace_config,
            _maintain_buffer_languages: if isolated_recipe_test {
                Task::ready(())
            } else {
                Self::maintain_buffer_languages(languages, cx)
            },
        }
    }

    fn send_lsp_proto_request<R: LspCommand>(
        &self,
        buffer: Entity<Buffer>,
        client: AnyProtoClient,
        upstream_project_id: u64,
        request: R,
        cx: &mut Context<LspStore>,
    ) -> Task<anyhow::Result<<R as LspCommand>::Response>> {
        if !self.is_capable_for_proto_request(&buffer, &request, cx) {
            return Task::ready(Ok(R::Response::default()));
        }
        let message = request.to_proto(upstream_project_id, buffer.read(cx));
        cx.spawn(async move |this, cx| {
            let response = client.request(message).await?;
            let this = this.upgrade().context("project dropped")?;
            request
                .response_from_proto(response, this, buffer, cx.clone())
                .await
        })
    }

    #[cfg(all(feature = "test-support", feature = "jvm-tools"))]
    pub fn remote_for_test(
        worktrees: Entity<WorktreeStore>,
        languages: Arc<LanguageRegistry>,
        client: AnyProtoClient,
        project_id: u64,
        cx: &mut App,
    ) -> Entity<Self> {
        let buffers =
            cx.new(|cx| BufferStore::remote(worktrees.clone(), client.clone(), project_id, cx));
        cx.new(|cx| Self::new_remote(buffers, worktrees, languages, client, project_id, false, cx))
    }

    pub(super) fn new_remote(
        buffer_store: Entity<BufferStore>,
        worktree_store: Entity<WorktreeStore>,
        languages: Arc<LanguageRegistry>,
        upstream_client: AnyProtoClient,
        project_id: u64,
        isolated_recipe_test: bool,
        cx: &mut Context<Self>,
    ) -> Self {
        if !isolated_recipe_test {
            cx.subscribe(&buffer_store, Self::on_buffer_store_event)
                .detach();
            cx.subscribe(&worktree_store, Self::on_worktree_store_event)
                .detach();
            #[cfg(feature = "jvm-tools")]
            Self::observe_jvm_project_trust(cx);
            subscribe_to_binary_statuses(&languages, cx).detach();
        }
        #[cfg(feature = "jvm-tools")]
        if !isolated_recipe_test {
            cx.observe_global::<SettingsStore>(|store, cx| {
                store.reconcile_remote_jvm_consumer_intent(true, cx);
            })
            .detach();
        }
        let _maintain_workspace_config = {
            let (sender, receiver) = watch::channel();
            (
                if isolated_recipe_test {
                    Task::ready(Ok(()))
                } else {
                    Self::maintain_workspace_config(receiver, cx)
                },
                sender,
            )
        };
        Self {
            isolated_recipe_test,
            mode: LspStoreMode::Remote(RemoteLspStore {
                upstream_client: (!isolated_recipe_test).then_some(upstream_client),
                upstream_project_id: project_id,
                #[cfg(feature = "jvm-tools")]
                jvm_consumers: RemoteJvmConsumerIntent {
                    connected: !isolated_recipe_test,
                    ..Default::default()
                },
            }),
            downstream_client: None,
            last_formatting_failure: None,
            buffer_store,
            worktree_store,
            languages: languages.clone(),
            language_server_statuses: Default::default(),
            #[cfg(feature = "jvm-tools")]
            jdtls_projects: Default::default(),
            #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
            jdtls_snapshot_reply_gate: None,
            #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
            host_jvm_language_loaded_gate: None,
            #[cfg(feature = "jvm-tools")]
            reviewed_jvm_dependencies: Default::default(),
            #[cfg(feature = "jvm-tools")]
            jdtls_refresh_tasks: Default::default(),
            #[cfg(feature = "jvm-tools")]
            kotlin_workspace_projects: Default::default(),
            #[cfg(feature = "jvm-tools")]
            kotlin_workspace_refresh_tasks: Default::default(),
            nonce: StdRng::from_os_rng().random(),
            diagnostic_summaries: HashMap::default(),
            lsp_server_capabilities: HashMap::default(),
            semantic_token_config: SemanticTokenConfig::new(cx),
            next_hint_id: Arc::default(),
            lsp_data: HashMap::default(),
            buffer_reload_tasks: HashMap::default(),
            active_entry: None,

            _maintain_workspace_config,
            _maintain_buffer_languages: if isolated_recipe_test {
                Task::ready(())
            } else {
                Self::maintain_buffer_languages(languages.clone(), cx)
            },
        }
    }

    fn on_buffer_store_event(
        &mut self,
        _: Entity<BufferStore>,
        event: &BufferStoreEvent,
        cx: &mut Context<Self>,
    ) {
        match event {
            BufferStoreEvent::BufferAdded(buffer) => {
                self.on_buffer_added(buffer, cx).log_err();
            }
            BufferStoreEvent::BufferChangedFilePath { buffer, old_file } => {
                let buffer_id = buffer.read(cx).remote_id();
                if let Some(local) = self.as_local_mut()
                    && let Some(old_file) = File::from_dyn(old_file.as_ref())
                {
                    local.reset_buffer(buffer, old_file, cx);

                    if local.registered_buffers.contains_key(&buffer_id) {
                        local.unregister_old_buffer_from_language_servers(buffer, old_file, cx);
                    }
                }

                self.detect_language_for_buffer(buffer, cx);
                if let Some(local) = self.as_local_mut() {
                    local.initialize_buffer(buffer, cx);
                    if local.registered_buffers.contains_key(&buffer_id) {
                        local.register_buffer_with_language_servers(buffer, HashSet::default(), cx);
                    }
                }
            }
            _ => {}
        }
    }

    fn on_worktree_store_event(
        &mut self,
        _: Entity<WorktreeStore>,
        event: &WorktreeStoreEvent,
        cx: &mut Context<Self>,
    ) {
        #[cfg(feature = "jvm-tools")]
        match event {
            WorktreeStoreEvent::WorktreeAdded(_)
            | WorktreeStoreEvent::WorktreeRemoved(..)
            | WorktreeStoreEvent::WorktreeOrderChanged => {
                self.reconcile_remote_jvm_consumer_intent(true, cx);
            }
            WorktreeStoreEvent::WorktreeUpdatedEntries(_, changes) => {
                let inputs_changed = changes
                    .iter()
                    .any(|(path, _, _)| jvm_project::is_project_input(path.as_ref()));
                self.reconcile_remote_jvm_consumer_intent(inputs_changed, cx);
            }
            _ => {}
        }
        match event {
            WorktreeStoreEvent::WorktreeAdded(worktree) => {
                if !worktree.read(cx).is_local() {
                    return;
                }
                cx.subscribe(worktree, |this, worktree, event, cx| match event {
                    worktree::Event::UpdatedEntries(changes) => {
                        this.update_local_worktree_language_servers(&worktree, changes, cx);
                    }
                    worktree::Event::LocalSettingsInvalidated(_)
                    | worktree::Event::UpdatedGitRepositories(_)
                    | worktree::Event::DeletedEntry(_)
                    | worktree::Event::Deleted
                    | worktree::Event::UpdatedRootRepoCommonDir { .. } => {}
                })
                .detach();
                #[cfg(feature = "jvm-tools")]
                if self
                    .as_local()
                    .is_some_and(|local| local.default_jvm_project_languages_enabled)
                {
                    self.request_workspace_config_refresh();
                }
            }
            WorktreeStoreEvent::WorktreeRemoved(_, id) => self.remove_worktree(*id, cx),
            WorktreeStoreEvent::WorktreeUpdateSent(worktree) => {
                worktree.update(cx, |worktree, _cx| self.send_diagnostic_summaries(worktree));
            }
            WorktreeStoreEvent::WorktreeUpdatedEntries(worktree_id, changes) => {
                self.invalidate_diagnostic_summaries_for_removed_entries(*worktree_id, changes, cx);
                #[cfg(feature = "jvm-tools")]
                if changes
                    .iter()
                    .any(|(path, _, _)| jvm_project::is_project_input(path.as_ref()))
                    && self
                        .as_local()
                        .is_some_and(|local| local.host_jvm_session.is_some())
                {
                    if let Some(session) = self
                        .as_local_mut()
                        .and_then(|local| local.host_jvm_session.as_mut())
                    {
                        session.pending_generation = None;
                        session.pending_plan = None;
                        if let Some(abort) = session.pending_abort.take() {
                            abort.abort();
                        }
                    }
                    self.refresh_server_tree(cx);
                }
                #[cfg(feature = "jvm-tools")]
                if self.as_local().is_some_and(|local| {
                    local.default_jvm_project_languages_enabled
                        || local.registered_project_languages.keys().any(|(root, _)| {
                            root.worktree_id == *worktree_id
                                && changes
                                    .iter()
                                    .any(|(path, _, _)| root.path.starts_with(path))
                        })
                }) {
                    self.request_workspace_config_refresh();
                }
                #[cfg(feature = "jvm-tools")]
                if changes
                    .iter()
                    .any(|(path, _, _)| jvm_project::is_project_input(path.as_ref()))
                {
                    self.reviewed_jvm_dependencies
                        .retain(|(root, _), _| root.worktree_id != *worktree_id);
                    if let Some(state) = self.jdtls_projects.get_mut(worktree_id) {
                        // JDTLS writes these descriptors during import, while its project data is already stale.
                        // Semantic build inputs still invalidate the operation; SDK phases recheck descriptor ownership.
                        let metadata_during_import = state.import_operation().is_some()
                            && changes
                                .iter()
                                .filter(|(path, _, _)| jvm_project::is_project_input(path.as_ref()))
                                .all(|(path, _, _)| {
                                    matches!(path.file_name(), Some(".project" | ".classpath"))
                                });
                        if !metadata_during_import {
                            if let Err(error) = state.mark_stale() {
                                log::warn!("Could not invalidate JDTLS project state: {error:#}");
                            }
                            self.jdtls_refresh_tasks.remove(worktree_id);
                        }
                        cx.notify();
                    }
                    if let Some(state) = self.kotlin_workspace_projects.get_mut(worktree_id) {
                        if let Err(error) = state.mark_stale() {
                            log::warn!("Could not invalidate Kotlin workspace state: {error:#}");
                        }
                        self.kotlin_workspace_refresh_tasks.remove(worktree_id);
                        cx.notify();
                    }
                }
            }
            WorktreeStoreEvent::WorktreeReleased(..)
            | WorktreeStoreEvent::WorktreeOrderChanged
            | WorktreeStoreEvent::WorktreeUpdatedGitRepositories(..)
            | WorktreeStoreEvent::WorktreeDeletedEntry(..)
            | WorktreeStoreEvent::WorktreeUpdatedRootRepoCommonDir(..) => {}
        }
    }

    fn on_prettier_store_event(
        &mut self,
        _: Entity<PrettierStore>,
        event: &PrettierStoreEvent,
        cx: &mut Context<Self>,
    ) {
        match event {
            PrettierStoreEvent::LanguageServerRemoved(prettier_server_id) => {
                self.unregister_supplementary_language_server(*prettier_server_id, cx);
            }
            PrettierStoreEvent::LanguageServerAdded {
                new_server_id,
                name,
                prettier_server,
            } => {
                self.register_supplementary_language_server(
                    *new_server_id,
                    name.clone(),
                    prettier_server.clone(),
                    cx,
                );
            }
        }
    }

    fn on_toolchain_store_event(
        &mut self,
        _: Entity<LocalToolchainStore>,
        event: &ToolchainStoreEvent,
        _: &mut Context<Self>,
    ) {
        if let ToolchainStoreEvent::ToolchainActivated = event {
            self.request_workspace_config_refresh()
        }
    }

    fn request_workspace_config_refresh(&mut self) {
        *self._maintain_workspace_config.1.borrow_mut() = ();
    }

    pub fn prettier_store(&self) -> Option<Entity<PrettierStore>> {
        self.as_local().map(|local| local.prettier_store.clone())
    }

    fn on_buffer_event(
        &mut self,
        buffer: Entity<Buffer>,
        event: &language::BufferEvent,
        cx: &mut Context<Self>,
    ) {
        match event {
            language::BufferEvent::Edited { .. } => {
                self.on_buffer_edited(buffer, cx);
            }

            language::BufferEvent::Saved => {
                self.on_buffer_saved(buffer, cx);
            }

            language::BufferEvent::Reloaded => {
                self.on_buffer_reloaded(buffer, cx);
            }

            _ => {}
        }
    }

    fn on_buffer_added(&mut self, buffer: &Entity<Buffer>, cx: &mut Context<Self>) -> Result<()> {
        buffer
            .read(cx)
            .set_language_registry(self.languages.clone());

        cx.subscribe(buffer, |this, buffer, event, cx| {
            this.on_buffer_event(buffer, event, cx);
        })
        .detach();

        self.parse_modeline(buffer, cx);
        self.detect_language_for_buffer(buffer, cx);
        if let Some(local) = self.as_local_mut() {
            local.initialize_buffer(buffer, cx);
        }

        Ok(())
    }

    pub fn refresh_background_diagnostics_for_buffers(
        &mut self,
        buffers: HashSet<BufferId>,
        cx: &mut Context<Self>,
    ) -> Shared<Task<()>> {
        let Some(local) = self.as_local_mut() else {
            return Task::ready(()).shared();
        };
        for buffer in buffers {
            if local.buffers_to_refresh_hash_set.insert(buffer) {
                local.buffers_to_refresh_queue.push_back(buffer);
                if local.buffers_to_refresh_queue.len() == 1 {
                    local._background_diagnostics_worker =
                        Self::background_diagnostics_worker(cx).shared();
                }
            }
        }

        local._background_diagnostics_worker.clone()
    }

    fn refresh_next_buffer(&mut self, cx: &mut Context<Self>) -> Option<Task<Result<()>>> {
        let buffer_store = self.buffer_store.clone();
        let local = self.as_local_mut()?;
        while let Some(buffer_id) = local.buffers_to_refresh_queue.pop_front() {
            local.buffers_to_refresh_hash_set.remove(&buffer_id);
            if let Some(buffer) = buffer_store.read(cx).get(buffer_id) {
                return Some(self.pull_diagnostics_for_buffer(buffer, cx));
            }
        }
        None
    }

    fn background_diagnostics_worker(cx: &mut Context<Self>) -> Task<()> {
        cx.spawn(async move |this, cx| {
            while let Ok(Some(task)) = this.update(cx, |this, cx| this.refresh_next_buffer(cx)) {
                task.await.log_err();
            }
        })
    }

    fn on_buffer_reloaded(&mut self, buffer: Entity<Buffer>, cx: &mut Context<Self>) {
        if self.parse_modeline(&buffer, cx) {
            self.detect_language_for_buffer(&buffer, cx);
        }

        let buffer_id = buffer.read(cx).remote_id();
        let task = self.pull_diagnostics_for_buffer(buffer, cx);
        self.buffer_reload_tasks.insert(buffer_id, task);
    }

    pub(crate) fn register_buffer_with_language_servers(
        &mut self,
        buffer: &Entity<Buffer>,
        only_register_servers: HashSet<LanguageServerSelector>,
        ignore_refcounts: bool,
        cx: &mut Context<Self>,
    ) -> OpenLspBufferHandle {
        let buffer_id = buffer.read(cx).remote_id();
        let handle = OpenLspBufferHandle(cx.new(|_| OpenLspBuffer(buffer.clone())));
        if let Some(local) = self.as_local_mut() {
            let refcount = local.registered_buffers.entry(buffer_id).or_insert(0);
            if !ignore_refcounts {
                *refcount += 1;
            }

            // We run early exits on non-existing buffers AFTER we mark the buffer as registered in order to handle buffer saving.
            // When a new unnamed buffer is created and saved, we will start loading it's language. Once the language is loaded, we go over all "language-less" buffers and try to fit that new language
            // with them. However, we do that only for the buffers that we think are open in at least one editor; thus, we need to keep tab of unnamed buffers as well, even though they're not actually registered with any language
            // servers in practice (we don't support non-file URI schemes in our LSP impl).
            let Some(file) = File::from_dyn(buffer.read(cx).file()) else {
                return handle;
            };
            if !file.is_local() {
                return handle;
            }

            if ignore_refcounts || *refcount == 1 {
                local.register_buffer_with_language_servers(buffer, only_register_servers, cx);
            }
            if !ignore_refcounts {
                cx.observe_release(&handle.0, move |lsp_store, buffer, cx| {
                    let refcount = {
                        let local = lsp_store.as_local_mut().unwrap();
                        let Some(refcount) = local.registered_buffers.get_mut(&buffer_id) else {
                            debug_panic!("bad refcounting");
                            return;
                        };

                        *refcount -= 1;
                        *refcount
                    };
                    if refcount == 0 {
                        lsp_store.lsp_data.remove(&buffer_id);
                        lsp_store.buffer_reload_tasks.remove(&buffer_id);
                        let local = lsp_store.as_local_mut().unwrap();
                        local.registered_buffers.remove(&buffer_id);

                        local.buffers_opened_in_servers.remove(&buffer_id);
                        if let Some(file) = File::from_dyn(buffer.0.read(cx).file()).cloned() {
                            local.unregister_old_buffer_from_language_servers(&buffer.0, &file, cx);

                            let buffer_abs_path = file.abs_path(cx);
                            for (_, buffer_pull_diagnostics_result_ids) in
                                &mut local.buffer_pull_diagnostics_result_ids
                            {
                                buffer_pull_diagnostics_result_ids.retain(
                                    |_, buffer_result_ids| {
                                        buffer_result_ids.remove(&buffer_abs_path);
                                        !buffer_result_ids.is_empty()
                                    },
                                );
                            }

                            let diagnostic_updates = local
                                .language_servers
                                .iter()
                                .filter_map(|(server_id, state)| {
                                    let supports_workspace_diagnostics = match state {
                                        LanguageServerState::Running {
                                            workspace_diagnostics_refresh_tasks,
                                            ..
                                        } => !workspace_diagnostics_refresh_tasks.is_empty(),
                                        _ => false,
                                    };
                                    if supports_workspace_diagnostics {
                                        None
                                    } else {
                                        Some(*server_id)
                                    }
                                })
                                .map(|server_id| DocumentDiagnosticsUpdate {
                                    diagnostics: DocumentDiagnostics {
                                        document_abs_path: buffer_abs_path.clone(),
                                        version: None,
                                        diagnostics: Vec::new(),
                                    },
                                    result_id: None,
                                    registration_id: None,
                                    server_id,
                                    disk_based_sources: Cow::Borrowed(&[]),
                                })
                                .collect::<Vec<_>>();

                            lsp_store
                                .merge_diagnostic_entries(
                                    diagnostic_updates,
                                    |_, diagnostic, _| {
                                        diagnostic.source_kind != DiagnosticSourceKind::Pulled
                                    },
                                    cx,
                                )
                                .context("Clearing diagnostics for the closed buffer")
                                .log_err();
                        }
                    }
                })
                .detach();
            }
        } else if let Some((upstream_client, upstream_project_id)) = self.upstream_client() {
            let buffer_id = buffer.read(cx).remote_id().to_proto();
            cx.background_spawn(async move {
                upstream_client
                    .request(proto::RegisterBufferWithLanguageServers {
                        project_id: upstream_project_id,
                        buffer_id,
                        only_servers: only_register_servers
                            .into_iter()
                            .map(|selector| {
                                let selector = match selector {
                                    LanguageServerSelector::Id(language_server_id) => {
                                        proto::language_server_selector::Selector::ServerId(
                                            language_server_id.to_proto(),
                                        )
                                    }
                                    LanguageServerSelector::Name(language_server_name) => {
                                        proto::language_server_selector::Selector::Name(
                                            language_server_name.to_string(),
                                        )
                                    }
                                };
                                proto::LanguageServerSelector {
                                    selector: Some(selector),
                                }
                            })
                            .collect(),
                    })
                    .await
            })
            .detach();
        } else {
            // Our remote connection got closed
        }
        handle
    }

    fn maintain_buffer_languages(
        languages: Arc<LanguageRegistry>,
        cx: &mut Context<Self>,
    ) -> Task<()> {
        let mut subscription = languages.subscribe();
        let mut prev_reload_count = languages.reload_count();
        cx.spawn(async move |this, cx| {
            while let Some(()) = subscription.next().await {
                if let Some(this) = this.upgrade() {
                    // If the language registry has been reloaded, then remove and
                    // re-assign the languages on all open buffers.
                    let reload_count = languages.reload_count();
                    if reload_count > prev_reload_count {
                        prev_reload_count = reload_count;
                        this.update(cx, |this, cx| {
                            this.buffer_store.clone().update(cx, |buffer_store, cx| {
                                for buffer in buffer_store.buffers() {
                                    if let Some(f) = File::from_dyn(buffer.read(cx).file()).cloned()
                                    {
                                        buffer.update(cx, |buffer, cx| {
                                            buffer.set_language_async(None, cx)
                                        });
                                        if let Some(local) = this.as_local_mut() {
                                            local.reset_buffer(&buffer, &f, cx);

                                            if local
                                                .registered_buffers
                                                .contains_key(&buffer.read(cx).remote_id())
                                                && let Some(file_url) =
                                                    file_path_to_lsp_url(&f.abs_path(cx)).log_err()
                                            {
                                                local.unregister_buffer_from_language_servers(
                                                    &buffer, &file_url, cx,
                                                );
                                            }
                                        }
                                    }
                                }
                            });
                        });
                    }

                    this.update(cx, |this, cx| {
                        let mut plain_text_buffers = Vec::new();
                        let mut buffers_with_language = Vec::new();
                        let mut buffers_with_unknown_injections = Vec::new();
                        for handle in this.buffer_store.read(cx).buffers() {
                            let buffer = handle.read(cx);
                            if buffer.language().is_none()
                                || buffer.language() == Some(&*language::PLAIN_TEXT)
                            {
                                plain_text_buffers.push(handle);
                            } else {
                                if buffer.contains_unknown_injections() {
                                    buffers_with_unknown_injections.push(handle.clone());
                                }
                                buffers_with_language.push(handle);
                            }
                        }

                        // Deprioritize the invisible worktrees so main worktrees' language servers can be started first,
                        // and reused later in the invisible worktrees.
                        plain_text_buffers.sort_by_key(|buffer| {
                            Reverse(
                                File::from_dyn(buffer.read(cx).file())
                                    .map(|file| file.worktree.read(cx).is_visible()),
                            )
                        });

                        for buffer in plain_text_buffers {
                            this.detect_language_for_buffer(&buffer, cx);
                            if let Some(local) = this.as_local_mut() {
                                local.initialize_buffer(&buffer, cx);
                                if local
                                    .registered_buffers
                                    .contains_key(&buffer.read(cx).remote_id())
                                {
                                    local.register_buffer_with_language_servers(
                                        &buffer,
                                        HashSet::default(),
                                        cx,
                                    );
                                }
                            }
                        }

                        // Also register buffers that already have a language with
                        // any newly-available language servers (e.g., from extensions
                        // that finished loading after buffers were restored).
                        if let Some(local) = this.as_local_mut() {
                            for buffer in buffers_with_language {
                                if local
                                    .registered_buffers
                                    .contains_key(&buffer.read(cx).remote_id())
                                {
                                    local.register_buffer_with_language_servers(
                                        &buffer,
                                        HashSet::default(),
                                        cx,
                                    );
                                }
                            }
                        }

                        for buffer in buffers_with_unknown_injections {
                            buffer.update(cx, |buffer, cx| buffer.reparse(cx, false));
                        }
                        #[cfg(feature = "jvm-tools")]
                        if this.as_local().is_some_and(|local| {
                            local.default_jvm_project_languages_enabled
                                || !local.registered_project_languages.is_empty()
                        }) {
                            this.request_workspace_config_refresh();
                        }
                    });
                }
            }
        })
    }

    fn parse_modeline(&mut self, buffer_handle: &Entity<Buffer>, cx: &mut Context<Self>) -> bool {
        let buffer = buffer_handle.read(cx);
        let content = buffer.as_rope();

        let modeline_settings = {
            let settings_store = cx.global::<SettingsStore>();
            let modeline_lines = settings_store
                .raw_user_settings()
                .and_then(|s| s.content.modeline_lines)
                .or(settings_store.raw_default_settings().modeline_lines)
                .unwrap_or(5);

            const MAX_MODELINE_BYTES: usize = 1024;

            let first_bytes =
                content.clip_offset(content.len().min(MAX_MODELINE_BYTES), Bias::Left);
            let mut first_lines = Vec::new();
            let mut lines = content.chunks_in_range(0..first_bytes).lines();
            for _ in 0..modeline_lines {
                if let Some(line) = lines.next() {
                    first_lines.push(line.to_string());
                } else {
                    break;
                }
            }
            let first_lines_ref: Vec<_> = first_lines.iter().map(|line| line.as_str()).collect();

            let last_start =
                content.clip_offset(content.len().saturating_sub(MAX_MODELINE_BYTES), Bias::Left);
            let mut last_lines = Vec::new();
            let mut lines = content
                .reversed_chunks_in_range(last_start..content.len())
                .lines();
            for _ in 0..modeline_lines {
                if let Some(line) = lines.next() {
                    last_lines.push(line.to_string());
                } else {
                    break;
                }
            }
            let last_lines_ref: Vec<_> =
                last_lines.iter().rev().map(|line| line.as_str()).collect();
            modeline::parse_modeline(&first_lines_ref, &last_lines_ref)
        };

        log::debug!("Parsed modeline settings: {:?}", modeline_settings);

        buffer_handle.update(cx, |buffer, _cx| buffer.set_modeline(modeline_settings))
    }

    fn detect_language_for_buffer(
        &mut self,
        buffer_handle: &Entity<Buffer>,
        cx: &mut Context<Self>,
    ) {
        // If the buffer has a language, set it and start the language server if we haven't already.
        let buffer = buffer_handle.read(cx);
        let Some(file) = buffer.file() else {
            return;
        };
        let content = buffer.as_rope();
        let modeline_settings = buffer.modeline().map(Arc::as_ref);

        let available_language = if let Some(ModelineSettings {
            mode: Some(mode_name),
            ..
        }) = modeline_settings
        {
            self.languages
                .available_language_for_modeline_name(mode_name)
                .map(|language| language.id())
        } else {
            self.languages.language_for_file(file, Some(content), cx)
        };
        if let Some(language_id) = available_language {
            if let Some(Ok(Ok(new_language))) =
                self.languages.load_language(language_id).now_or_never()
            {
                self.set_language_for_buffer(buffer_handle, new_language, cx);
            }
        } else {
            cx.emit(LspStoreEvent::LanguageDetected {
                buffer: buffer_handle.clone(),
                new_language: None,
            });
        }
    }

    pub(crate) fn set_language_for_buffer(
        &mut self,
        buffer_entity: &Entity<Buffer>,
        new_language: Arc<Language>,
        cx: &mut Context<Self>,
    ) {
        let buffer = buffer_entity.read(cx);
        let buffer_file = buffer.file().cloned();
        let buffer_id = buffer.remote_id();
        if let Some(local_store) = self.as_local_mut()
            && local_store.registered_buffers.contains_key(&buffer_id)
            && let Some(abs_path) =
                File::from_dyn(buffer_file.as_ref()).map(|file| file.abs_path(cx))
            && let Some(file_url) = file_path_to_lsp_url(&abs_path).log_err()
        {
            local_store.unregister_buffer_from_language_servers(buffer_entity, &file_url, cx);
        }
        buffer_entity.update(cx, |buffer, cx| {
            if buffer
                .language()
                .is_none_or(|old_language| !Arc::ptr_eq(old_language, &new_language))
            {
                buffer.set_language_async(Some(new_language.clone()), cx);
            }
        });

        let settings = LanguageSettings::resolve(
            Some(&buffer_entity.read(cx)),
            Some(&new_language.name()),
            cx,
        )
        .into_owned();
        let buffer_file = File::from_dyn(buffer_file.as_ref());

        let worktree_id = if let Some(file) = buffer_file {
            let worktree = file.worktree.clone();

            if let Some(local) = self.as_local_mut()
                && local.registered_buffers.contains_key(&buffer_id)
            {
                local.register_buffer_with_language_servers(buffer_entity, HashSet::default(), cx);
            }
            Some(worktree.read(cx).id())
        } else {
            None
        };

        if settings.prettier.allowed
            && let Some(prettier_plugins) = prettier_store::prettier_plugins_for_language(&settings)
        {
            let prettier_store = self.as_local().map(|s| s.prettier_store.clone());
            if let Some(prettier_store) = prettier_store {
                prettier_store.update(cx, |prettier_store, cx| {
                    prettier_store.install_default_prettier(
                        worktree_id,
                        prettier_plugins.iter().map(|s| Arc::from(s.as_str())),
                        cx,
                    )
                })
            }
        }

        cx.emit(LspStoreEvent::LanguageDetected {
            buffer: buffer_entity.clone(),
            new_language: Some(new_language),
        })
    }

    pub fn buffer_store(&self) -> Entity<BufferStore> {
        self.buffer_store.clone()
    }

    pub fn set_active_entry(&mut self, active_entry: Option<ProjectEntryId>) {
        self.active_entry = active_entry;
    }

    pub(crate) fn send_diagnostic_summaries(&self, worktree: &mut Worktree) {
        if let Some((client, downstream_project_id)) = self.downstream_client.clone()
            && let Some(diangostic_summaries) = self.diagnostic_summaries.get(&worktree.id())
        {
            let mut summaries = diangostic_summaries.iter().flat_map(|(path, summaries)| {
                summaries
                    .iter()
                    .map(|(server_id, summary)| summary.to_proto(*server_id, path.as_ref()))
            });
            if let Some(summary) = summaries.next() {
                client
                    .send(proto::UpdateDiagnosticSummary {
                        project_id: downstream_project_id,
                        worktree_id: worktree.id().to_proto(),
                        summary: Some(summary),
                        more_summaries: summaries.collect(),
                    })
                    .log_err();
            }
        }
    }

    fn is_capable_for_proto_request<R>(
        &self,
        buffer: &Entity<Buffer>,
        request: &R,
        cx: &App,
    ) -> bool
    where
        R: LspCommand,
    {
        self.check_if_capable_for_proto_request(
            buffer,
            |capabilities| {
                request.check_capabilities(AdapterServerCapabilities {
                    server_capabilities: capabilities.clone(),
                    code_action_kinds: None,
                })
            },
            cx,
        )
    }

    fn relevant_server_ids_for_capability_check(
        &self,
        buffer: &Entity<Buffer>,
        cx: &App,
    ) -> HashSet<LanguageServerId> {
        let buffer_id = buffer.read(cx).remote_id();
        if let Some(local) = self.as_local() {
            return local
                .buffers_opened_in_servers
                .get(&buffer_id)
                .into_iter()
                .flatten()
                .copied()
                .collect();
        }

        let Some(language) = buffer.read(cx).language().cloned() else {
            return HashSet::default();
        };
        let registered_language_servers = self
            .languages
            .lsp_adapters(&language.name())
            .into_iter()
            .map(|lsp_adapter| lsp_adapter.name())
            .collect::<HashSet<_>>();
        self.language_server_statuses
            .iter()
            .filter_map(|(server_id, server_status)| {
                registered_language_servers
                    .contains(&server_status.name)
                    .then_some(*server_id)
            })
            .collect()
    }

    fn check_if_any_relevant_server_matches<F>(
        &self,
        buffer: &Entity<Buffer>,
        mut check: F,
        cx: &App,
    ) -> bool
    where
        F: FnMut(&LanguageServerStatus, &lsp::ServerCapabilities) -> bool,
    {
        self.relevant_server_ids_for_capability_check(buffer, cx)
            .into_iter()
            .filter_map(|server_id| {
                Some((
                    self.language_server_statuses.get(&server_id)?,
                    self.lsp_server_capabilities.get(&server_id)?,
                ))
            })
            .any(|(server_status, capabilities)| check(server_status, capabilities))
    }

    fn check_if_capable_for_proto_request<F>(
        &self,
        buffer: &Entity<Buffer>,
        mut check: F,
        cx: &App,
    ) -> bool
    where
        F: FnMut(&lsp::ServerCapabilities) -> bool,
    {
        self.check_if_any_relevant_server_matches(buffer, |_, capabilities| check(capabilities), cx)
    }

    pub fn supports_range_formatting(&self, buffer: &Entity<Buffer>, cx: &App) -> bool {
        let settings = LanguageSettings::for_buffer(buffer.read(cx), cx);
        settings.formatter.as_ref().iter().any(|formatter| {
            match formatter {
                Formatter::None => false,
                Formatter::Auto => {
                    settings.prettier.allowed
                        || self.check_if_capable_for_proto_request(
                            buffer,
                            server_capabilities_support_range_formatting,
                            cx,
                        )
                }
                Formatter::Prettier => true,
                Formatter::External { .. } => false,
                Formatter::LanguageServer(settings::LanguageServerFormatterSpecifier::Current) => {
                    self.check_if_capable_for_proto_request(
                        buffer,
                        server_capabilities_support_range_formatting,
                        cx,
                    )
                }
                Formatter::LanguageServer(
                    settings::LanguageServerFormatterSpecifier::Specific { name },
                ) => self.check_if_any_relevant_server_matches(
                    buffer,
                    |server_status, capabilities| {
                        server_status.name.0.as_ref() == name
                            && server_capabilities_support_range_formatting(capabilities)
                    },
                    cx,
                ),
                // `FormatSelections` should only surface when a formatter can honor the
                // selected ranges. Code actions can still run as part of formatting, but
                // they operate on the whole buffer rather than the selected text.
                Formatter::CodeAction(_) => false,
            }
        })
    }

    fn all_capable_for_proto_request<F>(
        &self,
        buffer: &Entity<Buffer>,
        mut check: F,
        cx: &App,
    ) -> Vec<(lsp::LanguageServerId, lsp::LanguageServerName)>
    where
        F: FnMut(&lsp::LanguageServerName, &lsp::ServerCapabilities) -> bool,
    {
        self.relevant_server_ids_for_capability_check(buffer, cx)
            .into_iter()
            .filter_map(|server_id| {
                Some((
                    server_id,
                    &self.language_server_statuses.get(&server_id)?.name,
                    self.lsp_server_capabilities.get(&server_id)?,
                ))
            })
            .filter(|(_, server_name, capabilities)| check(server_name, capabilities))
            .map(|(server_id, server_name, _)| (server_id, server_name.clone()))
            .collect()
    }

    pub fn request_lsp<R>(
        &mut self,
        buffer: Entity<Buffer>,
        server: LanguageServerToQuery,
        request: R,
        cx: &mut Context<Self>,
    ) -> Task<Result<R::Response>>
    where
        R: LspCommand,
        <R::LspRequest as lsp::request::Request>::Result: Send,
        <R::LspRequest as lsp::request::Request>::Params: Send,
    {
        if let Some((upstream_client, upstream_project_id)) = self.upstream_client() {
            return self.send_lsp_proto_request(
                buffer,
                upstream_client,
                upstream_project_id,
                request,
                cx,
            );
        }

        let Some(language_server) = buffer.update(cx, |buffer, cx| match server {
            LanguageServerToQuery::FirstCapable => self.as_local().and_then(|local| {
                local
                    .language_servers_for_buffer(buffer, cx)
                    .find(|(_, server)| {
                        request.check_capabilities(server.adapter_server_capabilities())
                    })
                    .map(|(_, server)| server.clone())
            }),
            LanguageServerToQuery::Other(id) => self
                .language_server_for_local_buffer(buffer, id, cx)
                .and_then(|(_, server)| {
                    request
                        .check_capabilities(server.adapter_server_capabilities())
                        .then(|| Arc::clone(server))
                }),
        }) else {
            return Task::ready(Ok(Default::default()));
        };

        let file = File::from_dyn(buffer.read(cx).file()).and_then(File::as_local);

        let Some(file) = file else {
            return Task::ready(Ok(Default::default()));
        };

        let lsp_params = match request.to_lsp_params_or_response(
            &file.abs_path(cx),
            buffer.read(cx),
            &language_server,
            cx,
        ) {
            Ok(LspParamsOrResponse::Params(lsp_params)) => lsp_params,
            Ok(LspParamsOrResponse::Response(response)) => return Task::ready(Ok(response)),
            Err(err) => {
                let message = format!(
                    "{} via {} failed: {}",
                    request.display_name(),
                    language_server.name(),
                    err
                );
                if should_log_lsp_request_failure(&message) {
                    log::warn!("{message}");
                }
                return Task::ready(Err(anyhow!(message)));
            }
        };

        let status = request.status();
        let request_timeout = ProjectSettings::get_global(cx)
            .global_lsp_settings
            .get_request_timeout();

        cx.spawn(async move |this, cx| {
            let lsp_request = language_server.request::<R::LspRequest>(lsp_params, request_timeout);

            let id = lsp_request.id();
            let _cleanup = if status.is_some() {
                cx.update(|cx| {
                    this.update(cx, |this, cx| {
                        this.on_lsp_work_start(
                            language_server.server_id(),
                            ProgressToken::Number(id),
                            LanguageServerProgress {
                                is_disk_based_diagnostics_progress: false,
                                is_cancellable: false,
                                title: None,
                                message: status.clone(),
                                percentage: None,
                                last_update_at: cx.background_executor().now(),
                            },
                            cx,
                        );
                    })
                })
                .log_err();

                Some(defer(|| {
                    cx.update(|cx| {
                        this.update(cx, |this, cx| {
                            this.on_lsp_work_end(
                                language_server.server_id(),
                                ProgressToken::Number(id),
                                cx,
                            );
                        })
                    })
                    .log_err();
                }))
            } else {
                None
            };

            let result = lsp_request.await.into_response();

            let response = result.map_err(|err| {
                let message = format!(
                    "{} via {} failed: {}",
                    request.display_name(),
                    language_server.name(),
                    err
                );
                if should_log_lsp_request_failure(&message) {
                    log::warn!("{message}");
                }
                anyhow::anyhow!(message)
            })?;

            request
                .response_from_lsp(
                    response,
                    this.upgrade().context("no app context")?,
                    buffer,
                    language_server.server_id(),
                    cx.clone(),
                )
                .await
        })
    }

    fn on_settings_changed(&mut self, cx: &mut Context<Self>) {
        #[cfg(feature = "jvm-tools")]
        if self
            .as_local()
            .is_some_and(|local| local.host_jvm_session.is_some())
        {
            // Loading grammar defaults changes editing settings, not the authority to start a provider.
            self.reconcile_pending_host_jvm_intent(cx);
            self.refresh_server_tree(cx);
        }
        let mut language_formatters_to_check = Vec::new();
        for buffer in self.buffer_store.read(cx).buffers() {
            let buffer = buffer.read(cx);
            let settings = LanguageSettings::for_buffer(buffer, cx);
            if buffer.language().is_some() {
                let buffer_file = File::from_dyn(buffer.file());
                language_formatters_to_check.push((
                    buffer_file.map(|f| f.worktree_id(cx)),
                    settings.into_owned(),
                ));
            }
        }

        #[cfg(feature = "jvm-tools")]
        if self.as_local().is_some() {
            for (worktree_id, state) in &mut self.jdtls_projects {
                let location = SettingsLocation {
                    worktree_id: *worktree_id,
                    path: RelPath::empty(),
                };
                let settings = ProjectSettings::get(Some(location), cx);
                if state
                    .snapshot()
                    .and_then(|snapshot| snapshot.metadata.as_ref())
                    .is_some_and(|facts| {
                        match facts.matches_settings(
                            settings
                                .jvm_builds
                                .as_ref()
                                .and_then(|settings| settings.maven.as_ref()),
                        ) {
                            Ok(current) => !current,
                            Err(error) => {
                                log::warn!(
                                    "Could not validate Maven selection settings: {error:#}"
                                );
                                true
                            }
                        }
                    })
                {
                    state.mark_stale().log_err();
                    self.jdtls_refresh_tasks.remove(worktree_id);
                }
            }
        }
        self.request_workspace_config_refresh();

        if let Some(prettier_store) = self.as_local().map(|s| s.prettier_store.clone()) {
            prettier_store.update(cx, |prettier_store, cx| {
                prettier_store.on_settings_changed(language_formatters_to_check, cx)
            })
        }

        let new_semantic_token_rules = crate::project_settings::ProjectSettings::get_global(cx)
            .global_lsp_settings
            .semantic_token_rules
            .clone();
        self.semantic_token_config
            .update_rules(new_semantic_token_rules);
        // Always clear cached stylizers so that changes to language-specific
        // semantic token rules (e.g. from extension install/uninstall) are
        // picked up. Stylizers are recreated lazily, so this is cheap.
        self.semantic_token_config.clear_stylizers();

        let new_global_semantic_tokens_mode =
            all_language_settings(None, cx).defaults.semantic_tokens;
        if self
            .semantic_token_config
            .update_global_mode(new_global_semantic_tokens_mode)
        {
            let all_stopped = self
                .as_local()
                .is_some_and(|local| local.all_language_servers_stopped);
            if !all_stopped {
                // Restart servers without clearing per-server stopped status.
                // Individually-stopped servers will be skipped by the guard in
                // register_buffer_with_language_servers.
                let buffers = self.buffer_store.read(cx).buffers().collect();
                self.restart_language_servers_for_buffers(buffers, HashSet::default(), false, cx);
            }
        }

        cx.notify();
    }

    #[cfg(feature = "jvm-tools")]
    pub fn set_project_settings_observer(&mut self, observer: &Entity<SettingsObserver>) {
        if let Some(local) = self.as_local_mut() {
            local.project_settings_observer = Some(observer.downgrade());
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn validate_default_jvm_language_start(
        &self,
        key: &LanguageServerSeed,
        language_name: &LanguageName,
        adapter: &Arc<CachedLspAdapter>,
        path: &ProjectPath,
        server_id: LanguageServerId,
        cx: &mut App,
    ) -> Result<Option<DefaultJvmStartupInputs>> {
        let local = self
            .as_local()
            .context("Default project language tooling requires the current project host")?;
        anyhow::ensure!(
            !self.isolated_recipe_test
                && !local.all_language_servers_stopped
                && !local.stopped_language_servers.contains(&key.name)
                && matches!(
                    local.language_servers.get(&server_id),
                    Some(LanguageServerState::Starting { .. })
                )
                && local
                    .language_server_ids
                    .get(key)
                    .is_some_and(|server| server.id == server_id),
            "Project language startup is no longer current; restart the enabled provider on the current host project"
        );
        let requires_project_intent = (local.default_jvm_project_languages_enabled
            && language_name == &LanguageName::new_static("Java"))
            || local.host_jvm_session.is_some();
        if let Some(observer) = &local.project_settings_observer {
            anyhow::ensure!(
                observer.read_with(cx, |observer, _| {
                    observer.local_settings_are_current(key.worktree_id)
                })?,
                "Project settings are unavailable or loading; review the current host settings and retry"
            );
        }
        let trusted = TrustedWorktrees::try_get_global(cx).map(|trusted| {
            trusted.update(cx, |trusted, cx| {
                trusted.can_trust(&local.worktree_store, key.worktree_id, cx)
            })
        });
        anyhow::ensure!(
            trusted.unwrap_or(!requires_project_intent),
            "Project trust is unavailable or revoked; trust the current host project and restart language servers"
        );
        let available = local.languages.lsp_adapters(language_name);
        let location = SettingsLocation {
            worktree_id: path.worktree_id,
            path: &path.path,
        };
        let language_settings = AllLanguageSettings::get(Some(location), cx).language(
            Some(location),
            Some(language_name),
            cx,
        );
        let available_names = available
            .iter()
            .map(|adapter| adapter.name())
            .collect::<Vec<_>>();
        anyhow::ensure!(
            language_settings.enable_language_server
                && language_settings
                    .customized_language_servers(&available_names)
                    .contains(&key.name)
                && available
                    .iter()
                    .any(|current| Arc::ptr_eq(current, adapter)),
            "JVM provider selection changed or its extension is unavailable; enable the current provider and restart language servers"
        );
        let current_settings = language_server_settings_for(location, &key.name, cx)
            .cloned()
            .unwrap_or_default();
        anyhow::ensure!(
            current_settings.binary == key.settings.binary
                && current_settings.initialization_options == key.settings.initialization_options
                && local.toolchain_store.read(cx).active_toolchain(
                    path.worktree_id,
                    &path.path,
                    language_name.clone()
                ) == key.toolchain,
            "Project language startup settings changed; restart language servers to use the current host settings"
        );
        if key.name == LanguageServerName::new_static("jdtls") {
            let controls = ProjectSettings::get(Some(location), cx)
                .jvm_build_selection_intent(cx.global::<SettingsStore>(), location)?
                .startup_import_controls();
            controls.validate_overrides(&current_settings)?;
            anyhow::ensure!(
                key.settings
                    .jvm_startup
                    .as_ref()
                    .is_ok_and(|old| *old == controls),
                "JVM import settings changed; restart language servers to use the current build selection"
            );
        }
        let explicit =
            local
                .registered_project_languages
                .iter()
                .any(|((root, language), consumer)| {
                    root.worktree_id == key.worktree_id
                        && language == language_name
                        && consumer.explicit
                        && local.project_language_root_is_current(root, cx)
                });
        let buffer = self.buffer_store.read(cx).buffers().any(|buffer| {
            let buffer = buffer.read(cx);
            local.registered_buffers.contains_key(&buffer.remote_id())
                && buffer
                    .language()
                    .is_some_and(|language| language.name() == *language_name)
                && File::from_dyn(buffer.file())
                    .is_some_and(|file| file.worktree_id(cx) == key.worktree_id)
        });
        if explicit || buffer || !requires_project_intent {
            return Ok(None);
        }
        let worktree = local
            .worktree_store
            .read(cx)
            .worktree_for_id(key.worktree_id, cx)
            .context(
                "Default JVM project folder is unavailable; reopen the current host project",
            )?;
        let worktree = worktree.read(cx);
        let snapshot = worktree.snapshot();
        let root_location = SettingsLocation {
            worktree_id: key.worktree_id,
            path: RelPath::empty(),
        };
        let project_settings = ProjectSettings::get(Some(root_location), cx);
        project_settings.jvm_build_selection_intent(cx.global::<SettingsStore>(), root_location)?;
        let roots = jvm_project::default_jvm_build_roots(
            &snapshot,
            key.worktree_id,
            project_settings.jvm_builds.as_ref(),
        )?;
        anyhow::ensure!(
            roots.iter().any(|root| {
                root.worktree_id == key.worktree_id
                    && local
                        .registered_project_languages
                        .get(&(root.clone(), language_name.clone()))
                        .is_some_and(|consumer| {
                            (local.default_jvm_project_languages_enabled && consumer.default_jvm)
                                || consumer.remote_jvm.is_some_and(|stamp| {
                                    local
                                        .host_jvm_session
                                        .as_ref()
                                        .is_some_and(|session| session.admits(stamp))
                                })
                        })
            }),
            "Default JVM build input is no longer current; select a visible host build file and refresh before restarting language servers"
        );
        let root_inode = snapshot
            .entry_for_path(RelPath::empty())
            .context("Default JVM project folder is unavailable; refresh the current host project")?
            .inode;
        let root_location = SettingsLocation {
            worktree_id: key.worktree_id,
            path: RelPath::empty(),
        };
        let inputs = jvm_project::default_jvm_build_inputs(
            &snapshot,
            key.worktree_id,
            ProjectSettings::get(Some(root_location), cx)
                .jvm_builds
                .as_ref(),
        )?;
        let files = inputs
            .into_iter()
            .map(|input| {
                let inode = snapshot
                    .entry_for_path(&input.path)
                    .context(
                        "Default JVM build input is unavailable; refresh the current host project",
                    )?
                    .inode;
                Ok((input.path, inode))
            })
            .collect::<Result<Vec<_>>>()?;
        Ok(Some(DefaultJvmStartupInputs {
            fs: local.fs.clone(),
            root: worktree.abs_path(),
            root_inode,
            files,
        }))
    }

    #[cfg(feature = "jvm-tools")]
    fn reconcile_pending_host_jvm_intent(&mut self, cx: &mut Context<Self>) {
        let Some(expected) = self
            .as_local()
            .and_then(|local| local.host_jvm_session.as_ref())
            .and_then(|session| session.pending_plan.clone())
        else {
            return;
        };
        let roots = expected
            .keys()
            .map(|(root, _)| root.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let current = if roots.is_empty() {
            Ok(BTreeMap::new())
        } else {
            self.host_jvm_consumer_plan(&roots, cx)
        };
        let changed = match current {
            Ok(current) => &current != expected.as_ref(),
            Err(_) => {
                log::debug!("Pending host JVM startup inputs are no longer admitted");
                true
            }
        };
        if changed
            && let Some(session) = self
                .as_local_mut()
                .and_then(|local| local.host_jvm_session.as_mut())
        {
            session.pending_generation = None;
            session.pending_plan = None;
            if let Some(abort) = session.pending_abort.take() {
                abort.abort();
            }
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn reconcile_remote_jvm_project_languages(&mut self, cx: &mut Context<Self>) {
        let Some(local) = self.as_local() else { return };
        let leased = local
            .registered_project_languages
            .iter()
            .filter_map(|(key, consumer)| consumer.remote_jvm.map(|stamp| (key.clone(), stamp)))
            .collect::<Vec<_>>();
        if leased.is_empty() {
            return;
        }
        let stamp_is_current = leased.iter().all(|(_, stamp)| {
            local
                .host_jvm_session
                .as_ref()
                .is_some_and(|session| session.admits(*stamp))
        });
        let roots = leased
            .iter()
            .map(|((root, _), _)| root.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let restarting = local.manual_language_server_action.upgrade().is_some();
        let current = if stamp_is_current {
            match self.host_jvm_consumer_plan_for_restart(&roots, restarting, cx) {
                Ok(plan) => leased.iter().all(|(key, _)| plan.contains_key(key)),
                Err(_) => {
                    log::warn!(
                        "Host JVM consumer selection is no longer admitted; refresh host setup"
                    );
                    false
                }
            }
        } else {
            false
        };
        if !current && let Some(local) = self.as_local_mut() {
            local.clear_remote_jvm_consumers();
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn host_jvm_consumer_plan(
        &self,
        roots: &[ProjectPath],
        cx: &mut App,
    ) -> Result<JvmConsumerPlan> {
        self.host_jvm_consumer_plan_for_restart(roots, false, cx)
    }

    #[cfg(feature = "jvm-tools")]
    fn host_jvm_consumer_plan_for_restart(
        &self,
        roots: &[ProjectPath],
        restarting: bool,
        cx: &mut App,
    ) -> Result<JvmConsumerPlan> {
        let local = self
            .as_local()
            .context("JVM project tooling requires the current host")?;
        ensure!(
            restarting || !local.all_language_servers_stopped,
            "JVM language servers are stopped; restart the enabled host providers before retrying"
        );
        let mut plan = BTreeMap::new();
        for root in roots {
            ensure!(
                local.project_language_root_is_current(root, cx),
                "JVM project root is unavailable; refresh the current host project"
            );
            ensure!(
                TrustedWorktrees::try_get_global(cx).is_some_and(|trusted| {
                    trusted.update(cx, |trusted, cx| {
                        trusted.can_trust(&self.worktree_store, root.worktree_id, cx)
                    })
                }),
                "Trust the current host project before starting JVM tooling"
            );
            let worktree = local
                .worktree_store
                .read(cx)
                .worktree_for_id(root.worktree_id, cx)
                .context("JVM host project folder is unavailable; reopen it and retry")?;
            let worktree = worktree.read(cx);
            ensure!(
                !worktree.is_single_file(),
                "JVM tooling needs a project folder; open the current host project"
            );
            let root_location = SettingsLocation {
                worktree_id: root.worktree_id,
                path: RelPath::empty(),
            };
            let project_settings = ProjectSettings::get(Some(root_location), cx);
            project_settings
                .jvm_build_selection_intent(cx.global::<SettingsStore>(), root_location)
                .map_err(|_| {
                    anyhow!("JVM build selection is invalid; check current host project settings")
                })?;
            let eligible = jvm_project::default_jvm_build_roots(
                &worktree.snapshot(),
                root.worktree_id,
                project_settings.jvm_builds.as_ref(),
            )
            .map_err(|_| {
                anyhow!("JVM build selection is unavailable; check current host project settings")
            })?;
            ensure!(
                eligible.contains(root),
                "JVM project root is no longer selected; refresh the current host project"
            );
            let location = SettingsLocation {
                worktree_id: root.worktree_id,
                path: &root.path,
            };
            let before = plan.len();
            for name in ["Java", "Kotlin"] {
                let language_name = LanguageName::new_static(name);
                let settings = AllLanguageSettings::get(Some(location), cx).language(
                    Some(location),
                    Some(&language_name),
                    cx,
                );
                if !settings.enable_language_server {
                    continue;
                }
                ensure!(
                    local.languages.available_language_for_name(name).is_some(),
                    "An enabled JVM language is unavailable; enable its extension on the host or disable that language server"
                );
                let adapters = local.languages.lsp_adapters(&language_name);
                let available = adapters
                    .iter()
                    .map(|adapter| adapter.name())
                    .collect::<Vec<_>>();
                let selected = settings.customized_language_servers(&available);
                ensure!(
                    available.iter().any(|name| selected.contains(name)
                        && (restarting || !local.stopped_language_servers.contains(name))),
                    "An enabled JVM provider is unavailable or stopped; check host language-server settings and extension setup"
                );
                let mut providers = Vec::new();
                for adapter in adapters.iter().filter(|adapter| {
                    selected.contains(&adapter.name())
                        && (restarting || !local.stopped_language_servers.contains(&adapter.name()))
                }) {
                    let server_name = adapter.name();
                    let server_settings = language_server_settings_for(location, &server_name, cx)
                        .cloned()
                        .unwrap_or_default();
                    let jvm_startup = if server_name == LanguageServerName::new_static("jdtls") {
                        let controls = ProjectSettings::get(Some(location), cx)
                            .jvm_build_selection_intent(cx.global::<SettingsStore>(), location)
                            .map_err(|_| {
                                anyhow!(
                                    "JVM build selection is invalid; check current host settings"
                                )
                            })?
                            .startup_import_controls();
                        controls.validate_overrides(&server_settings)
                            .map_err(|_| anyhow!("JVM startup settings conflict with build selection; review host language-server settings"))?;
                        controls
                    } else {
                        jvm_project::JvmStartupImportControls::default()
                    };
                    providers.push(LanguageServerSeed {
                        worktree_id: root.worktree_id,
                        name: server_name,
                        toolchain: local.toolchain_store.read(cx).active_toolchain(
                            root.worktree_id,
                            &root.path,
                            language_name.clone(),
                        ),
                        settings: LanguageServerSeedSettings {
                            binary: server_settings.binary,
                            initialization_options: server_settings.initialization_options,
                            jvm_startup: Ok(jvm_startup),
                        },
                    });
                }
                plan.insert((root.clone(), language_name), providers);
            }
            ensure!(
                plan.len() > before,
                "JVM tooling is disabled for this root; enable a host JVM provider before retrying"
            );
        }
        ensure!(
            local
                .registered_project_languages
                .iter()
                .filter(|(_, consumer)| consumer.explicit || consumer.default_jvm)
                .map(|(key, _)| key)
                .chain(plan.keys())
                .collect::<BTreeSet<_>>()
                .len()
                <= 256,
            "Project language tooling has reached its root limit; unlink unused roots and retry"
        );
        Ok(plan)
    }

    #[cfg(feature = "jvm-tools")]
    fn ensure_host_jvm_consumer_scope(&self, project_id: u64, peer: proto::PeerId) -> Result<()> {
        ensure!(
            !self.isolated_recipe_test,
            "Remote JVM project tooling is unavailable in this isolated execution profile"
        );
        ensure!(
            self.downstream_client
                .as_ref()
                .is_some_and(|(_, id)| *id == project_id),
            "JVM project ownership belongs to a different host project"
        );
        ensure!(
            self.as_local()
                .and_then(|local| local.host_jvm_session.as_ref())
                .is_some_and(|session| session.peer == peer && peer.id != 0 && peer.owner_id == 0),
            "JVM project ownership requires the current scoped host connection; reconnect and retry"
        );
        Ok(())
    }

    #[cfg(feature = "jvm-tools")]
    fn invalidate_pending_host_jvm_restarts(&mut self) {
        if let Some(local) = self.as_local_mut() {
            // A delayed restart must not clear a newer stop, even on the same connection.
            local.manual_language_server_action = std::sync::Weak::new();
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn host_jvm_restart_trusted_worktrees(&self, cx: &mut App) -> Result<Vec<WorktreeId>> {
        let trusted = TrustedWorktrees::try_get_global(cx)
            .context("Restore project trust on the host, then retry project restart")?;
        let worktrees = self
            .worktree_store
            .read(cx)
            .visible_worktrees(cx)
            .take(257)
            .map(|worktree| worktree.read(cx).id())
            .collect::<Vec<_>>();
        ensure!(
            !worktrees.is_empty() && worktrees.len() <= 256,
            "Project restart needs a bounded current host workspace; reopen or narrow it and retry"
        );
        for worktree_id in &worktrees {
            ensure!(
                trusted.update(cx, |trusted, cx| {
                    trusted.can_trust(&self.worktree_store, *worktree_id, cx)
                }),
                "Trust the current host project before restarting JVM tooling"
            );
        }
        Ok(worktrees)
    }

    #[cfg(feature = "jvm-tools")]
    fn host_jvm_restart_scope(
        &mut self,
        project_id: u64,
        peer: proto::PeerId,
        relayed: bool,
        cx: &mut App,
    ) -> Result<Option<HostJvmRestartScope>> {
        let local = self
            .as_local()
            .context("Project restart requires the current host")?;
        let Some(session) = local.host_jvm_session.as_ref() else {
            return Ok(None);
        };
        ensure!(
            !relayed,
            "JVM project restart requires the direct current host connection; reconnect and retry"
        );
        self.ensure_host_jvm_consumer_scope(project_id, peer)?;
        let stamp = JvmConsumerStamp {
            peer,
            generation: session.last_generation,
        };
        let accepted_generation = session.accepted_generation;
        let roots = local
            .registered_project_languages
            .iter()
            .filter(|(_, consumer)| consumer.remote_jvm.is_some())
            .map(|((root, _), _)| root.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let registry_generation = local.languages.reload_count();
        let trusted_worktrees = self.host_jvm_restart_trusted_worktrees(cx)?;
        let plan = self.host_jvm_consumer_plan_for_restart(&roots, true, cx)?;
        let action = Arc::new(());
        self.as_local_mut()
            .context("Project restart requires the current host")?
            .manual_language_server_action = Arc::downgrade(&action);
        Ok(Some(HostJvmRestartScope {
            project_id,
            stamp,
            accepted_generation,
            trusted_worktrees,
            plan,
            registry_generation,
            action,
        }))
    }

    #[cfg(feature = "jvm-tools")]
    fn validate_host_jvm_restart_scope(
        &self,
        scope: &HostJvmRestartScope,
        cx: &mut App,
    ) -> Result<()> {
        self.ensure_host_jvm_consumer_scope(scope.project_id, scope.stamp.peer)?;
        let local = self
            .as_local()
            .context("Project restart requires the current host")?;
        ensure!(
            local
                .manual_language_server_action
                .upgrade()
                .is_some_and(|action| { Arc::ptr_eq(&scope.action, &action) })
                && local.host_jvm_session.as_ref().is_some_and(|session| {
                    session.last_generation == scope.stamp.generation
                        && session.accepted_generation == scope.accepted_generation
                })
                && local.languages.reload_count() == scope.registry_generation,
            "Project restart was superseded; review the current host state and retry"
        );
        ensure!(
            self.host_jvm_restart_trusted_worktrees(cx)? == scope.trusted_worktrees,
            "The host workspace changed during restart; refresh and retry"
        );
        let roots = scope
            .plan
            .keys()
            .map(|(root, _)| root.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let current = self.host_jvm_consumer_plan_for_restart(&roots, true, cx)?;
        ensure!(
            current == scope.plan,
            "JVM providers or project selection changed during restart; refresh and retry"
        );
        Ok(())
    }

    #[cfg(feature = "jvm-tools")]
    fn validate_pending_host_jvm_setup(
        &self,
        project_id: u64,
        stamp: JvmConsumerStamp,
        expected: &JvmConsumerPlan,
        registry_generation: usize,
        cx: &mut App,
    ) -> Result<()> {
        self.ensure_host_jvm_consumer_scope(project_id, stamp.peer)?;
        ensure!(
            self.as_local()
                .and_then(|local| local.host_jvm_session.as_ref())
                .is_some_and(
                    |session| session.pending_generation == Some(stamp.generation)
                        && session.pending_plan.as_deref() == Some(expected)
                ),
            "JVM project ownership changed during setup; refresh and retry"
        );
        let local = self
            .as_local()
            .context("JVM project tooling requires the current host")?;
        ensure!(
            local.languages.reload_count() == registry_generation,
            "JVM providers changed during setup; refresh and retry"
        );
        let roots = expected
            .keys()
            .map(|(root, _)| root.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let current = if roots.is_empty() {
            BTreeMap::new()
        } else {
            self.host_jvm_consumer_plan(&roots, cx)?
        };
        ensure!(
            &current == expected,
            "JVM startup inputs changed during setup; refresh and retry"
        );
        Ok(())
    }

    #[cfg(feature = "jvm-tools")]
    async fn handle_set_jvm_project_consumers(
        this: Entity<Self>,
        envelope: TypedEnvelope<proto::SetJvmProjectConsumers>,
        mut cx: AsyncApp,
    ) -> Result<proto::JvmProjectConsumersResponse> {
        ensure!(
            envelope.original_sender_id.is_none(),
            "JVM default ownership is unavailable to relayed clients; use the direct current host connection"
        );
        let request = envelope.payload;
        let peer = envelope.sender_id;
        ensure!(
            request.protocol_version == 1 && request.generation != 0,
            "JVM project ownership protocol is unsupported; update the host and reconnect"
        );
        ensure!(
            request.roots.len() <= 128 && request.encoded_len() <= 1_048_576,
            "JVM project ownership exceeds its scope limit; narrow selected roots and retry"
        );
        let roots = request
            .roots
            .iter()
            .map(|root| {
                ensure!(
                    root.path.len() <= 4096 && !root.path.chars().any(char::is_control),
                    "JVM project root is invalid; refresh the current host project"
                );
                let path = RelPath::from_unix_str(&root.path).map_err(|_| {
                    anyhow!("JVM project root is invalid; refresh the current host project")
                })?;
                Ok(ProjectPath {
                    worktree_id: WorktreeId::from_proto(root.worktree_id),
                    path: path.into(),
                })
            })
            .collect::<Result<Vec<_>>>()?;
        ensure!(
            roots.iter().collect::<BTreeSet<_>>().len() == roots.len(),
            "JVM project roots are duplicated; refresh the current selection"
        );
        let (plan, languages, registry_generation, registration) =
            this.update(&mut cx, |store, cx| -> Result<_> {
                store.ensure_host_jvm_consumer_scope(request.project_id, peer)?;
                let local = store
                    .as_local()
                    .context("JVM project tooling requires the current host")?;
                ensure!(
                    local
                        .host_jvm_session
                        .as_ref()
                        .is_some_and(|session| request.generation > session.last_generation),
                    "JVM project ownership request is stale; refresh the current selection"
                );
                let plan = Arc::new(if roots.is_empty() {
                    BTreeMap::new()
                } else {
                    store.host_jvm_consumer_plan(&roots, cx)?
                });
                let local = store
                    .as_local_mut()
                    .context("JVM project tooling requires the current host")?;
                let languages = local.languages.clone();
                let registry_generation = languages.reload_count();
                for (key, consumer) in &mut local.registered_project_languages {
                    if !plan.contains_key(key) {
                        consumer.remote_jvm = None;
                    }
                }
                local.registered_project_languages.retain(|_, consumer| {
                    consumer.explicit || consumer.default_jvm || consumer.remote_jvm.is_some()
                });
                let session = local
                    .host_jvm_session
                    .as_mut()
                    .context("JVM host connection is unavailable")?;
                if let Some(abort) = session.pending_abort.take() {
                    abort.abort();
                }
                let (abort, registration) = futures::future::AbortHandle::new_pair();
                session.pending_abort = Some(abort);
                session.last_generation = request.generation;
                session.pending_generation = Some(request.generation);
                session.pending_plan = Some(plan.clone());
                if plan.is_empty() {
                    session.accepted_generation = None;
                }
                store.refresh_server_tree(cx);
                Ok((plan, languages, registry_generation, registration))
            })?;
        let result = match futures::future::Abortable::new(
            async {
                let mut loaded = BTreeMap::new();
                for name in plan.keys().map(|(_, name)| name).collect::<BTreeSet<_>>() {
                    let language = languages
                .language_for_name(name.as_ref())
                .await
                .map_err(|_| {
                    anyhow!(
                        "JVM language could not be loaded; check the host extension setup and retry"
                    )
                })?;
                    #[cfg(feature = "test-support")]
                    if let Some(gate) = this.update(&mut cx, |store, _| {
                        store.host_jvm_language_loaded_gate.take()
                    }) {
                        gate.started
                            .send(request.generation)
                            .map_err(|_| anyhow!("Host JVM setup observer closed"))?;
                        gate.release
                            .await
                            .context("Host JVM setup observation gate closed")?;
                    }
                    this.update(&mut cx, |store, cx| {
                        store.validate_pending_host_jvm_setup(
                            request.project_id,
                            JvmConsumerStamp {
                                peer,
                                generation: request.generation,
                            },
                            &plan,
                            registry_generation,
                            cx,
                        )
                    })?;
                    loaded.insert(name.clone(), language);
                }
                this.update(&mut cx, |store, cx| -> Result<_> {
                store.validate_pending_host_jvm_setup(
                    request.project_id, JvmConsumerStamp { peer, generation: request.generation },
                    &plan, registry_generation, cx,
                )?;
                let admitted = plan
                    .keys()
                    .map(|(root, name)| {
                        Ok((
                            root.clone(),
                            name.clone(),
                            loaded
                                .get(name)
                                .context("JVM language is unavailable; retry host setup")?
                                .clone(),
                        ))
                    })
                    .collect::<Result<Vec<_>>>()?;
                let response = proto::JvmProjectConsumersResponse {
                    protocol_version: 1,
                    generation: request.generation,
                    accepted_roots: roots.iter().map(ProjectPath::to_proto).collect(),
                };
                ensure!(
                    response.encoded_len() <= 1_048_576,
                    "JVM project ownership exceeds its scope limit; narrow selected roots and retry"
                );
                let local = store
                    .as_local_mut()
                    .context("JVM project tooling requires the current host")?;
                let session = local
                    .host_jvm_session
                    .as_mut()
                    .context("JVM host connection is unavailable")?;
                session.pending_generation = None;
                session.pending_plan = None;
                drop(session.pending_abort.take());
                session.accepted_generation = Some(request.generation);
                for (root, name, language) in admitted {
                    let stamp = JvmConsumerStamp {
                        peer,
                        generation: request.generation,
                    };
                    local
                        .registered_project_languages
                        .entry((root, name))
                        .and_modify(|consumer| {
                            consumer.language = language.clone();
                            consumer.remote_jvm = Some(stamp);
                        })
                        .or_insert(ProjectLanguageConsumer {
                            language,
                            explicit: false,
                            default_jvm: false,
                            remote_jvm: Some(stamp),
                        });
                }
                store.refresh_server_tree(cx);
                Ok(response)
            })
            },
            registration,
        )
        .await
        {
            Ok(result) => result,
            Err(_) => Err(anyhow!(
                "JVM project setup was cancelled; refresh current host selection and retry"
            )),
        };
        if result.is_err() {
            this.update(&mut cx, |store, _| {
                if let Some(session) = store
                    .as_local_mut()
                    .and_then(|local| local.host_jvm_session.as_mut())
                    && session.peer == peer
                    && session.pending_generation == Some(request.generation)
                {
                    session.pending_generation = None;
                    session.pending_plan = None;
                    drop(session.pending_abort.take());
                }
            });
        }
        result
    }

    #[cfg(feature = "jvm-tools")]
    pub fn set_host_jvm_session(
        &mut self,
        peer: Option<proto::PeerId>,
        cx: &mut Context<Self>,
    ) -> Result<()> {
        ensure!(
            peer.is_none() || !self.isolated_recipe_test,
            "Remote JVM project tooling is unavailable in this isolated execution profile"
        );
        ensure!(
            peer.is_none_or(|peer| peer.owner_id == 0 && peer.id != 0),
            "Remote JVM project tooling requires the current scoped host connection"
        );
        let local = self
            .as_local_mut()
            .context("Remote JVM project ownership must be configured on the project host")?;
        if local.host_jvm_session.as_ref().map(|session| session.peer) == peer {
            return Ok(());
        }
        local.clear_remote_jvm_consumers();
        local.host_jvm_session = peer.map(|peer| HostJvmSession {
            peer,
            last_generation: 0,
            pending_generation: None,
            pending_plan: None,
            pending_abort: None,
            accepted_generation: None,
        });
        self.refresh_server_tree(cx);
        Ok(())
    }

    #[cfg(feature = "jvm-tools")]
    fn current_remote_jvm_roots(&self, cx: &App) -> Result<Vec<ProjectPath>> {
        let remote = self
            .as_remote()
            .context("JVM tooling needs a remote project")?;
        ensure!(
            !self.isolated_recipe_test
                && remote
                    .upstream_client
                    .as_ref()
                    .is_some_and(|client| !client.is_via_collab()),
            "JVM tooling requires the current direct host connection; reconnect and retry"
        );
        let trusted = TrustedWorktrees::try_get_global(cx)
            .context("Restore project trust on the host, then retry JVM setup")?;
        let mut roots = BTreeSet::new();
        for worktree in self.worktree_store.read(cx).visible_worktrees(cx) {
            let worktree = worktree.read(cx);
            if worktree.is_local() || worktree.is_single_file() {
                continue;
            }
            let location = SettingsLocation {
                worktree_id: worktree.id(),
                path: RelPath::empty(),
            };
            let settings = ProjectSettings::get(Some(location), cx);
            settings
                .jvm_build_selection_intent(cx.global::<SettingsStore>(), location)
                .map_err(|_| {
                    anyhow!("JVM build selection is invalid; check host project settings and retry")
                })?;
            let selected = jvm_project::default_jvm_build_roots(
                &worktree.snapshot(),
                worktree.id(),
                settings.jvm_builds.as_ref(),
            )
            .map_err(|_| {
                anyhow!("JVM roots are unavailable; narrow host build-file selections and retry")
            })?;
            if !selected.is_empty() {
                ensure!(
                    trusted.read(cx).observed_worktree_trust(
                        &self.worktree_store,
                        worktree.id(),
                        cx
                    ) == Some(true),
                    "Trust the current host project before starting JVM tooling"
                );
            }
            ensure!(
                selected
                    .iter()
                    .all(|root| root.path.as_unix_str().len() <= 4096),
                "JVM root path exceeds its scope limit; narrow host build-file selections and retry"
            );
            roots.extend(selected);
            ensure!(
                roots.len() <= 128,
                "JVM project tooling has reached its root limit; narrow host build-file selections and retry"
            );
        }
        Ok(roots.into_iter().collect())
    }

    #[cfg(feature = "jvm-tools")]
    fn reconcile_remote_jvm_consumer_intent(&mut self, force: bool, cx: &mut Context<Self>) {
        let Some(remote) = self.as_remote() else {
            return;
        };
        if !remote.jvm_consumers.connected || remote.upstream_client.is_none() {
            return;
        }
        if !remote.jvm_consumers.enabled && remote.jvm_consumers.requested_roots.is_none() {
            return;
        }
        let roots = if remote.jvm_consumers.enabled {
            self.current_remote_jvm_roots(cx)
        } else {
            Ok(Vec::new())
        };
        let error = roots.as_ref().err().map(ToString::to_string);
        let roots = roots.unwrap_or_default();
        let LspStoreMode::Remote(remote) = &mut self.mode else {
            return;
        };
        if !force && remote.jvm_consumers.requested_roots.as_ref() == Some(&roots) {
            return;
        }
        let Some(generation) = remote.jvm_consumers.generation.checked_add(1) else {
            drop(remote.jvm_consumers.request_task.take());
            remote.jvm_consumers.accepted_roots.clear();
            cx.emit(LspStoreEvent::Notification(
                "JVM connection generation is exhausted; reconnect the host before retrying".into(),
            ));
            return;
        };
        let Some(client) = remote.upstream_client.clone() else {
            return;
        };
        let request = proto::SetJvmProjectConsumers {
            project_id: remote.upstream_project_id,
            protocol_version: 1,
            generation,
            roots: roots.iter().map(ProjectPath::to_proto).collect(),
        };
        if request.encoded_len() > 1_048_576
            || request.roots.iter().any(|root| root.path.len() > 4096)
        {
            cx.emit(LspStoreEvent::Notification(
                "JVM project ownership exceeds its scope limit; narrow selected roots and retry"
                    .into(),
            ));
            return;
        }
        remote.jvm_consumers.generation = generation;
        drop(remote.jvm_consumers.request_task.take());
        remote.jvm_consumers.accepted_roots.clear();
        remote.jvm_consumers.requested_roots = Some(roots.clone());
        remote.jvm_consumers.withdrawal_needed = !roots.is_empty();
        if let Some(error) = error {
            cx.emit(LspStoreEvent::Notification(error));
        }
        let response = client.request(request);
        let task = cx.spawn(async move |this, cx| {
            let deadline = cx.background_executor().timer(Duration::from_secs(15));
            let (result, timed_out) = match futures::future::select(Box::pin(response), Box::pin(deadline)).await {
                futures::future::Either::Left((response, _)) => (response, false),
                futures::future::Either::Right(_) => (Err(anyhow!("JVM host setup timed out")), true),
            };
            this.update(cx, |store, cx| {
                let scope_current = roots.is_empty() || store.current_remote_jvm_roots(cx).is_ok_and(|current| current == roots);
                let LspStoreMode::Remote(remote) = &mut store.mode else { return; };
                if remote.jvm_consumers.generation != generation || !remote.jvm_consumers.connected {
                    return;
                }
                let valid = result.as_ref().is_ok_and(|response| {
                    response.protocol_version == 1 && response.generation == generation
                        && response.encoded_len() <= 1_048_576
                        && response.accepted_roots == roots.iter().map(ProjectPath::to_proto).collect::<Vec<_>>()
                });
                if scope_current && valid {
                    remote.jvm_consumers.accepted_roots = roots;
                    if !remote.jvm_consumers.enabled {
                        remote.jvm_consumers.requested_roots = None;
                    }
                    cx.notify();
                } else {
                    store.withdraw_remote_jvm_consumer_intent();
                    if let LspStoreMode::Remote(remote) = &mut store.mode
                        && !remote.jvm_consumers.enabled
                    {
                        remote.jvm_consumers.requested_roots = None;
                    }
                    let message = if timed_out {
                        "JVM host setup timed out; check the host connection and providers, then retry or reconnect"
                    } else if !scope_current {
                        "JVM selection or trust changed; review the current host project and retry"
                    } else if result.is_err() {
                        "JVM host setup is unavailable; check host version, trust, extensions and provider settings, then retry or reconnect"
                    } else {
                        "The host returned unsupported or stale JVM ownership; update the host and retry or reconnect"
                    };
                    cx.emit(LspStoreEvent::Notification(message.into()));
                    cx.notify();
                }
            }).log_err();
        });
        if let LspStoreMode::Remote(remote) = &mut self.mode {
            remote.jvm_consumers.request_task = Some(task);
        }
        cx.notify();
    }

    #[cfg(feature = "jvm-tools")]
    fn withdraw_remote_jvm_consumer_intent(&mut self) {
        if let LspStoreMode::Remote(remote) = &mut self.mode {
            remote.withdraw_jvm_consumer_intent();
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn cancel_pending_remote_jvm_request(&mut self, cx: &mut Context<Self>) {
        let LspStoreMode::Remote(remote) = &mut self.mode else {
            return;
        };
        if !remote
            .jvm_consumers
            .request_task
            .as_ref()
            .is_some_and(|task| !task.is_ready())
        {
            return;
        }
        drop(remote.jvm_consumers.request_task.take());
        remote.jvm_consumers.accepted_roots.clear();
        if let Some(generation) = remote.jvm_consumers.generation.checked_add(1) {
            remote.jvm_consumers.generation = generation;
        } else {
            cx.emit(LspStoreEvent::Notification(
                "JVM connection generation is exhausted; reconnect the host before retrying".into(),
            ));
        }
        cx.notify();
    }

    #[cfg(feature = "jvm-tools")]
    fn restart_remote_jvm_project_languages(&mut self, cx: &mut Context<Self>) -> bool {
        if !self.as_remote().is_some_and(|remote| {
            remote.jvm_consumers.enabled
                && remote.jvm_consumers.connected
                && remote
                    .upstream_client
                    .as_ref()
                    .is_some_and(|client| !client.is_via_collab())
        }) {
            return false;
        }
        let roots = match self.current_remote_jvm_roots(cx) {
            Ok(roots) if roots.is_empty() => {
                self.withdraw_remote_jvm_consumer_intent();
                return false;
            }
            Ok(roots) => roots,
            Err(error) => {
                self.withdraw_remote_jvm_consumer_intent();
                cx.emit(LspStoreEvent::Notification(error.to_string()));
                cx.notify();
                return true;
            }
        };
        let LspStoreMode::Remote(remote) = &mut self.mode else {
            return false;
        };
        let Some(generation) = remote.jvm_consumers.generation.checked_add(1) else {
            drop(remote.jvm_consumers.request_task.take());
            remote.jvm_consumers.accepted_roots.clear();
            cx.emit(LspStoreEvent::Notification(
                "JVM connection generation is exhausted; reconnect the host before retrying".into(),
            ));
            cx.notify();
            return true;
        };
        let Some(client) = remote.upstream_client.as_ref() else {
            return false;
        };
        let response = client.request(proto::RestartLanguageServers {
            project_id: remote.upstream_project_id,
            buffer_ids: Vec::new(),
            only_servers: Vec::new(),
            all: true,
        });
        remote.jvm_consumers.generation = generation;
        drop(remote.jvm_consumers.request_task.take());
        remote.jvm_consumers.accepted_roots.clear();
        // Retain the host lease so its bufferless consumers survive the restart.
        remote.jvm_consumers.request_task = Some(cx.spawn(async move |this, cx| {
            let deadline = cx.background_executor().timer(Duration::from_secs(15));
            let (result, timed_out) = match futures::future::select(Box::pin(response), Box::pin(deadline)).await {
                futures::future::Either::Left((response, _)) => (response, false),
                futures::future::Either::Right(_) => (Err(anyhow!("JVM host restart timed out")), true),
            };
            this.update(cx, |store, cx| {
                if !store.as_remote().is_some_and(|remote| {
                    remote.jvm_consumers.enabled && remote.jvm_consumers.connected
                        && remote.jvm_consumers.generation == generation
                }) {
                    return;
                }
                let scope_current = store.current_remote_jvm_roots(cx).is_ok_and(|current| current == roots);
                if result.is_ok() && scope_current {
                    store.reconcile_remote_jvm_consumer_intent(true, cx);
                    return;
                }
                store.withdraw_remote_jvm_consumer_intent();
                let message = if timed_out {
                    "JVM host restart timed out; check the host connection and providers, then retry or reconnect"
                } else if !scope_current {
                    "JVM selection or trust changed during restart; review the current host project and retry"
                } else {
                    "JVM host restart is unavailable; check host version, trust, extensions and provider settings, then retry or reconnect"
                };
                cx.emit(LspStoreEvent::Notification(message.into()));
                cx.notify();
            }).log_err();
        }));
        cx.notify();
        true
    }

    #[cfg(feature = "jvm-tools")]
    fn invalidate_remote_jvm_consumer_intent(&mut self) {
        self.withdraw_remote_jvm_consumer_intent();
        if let LspStoreMode::Remote(remote) = &mut self.mode {
            remote.jvm_consumers.connected = false;
            remote.jvm_consumers.requested_roots = None;
            remote.jvm_consumers.accepted_roots.clear();
            drop(remote.jvm_consumers.request_task.take());
        }
    }

    #[cfg(feature = "jvm-tools")]
    pub fn remote_jvm_consumer_roots(&self) -> &[ProjectPath] {
        self.as_remote()
            .map(|remote| remote.jvm_consumers.accepted_roots.as_slice())
            .unwrap_or_default()
    }

    #[cfg(feature = "jvm-tools")]
    pub fn remote_jvm_connection_state_changed(&mut self, connected: bool, cx: &mut Context<Self>) {
        self.invalidate_remote_jvm_consumer_intent();
        if connected {
            if let LspStoreMode::Remote(remote) = &mut self.mode {
                remote.jvm_consumers.connected = true;
            }
            self.reconcile_remote_jvm_consumer_intent(true, cx);
        }
        cx.notify();
    }

    #[cfg(feature = "jvm-tools")]
    pub fn set_default_jvm_project_languages_enabled(
        &mut self,
        enabled: bool,
        cx: &mut Context<Self>,
    ) -> Result<()> {
        anyhow::ensure!(
            !enabled || !self.isolated_recipe_test,
            "Default project language tooling is unavailable in this isolated execution profile"
        );
        anyhow::ensure!(
            !enabled || TrustedWorktrees::try_get_global(cx).is_some(),
            "Default project language tooling requires the project host trust service; reopen the project after restoring it"
        );
        if let LspStoreMode::Remote(remote) = &mut self.mode {
            ensure!(
                !enabled
                    || remote
                        .upstream_client
                        .as_ref()
                        .is_some_and(|client| !client.is_via_collab()),
                "Default JVM project tooling requires a direct host connection; relayed collaboration is unavailable"
            );
            remote.jvm_consumers.enabled = enabled;
            self.reconcile_remote_jvm_consumer_intent(true, cx);
            return Ok(());
        }
        let local = self
            .as_local_mut()
            .context("Default project language tooling requires the current project host")?;
        local.default_jvm_project_languages_enabled = enabled;
        self.refresh_server_tree(cx);
        Ok(())
    }

    #[cfg(feature = "jvm-tools")]
    fn apply_default_jvm_project_language(
        &mut self,
        language: Arc<Language>,
        cx: &App,
    ) -> Result<()> {
        let local = self
            .as_local_mut()
            .context("Default project language tooling requires the current project host")?;
        anyhow::ensure!(
            local.default_jvm_project_languages_enabled
                && !local.all_language_servers_stopped
                && TrustedWorktrees::try_get_global(cx).is_some(),
            "Default project language tooling is no longer enabled; refresh the current project"
        );
        let roots = local.default_jvm_build_roots(cx)?;
        if roots.is_empty() {
            return Ok(());
        }
        anyhow::ensure!(
            !local.languages.lsp_adapters(&language.name()).is_empty(),
            "No Java language server provider is available; enable or install its extension and restart language servers"
        );
        let keys = roots
            .into_iter()
            .map(|root| (root, language.name()))
            .collect::<BTreeSet<_>>();
        anyhow::ensure!(
            local
                .registered_project_languages
                .keys()
                .chain(keys.iter())
                .collect::<BTreeSet<_>>()
                .len()
                <= 256,
            "Default project language tooling has reached its root limit; unlink unused roots or narrow JVM build-file selections and refresh"
        );
        for key in keys {
            local
                .registered_project_languages
                .entry(key)
                .and_modify(|consumer| {
                    consumer.language = language.clone();
                    consumer.default_jvm = true;
                })
                .or_insert(ProjectLanguageConsumer {
                    language: language.clone(),
                    explicit: false,
                    default_jvm: true,
                    remote_jvm: None,
                });
        }
        Ok(())
    }

    #[cfg(feature = "jvm-tools")]
    fn reconcile_default_jvm_project_languages(&mut self, cx: &mut Context<Self>) {
        let isolated = self.isolated_recipe_test;
        let Some(local) = self.as_local_mut() else {
            return;
        };
        local.default_jvm_language_task = None;
        local.clear_default_jvm_consumers();
        if isolated
            || !local.default_jvm_project_languages_enabled
            || local.all_language_servers_stopped
        {
            return;
        }
        if TrustedWorktrees::try_get_global(cx).is_none() {
            local.report_default_jvm_startup_error(
                "Default project language tooling requires the project host trust service; reopen the project after restoring it",
            );
            return;
        }
        match local.default_jvm_build_roots(cx) {
            Ok(roots) if roots.is_empty() => return,
            Ok(_) => {}
            Err(error) => {
                local.report_default_jvm_startup_error(&error.to_string());
                return;
            }
        }
        if local
            .languages
            .available_language_for_name("Java")
            .is_none()
        {
            local.report_default_jvm_startup_error(
                "Java language is unavailable; enable or install its extension and restart language servers",
            );
            return;
        }
        let mut loading = Box::pin(local.languages.language_for_name("Java"));
        if let Some(result) = loading.as_mut().now_or_never() {
            match result {
                Ok(language) => {
                    if let Err(error) = self.apply_default_jvm_project_language(language, cx)
                        && let Some(local) = self.as_local()
                    {
                        local.report_default_jvm_startup_error(&error.to_string());
                    }
                }
                Err(_) => {
                    local.report_default_jvm_startup_error(
                        "Java language could not be loaded; enable its extension and restart language servers",
                    );
                }
            }
        } else {
            local.default_jvm_language_task = Some(cx.spawn(async move |this, cx| {
                let result = loading.await;
                this.update(cx, |store, cx| {
                    if !store.as_local().is_some_and(|local| local.default_jvm_project_languages_enabled && !local.all_language_servers_stopped) {
                        return;
                    }
                    match result {
                        Ok(language) => {
                            if let Err(error) = store.apply_default_jvm_project_language(language, cx) {
                                if let Some(local) = store.as_local() {
                                    local.report_default_jvm_startup_error(&error.to_string());
                                }
                            } else {
                                store.refresh_server_tree(cx);
                            }
                        }
                        Err(_) => {
                            if let Some(local) = store.as_local() {
                                local.report_default_jvm_startup_error(
                                    "Java language could not be loaded; enable its extension and restart language servers",
                                );
                            }
                        }
                    }
                }).log_err();
            }));
        }
    }

    #[cfg(feature = "jvm-tools")]
    pub fn register_project_language(
        &mut self,
        root: ProjectPath,
        language: Arc<Language>,
        cx: &mut Context<Self>,
    ) -> Result<()> {
        anyhow::ensure!(
            !self.isolated_recipe_test,
            "Project language tooling is unavailable in this isolated execution profile"
        );
        anyhow::ensure!(
            TrustedWorktrees::try_get_global(cx).is_some(),
            "Project language tooling requires the project host trust service; reopen the project after restoring it"
        );
        let local = self.as_local_mut().context(
            "Project language tooling must be registered on the project host; remote startup is unavailable",
        )?;
        anyhow::ensure!(
            local.project_language_root_is_current(&root, cx),
            "Project language tooling requires a current visible local directory; reopen or refresh the project root"
        );
        anyhow::ensure!(
            !local.languages.lsp_adapters(&language.name()).is_empty(),
            "No language server provider is available for this project language; enable or install its extension and retry"
        );
        let key = (root, language.name());
        anyhow::ensure!(
            local.registered_project_languages.contains_key(&key)
                || local.registered_project_languages.len() < 256,
            "Project language tooling has reached its root limit; unlink unused project roots and retry"
        );
        local
            .registered_project_languages
            .entry(key)
            .and_modify(|consumer| {
                consumer.language = language.clone();
                consumer.explicit = true;
            })
            .or_insert(ProjectLanguageConsumer {
                language,
                explicit: true,
                default_jvm: false,
                remote_jvm: None,
            });
        self.refresh_server_tree(cx);
        Ok(())
    }

    #[cfg(feature = "jvm-tools")]
    pub fn unregister_project_language(
        &mut self,
        root: &ProjectPath,
        language: &LanguageName,
        cx: &mut Context<Self>,
    ) -> Result<()> {
        let local = self
            .as_local_mut()
            .context("Project language tooling must be unregistered on the project host")?;
        if let Some(consumer) = local
            .registered_project_languages
            .get_mut(&(root.clone(), language.clone()))
        {
            consumer.explicit = false;
        }
        local.registered_project_languages.retain(|_, consumer| {
            consumer.explicit || consumer.default_jvm || consumer.remote_jvm.is_some()
        });
        self.refresh_server_tree(cx);
        Ok(())
    }

    fn refresh_server_tree(&mut self, cx: &mut Context<Self>) {
        #[cfg(feature = "jvm-tools")]
        self.reconcile_remote_jvm_project_languages(cx);
        #[cfg(feature = "jvm-tools")]
        self.reconcile_default_jvm_project_languages(cx);
        let buffer_store = self.buffer_store.clone();
        let Some(local) = self.as_local_mut() else {
            return;
        };
        if local.all_language_servers_stopped {
            return;
        }
        let stopped_language_servers = local.stopped_language_servers.clone();
        let mut adapters = BTreeMap::default();
        let get_adapter = {
            let languages = local.languages.clone();
            let environment = local.environment.clone();
            let weak = local.weak.clone();
            let worktree_store = local.worktree_store.clone();
            let http_client = local.http_client.clone();
            let fs = local.fs.clone();
            move |worktree_id, cx: &mut App| {
                let worktree = worktree_store.read(cx).worktree_for_id(worktree_id, cx)?;
                Some(LocalLspAdapterDelegate::new(
                    languages.clone(),
                    &environment,
                    weak.clone(),
                    &worktree,
                    http_client.clone(),
                    fs.clone(),
                    cx,
                ))
            }
        };

        let mut messages_to_report = Vec::new();
        let (new_tree, to_stop) = {
            let mut rebase = local.lsp_tree.rebase();
            let mut consumers = buffer_store
                .read(cx)
                .buffers()
                .filter_map(|buffer| {
                    let raw_buffer = buffer.read(cx);
                    if !local
                        .registered_buffers
                        .contains_key(&raw_buffer.remote_id())
                    {
                        return None;
                    }
                    let file = File::from_dyn(raw_buffer.file()).cloned()?;
                    let language = raw_buffer.language().cloned()?;
                    let path = file
                        .path()
                        .parent()
                        .map(Arc::from)
                        .unwrap_or_else(|| file.path().clone());
                    Some((
                        ProjectPath {
                            worktree_id: file.worktree_id(cx),
                            path,
                        },
                        language,
                        Some((file.abs_path(cx), raw_buffer.remote_id())),
                        file.worktree.read(cx).is_visible(),
                    ))
                })
                .collect::<Vec<_>>();
            #[cfg(feature = "jvm-tools")]
            {
                let current_roots = local
                    .registered_project_languages
                    .keys()
                    .filter(|(root, _)| local.project_language_root_is_current(root, cx))
                    .cloned()
                    .collect::<HashSet<_>>();
                local
                    .registered_project_languages
                    .retain(|key, _| current_roots.contains(key));
                if TrustedWorktrees::try_get_global(cx).is_some() {
                    consumers.extend(local.registered_project_languages.iter().map(
                        |((root, _), consumer)| {
                            (root.clone(), consumer.language.clone(), None, true)
                        },
                    ));
                }
            }
            consumers.sort_by_key(|(_, _, _, visible)| Reverse(*visible));
            for (worktree_path, language, buffer_registration, _) in consumers {
                let worktree_id = worktree_path.worktree_id;
                let Some(worktree) = local
                    .worktree_store
                    .read(cx)
                    .worktree_for_id(worktree_id, cx)
                else {
                    continue;
                };

                if let Some((_, apply)) = local.reuse_existing_language_server(
                    rebase.server_tree(),
                    &worktree,
                    &language.name(),
                    cx,
                ) {
                    (apply)(rebase.server_tree());
                } else if let Some(lsp_delegate) = adapters
                    .entry(worktree_id)
                    .or_insert_with(|| get_adapter(worktree_id, cx))
                    .clone()
                {
                    let delegate =
                        Arc::new(ManifestQueryDelegate::new(worktree.read(cx).snapshot()));
                    let nodes = rebase
                        .walk(
                            worktree_path,
                            language.name(),
                            language.manifest(),
                            delegate.clone(),
                            cx,
                        )
                        .collect::<Vec<_>>();
                    for node in nodes {
                        if let Some(name) = node.name()
                            && stopped_language_servers.contains(&name)
                        {
                            continue;
                        }
                        let server_id = node.server_id_or_init(|disposition| {
                            let path = &disposition.path;
                            let uri = Uri::from_file_path(worktree.read(cx).absolutize(&path.path));
                            let key = LanguageServerSeed {
                                worktree_id,
                                name: disposition.server_name.clone(),
                                settings: LanguageServerSeedSettings {
                                    binary: disposition.settings.binary.clone(),
                                    initialization_options: disposition
                                        .settings
                                        .initialization_options
                                        .clone(),
                                    #[cfg(feature = "jvm-tools")]
                                    jvm_startup: disposition.jvm_startup.clone(),
                                },
                                toolchain: local.toolchain_store.read(cx).active_toolchain(
                                    path.worktree_id,
                                    &path.path,
                                    language.name(),
                                ),
                            };
                            local.language_server_ids.remove(&key);

                            let server_id = local.get_or_insert_language_server(
                                &worktree,
                                lsp_delegate.clone(),
                                disposition,
                                &language.name(),
                                cx,
                            );
                            if let Some(state) = local.language_servers.get(&server_id)
                                && let Ok(uri) = uri
                            {
                                state.add_workspace_folder(uri);
                            };
                            server_id
                        });

                        if let Some(language_server_id) = server_id
                            && let Some((abs_path, buffer_id)) = &buffer_registration
                        {
                            messages_to_report.push(LspStoreEvent::LanguageServerUpdate {
                                language_server_id,
                                name: node.name(),
                                message:
                                    proto::update_language_server::Variant::RegisteredForBuffer(
                                        proto::RegisteredForBuffer {
                                            buffer_abs_path: abs_path
                                                .to_string_lossy()
                                                .into_owned(),
                                            buffer_id: buffer_id.to_proto(),
                                        },
                                    ),
                            });
                        }
                    }
                } else {
                    continue;
                }
            }
            rebase.finish()
        };
        for message in messages_to_report {
            cx.emit(message);
        }
        local.lsp_tree = new_tree;
        for (id, _) in to_stop {
            self.stop_local_language_server(id, cx).detach();
        }
    }

    pub fn apply_code_action(
        &self,
        buffer_handle: Entity<Buffer>,
        mut action: CodeAction,
        push_to_history: bool,
        cx: &mut Context<Self>,
    ) -> Task<Result<ProjectTransaction>> {
        if let Some((upstream_client, project_id)) = self.upstream_client() {
            let request = proto::ApplyCodeAction {
                project_id,
                buffer_id: buffer_handle.read(cx).remote_id().into(),
                action: Some(Self::serialize_code_action(&action)),
            };
            let buffer_store = self.buffer_store();
            cx.spawn(async move |_, cx| {
                let response = upstream_client
                    .request(request)
                    .await?
                    .transaction
                    .context("missing transaction")?;

                buffer_store
                    .update(cx, |buffer_store, cx| {
                        buffer_store.deserialize_project_transaction(response, push_to_history, cx)
                    })
                    .await
            })
        } else if self.mode.is_local() {
            let Some((_, lang_server, request_timeout)) = buffer_handle.update(cx, |buffer, cx| {
                let request_timeout = ProjectSettings::get_global(cx)
                    .global_lsp_settings
                    .get_request_timeout();
                self.language_server_for_local_buffer(buffer, action.server_id, cx)
                    .map(|(adapter, server)| (adapter.clone(), server.clone(), request_timeout))
            }) else {
                return Task::ready(Ok(ProjectTransaction::default()));
            };

            cx.spawn(async move |this, cx| {
                LocalLspStore::try_resolve_code_action(&lang_server, &mut action, request_timeout)
                    .await
                    .context("resolving a code action")?;
                if let Some(edit) = action.lsp_action.edit()
                    && (edit.changes.is_some() || edit.document_changes.is_some())
                {
                    return LocalLspStore::deserialize_workspace_edit(
                        this.upgrade().context("no app present")?,
                        edit.clone(),
                        push_to_history,
                        lang_server.clone(),
                        cx,
                    )
                    .await;
                }

                let Some(command) = action.lsp_action.command() else {
                    return Ok(ProjectTransaction::default());
                };

                let server_capabilities = lang_server.capabilities();
                let available_commands = server_capabilities
                    .execute_command_provider
                    .as_ref()
                    .map(|options| options.commands.as_slice())
                    .unwrap_or_default();

                if !available_commands.contains(&command.command) {
                    log::debug!(
                        "Skipping executeCommand for {}, not listed in language server capabilities",
                        command.command
                    );
                    return Ok(ProjectTransaction::default());
                }

                let request_timeout = cx.update(|app| {
                    ProjectSettings::get_global(app)
                        .global_lsp_settings
                        .get_request_timeout()
                });

                this.update(cx, |this, _| {
                    this.as_local_mut()
                        .unwrap()
                        .last_workspace_edits_by_language_server
                        .remove(&lang_server.server_id());
                })?;

                let _result = lang_server
                    .request::<lsp::request::ExecuteCommand>(
                        lsp::ExecuteCommandParams {
                            command: command.command.clone(),
                            arguments: command.arguments.clone().unwrap_or_default(),
                            ..lsp::ExecuteCommandParams::default()
                        },
                        request_timeout,
                    )
                    .await
                    .into_response()
                    .context("execute command")?;

                return this.update(cx, |this, _| {
                    this.as_local_mut()
                        .unwrap()
                        .last_workspace_edits_by_language_server
                        .remove(&lang_server.server_id())
                        .unwrap_or_default()
                });
            })
        } else {
            Task::ready(Err(anyhow!("no upstream client and not local")))
        }
    }

    pub fn resolve_code_action(
        &self,
        buffer: &Entity<Buffer>,
        mut action: CodeAction,
        cx: &mut Context<Self>,
    ) -> Task<Result<CodeAction>> {
        if action.resolved {
            return Task::ready(Ok(action));
        }
        if let Some((upstream_client, project_id)) = self.upstream_client() {
            let request = proto::ResolveCodeAction {
                project_id,
                buffer_id: buffer.read(cx).remote_id().into(),
                action: Some(Self::serialize_code_action(&action)),
            };
            cx.background_spawn(async move {
                let response = upstream_client
                    .request(request)
                    .await
                    .context("resolve code action proto request")?;
                let action = response.action.context("missing resolved action")?;
                Self::deserialize_code_action(action)
            })
        } else if self.mode.is_local() {
            let server_id = action.server_id;
            let Some(lang_server) = buffer.update(cx, |buffer, cx| {
                self.language_server_for_local_buffer(buffer, server_id, cx)
                    .map(|(_, server)| server.clone())
            }) else {
                return Task::ready(Ok(action));
            };
            let request_timeout = ProjectSettings::get_global(cx)
                .global_lsp_settings
                .get_request_timeout();
            cx.background_spawn(async move {
                LocalLspStore::try_resolve_code_action(&lang_server, &mut action, request_timeout)
                    .await
                    .context("resolving a code action")?;
                Ok(action)
            })
        } else {
            Task::ready(Err(anyhow!("no upstream client and not local")))
        }
    }

    pub(super) async fn handle_resolve_code_action(
        lsp_store: Entity<Self>,
        envelope: TypedEnvelope<proto::ResolveCodeAction>,
        mut cx: AsyncApp,
    ) -> Result<proto::ResolveCodeActionResponse> {
        let action =
            Self::deserialize_code_action(envelope.payload.action.context("invalid action")?)?;
        let buffer = lsp_store.update(&mut cx, |lsp_store, cx| {
            let buffer_id = BufferId::new(envelope.payload.buffer_id)?;
            lsp_store.buffer_store.read(cx).get_existing(buffer_id)
        })?;
        let resolved = lsp_store
            .update(&mut cx, |lsp_store, cx| {
                lsp_store.resolve_code_action(&buffer, action, cx)
            })
            .await
            .context("resolving code action")?;
        Ok(proto::ResolveCodeActionResponse {
            action: Some(Self::serialize_code_action(&resolved)),
        })
    }

    pub fn apply_code_action_kind(
        &mut self,
        buffers: HashSet<Entity<Buffer>>,
        kind: CodeActionKind,
        push_to_history: bool,
        cx: &mut Context<Self>,
    ) -> Task<anyhow::Result<ProjectTransaction>> {
        if self.as_local().is_some() {
            cx.spawn(async move |lsp_store, cx| {
                let buffers = buffers.into_iter().collect::<Vec<_>>();
                let result = LocalLspStore::execute_code_action_kind_locally(
                    lsp_store.clone(),
                    buffers,
                    kind,
                    push_to_history,
                    cx,
                )
                .await;
                lsp_store.update(cx, |lsp_store, _| {
                    lsp_store.update_last_formatting_failure(&result);
                })?;
                result
            })
        } else if let Some((client, project_id)) = self.upstream_client() {
            let buffer_store = self.buffer_store();
            cx.spawn(async move |lsp_store, cx| {
                let result = client
                    .request(proto::ApplyCodeActionKind {
                        project_id,
                        kind: kind.as_str().to_owned(),
                        buffer_ids: buffers
                            .iter()
                            .map(|buffer| {
                                buffer.read_with(cx, |buffer, _| buffer.remote_id().into())
                            })
                            .collect(),
                    })
                    .await
                    .and_then(|result| result.transaction.context("missing transaction"));
                lsp_store.update(cx, |lsp_store, _| {
                    lsp_store.update_last_formatting_failure(&result);
                })?;

                let transaction_response = result?;
                buffer_store
                    .update(cx, |buffer_store, cx| {
                        buffer_store.deserialize_project_transaction(
                            transaction_response,
                            push_to_history,
                            cx,
                        )
                    })
                    .await
            })
        } else {
            Task::ready(Ok(ProjectTransaction::default()))
        }
    }

    pub fn resolved_hint(
        &mut self,
        buffer_id: BufferId,
        id: InlayId,
        cx: &mut Context<Self>,
    ) -> Option<ResolvedHint> {
        let buffer = self.buffer_store.read(cx).get(buffer_id)?;

        let lsp_data = self.lsp_data.get_mut(&buffer_id)?;
        let buffer_lsp_hints = &mut lsp_data.inlay_hints;
        let hint = buffer_lsp_hints.hint_for_id(id)?.clone();
        let (server_id, resolve_data) = match &hint.resolve_state {
            ResolveState::Resolved => return Some(ResolvedHint::Resolved(hint)),
            ResolveState::Resolving => {
                return Some(ResolvedHint::Resolving(
                    buffer_lsp_hints.hint_resolves.get(&id)?.clone(),
                ));
            }
            ResolveState::CanResolve(server_id, resolve_data) => (*server_id, resolve_data.clone()),
        };

        let resolve_task = self.resolve_inlay_hint(hint, buffer, server_id, cx);
        let buffer_lsp_hints = &mut self.lsp_data.get_mut(&buffer_id)?.inlay_hints;
        let previous_task = buffer_lsp_hints.hint_resolves.insert(
            id,
            cx.spawn(async move |lsp_store, cx| {
                let resolved_hint = resolve_task.await;
                lsp_store
                    .update(cx, |lsp_store, _| {
                        if let Some(old_inlay_hint) = lsp_store
                            .lsp_data
                            .get_mut(&buffer_id)
                            .and_then(|buffer_lsp_data| buffer_lsp_data.inlay_hints.hint_for_id(id))
                        {
                            match resolved_hint {
                                Ok(resolved_hint) => {
                                    *old_inlay_hint = resolved_hint;
                                }
                                Err(e) => {
                                    old_inlay_hint.resolve_state =
                                        ResolveState::CanResolve(server_id, resolve_data);
                                    log::error!("Inlay hint resolve failed: {e:#}");
                                }
                            }
                        }
                    })
                    .ok();
            })
            .shared(),
        );
        debug_assert!(
            previous_task.is_none(),
            "Did not change hint's resolve state after spawning its resolve"
        );
        buffer_lsp_hints.hint_for_id(id)?.resolve_state = ResolveState::Resolving;
        None
    }

    pub(crate) fn linked_edits(
        &mut self,
        buffer: &Entity<Buffer>,
        position: Anchor,
        cx: &mut Context<Self>,
    ) -> Task<Result<Vec<Range<Anchor>>>> {
        let snapshot = buffer.read(cx).snapshot();
        let scope = snapshot.language_scope_at(position);
        let Some(server_id) = self
            .as_local()
            .and_then(|local| {
                buffer.update(cx, |buffer, cx| {
                    local
                        .language_servers_for_buffer(buffer, cx)
                        .filter(|(_, server)| {
                            LinkedEditingRange::check_server_capabilities(server.capabilities())
                        })
                        .filter(|(adapter, _)| {
                            scope
                                .as_ref()
                                .map(|scope| scope.language_allowed(&adapter.name))
                                .unwrap_or(true)
                        })
                        .map(|(_, server)| LanguageServerToQuery::Other(server.server_id()))
                        .next()
                })
            })
            .or_else(|| {
                self.upstream_client()
                    .is_some()
                    .then_some(LanguageServerToQuery::FirstCapable)
            })
            .filter(|_| {
                maybe!({
                    buffer.read(cx).language_at(position)?;
                    Some(
                        LanguageSettings::for_buffer_at(&buffer.read(cx), position, cx)
                            .linked_edits,
                    )
                }) == Some(true)
            })
        else {
            return Task::ready(Ok(Vec::new()));
        };

        self.request_lsp(
            buffer.clone(),
            server_id,
            LinkedEditingRange { position },
            cx,
        )
    }

    fn apply_on_type_formatting(
        &mut self,
        buffer: Entity<Buffer>,
        position: Anchor,
        trigger: String,
        cx: &mut Context<Self>,
    ) -> Task<Result<Option<Transaction>>> {
        if let Some((client, project_id)) = self.upstream_client() {
            if !self.check_if_capable_for_proto_request(
                &buffer,
                |capabilities| {
                    OnTypeFormatting::supports_on_type_formatting(&trigger, capabilities)
                },
                cx,
            ) {
                return Task::ready(Ok(None));
            }
            let request = proto::OnTypeFormatting {
                project_id,
                buffer_id: buffer.read(cx).remote_id().into(),
                position: Some(serialize_anchor(&position)),
                trigger,
                version: serialize_version(&buffer.read(cx).version()),
            };
            cx.background_spawn(async move {
                client
                    .request(request)
                    .await?
                    .transaction
                    .map(language::proto::deserialize_transaction)
                    .transpose()
            })
        } else if let Some(local) = self.as_local_mut() {
            let buffer_id = buffer.read(cx).remote_id();
            local.buffers_being_formatted.insert(buffer_id);
            cx.spawn(async move |this, cx| {
                let _cleanup = defer({
                    let this = this.clone();
                    let mut cx = cx.clone();
                    move || {
                        this.update(&mut cx, |this, _| {
                            if let Some(local) = this.as_local_mut() {
                                local.buffers_being_formatted.remove(&buffer_id);
                            }
                        })
                        .ok();
                    }
                });

                buffer
                    .update(cx, |buffer, _| {
                        buffer.wait_for_edits(Some(position.timestamp()))
                    })
                    .await?;
                this.update(cx, |this, cx| {
                    let position = position.to_point_utf16(buffer.read(cx));
                    this.on_type_format(buffer, position, trigger, false, cx)
                })?
                .await
            })
        } else {
            Task::ready(Err(anyhow!("No upstream client or local language server")))
        }
    }

    pub fn on_type_format<T: ToPointUtf16>(
        &mut self,
        buffer: Entity<Buffer>,
        position: T,
        trigger: String,
        push_to_history: bool,
        cx: &mut Context<Self>,
    ) -> Task<Result<Option<Transaction>>> {
        let position = position.to_point_utf16(buffer.read(cx));
        self.on_type_format_impl(buffer, position, trigger, push_to_history, cx)
    }

    fn on_type_format_impl(
        &mut self,
        buffer: Entity<Buffer>,
        position: PointUtf16,
        trigger: String,
        push_to_history: bool,
        cx: &mut Context<Self>,
    ) -> Task<Result<Option<Transaction>>> {
        let options = buffer.update(cx, |buffer, cx| {
            lsp_command::lsp_formatting_options(
                LanguageSettings::for_buffer_at(buffer, position, cx).as_ref(),
            )
        });

        cx.spawn(async move |this, cx| {
            if let Some(waiter) =
                buffer.update(cx, |buffer, _| buffer.wait_for_autoindent_applied())
            {
                waiter.await?;
            }
            cx.update(|cx| {
                this.update(cx, |this, cx| {
                    this.request_lsp(
                        buffer.clone(),
                        LanguageServerToQuery::FirstCapable,
                        OnTypeFormatting {
                            position,
                            trigger,
                            options,
                            push_to_history,
                        },
                        cx,
                    )
                })
            })?
            .await
        })
    }

    pub fn definitions(
        &mut self,
        buffer: &Entity<Buffer>,
        position: PointUtf16,
        cx: &mut Context<Self>,
    ) -> Task<Result<Option<Vec<LocationLink>>>> {
        if let Some((upstream_client, project_id)) = self.upstream_client() {
            let request = GetDefinitions { position };
            if !self.is_capable_for_proto_request(buffer, &request, cx) {
                return Task::ready(Ok(None));
            }

            let request_timeout = ProjectSettings::get_global(cx)
                .global_lsp_settings
                .get_request_timeout();

            let request_task = upstream_client.request_lsp(
                project_id,
                None,
                request_timeout,
                cx.background_executor().clone(),
                request.to_proto(project_id, buffer.read(cx)),
            );
            let buffer = buffer.clone();
            cx.spawn(async move |weak_lsp_store, cx| {
                let Some(lsp_store) = weak_lsp_store.upgrade() else {
                    return Ok(None);
                };
                let Some(responses) = request_task.await? else {
                    return Ok(None);
                };
                let actions = join_all(responses.payload.into_iter().map(|response| {
                    GetDefinitions { position }.response_from_proto(
                        response.response,
                        lsp_store.clone(),
                        buffer.clone(),
                        cx.clone(),
                    )
                }))
                .await;

                Ok(Some(
                    actions
                        .into_iter()
                        .collect::<Result<Vec<Vec<_>>>>()?
                        .into_iter()
                        .flatten()
                        .dedup()
                        .collect(),
                ))
            })
        } else {
            let definitions_task = self.request_multiple_lsp_locally(
                buffer,
                Some(position),
                GetDefinitions { position },
                cx,
            );
            cx.background_spawn(async move {
                Ok(Some(
                    definitions_task
                        .await
                        .into_iter()
                        .flat_map(|(_, definitions)| definitions)
                        .dedup()
                        .collect(),
                ))
            })
        }
    }

    fn edit_prediction_definitions_for_command<C>(
        &mut self,
        buffer: &Entity<Buffer>,
        request: C,
        position: PointUtf16,
        cx: &mut Context<Self>,
    ) -> Task<Result<Vec<EditPredictionDefinition>>>
    where
        C: LspCommand<Response = Vec<EditPredictionDefinition>> + Clone,
        C::ProtoRequest: proto::LspRequestMessage,
        <C::ProtoRequest as proto::LspRequestMessage>::Response:
            Into<<C::ProtoRequest as proto::RequestMessage>::Response>,
        <C::LspRequest as lsp::request::Request>::Result: Send,
        <C::LspRequest as lsp::request::Request>::Params: Send,
    {
        if let Some((upstream_client, project_id)) = self.upstream_client() {
            if !self.is_capable_for_proto_request(buffer, &request, cx) {
                return Task::ready(Ok(Vec::new()));
            }

            let request_timeout = ProjectSettings::get_global(cx)
                .global_lsp_settings
                .get_request_timeout();

            let request_task = upstream_client.request_lsp(
                project_id,
                None,
                request_timeout,
                cx.background_executor().clone(),
                request.to_proto(project_id, buffer.read(cx)),
            );
            let buffer = buffer.clone();
            cx.spawn(async move |weak_lsp_store, cx| {
                let Some(lsp_store) = weak_lsp_store.upgrade() else {
                    return Ok(Vec::new());
                };
                let Some(responses) = request_task.await? else {
                    return Ok(Vec::new());
                };
                let actions = join_all(responses.payload.into_iter().map(|response| {
                    request.clone().response_from_proto(
                        response.response.into(),
                        lsp_store.clone(),
                        buffer.clone(),
                        cx.clone(),
                    )
                }))
                .await;

                Ok(actions
                    .into_iter()
                    .collect::<Result<Vec<Vec<_>>>>()?
                    .into_iter()
                    .flatten()
                    .collect())
            })
        } else {
            let definitions_task =
                self.request_multiple_lsp_locally(buffer, Some(position), request, cx);
            cx.background_spawn(async move {
                Ok(definitions_task
                    .await
                    .into_iter()
                    .flat_map(|(_, definitions)| definitions)
                    .collect())
            })
        }
    }

    pub fn edit_prediction_definitions(
        &mut self,
        buffer: &Entity<Buffer>,
        position: PointUtf16,
        include_type_definitions: bool,
        cx: &mut Context<Self>,
    ) -> Task<Result<Vec<EditPredictionDefinition>>> {
        let definitions = self.edit_prediction_definitions_for_command(
            buffer,
            GetEditPredictionDefinitions { position },
            position,
            cx,
        );
        let type_definitions = include_type_definitions.then(|| {
            self.edit_prediction_definitions_for_command(
                buffer,
                GetEditPredictionTypeDefinitions { position },
                position,
                cx,
            )
        });
        cx.background_spawn(async move {
            let mut merged = definitions.await?;
            if let Some(type_definitions) = type_definitions {
                merged.extend(type_definitions.await?);
            }
            let mut seen = HashSet::default();
            merged.retain(|definition| seen.insert(definition.clone()));
            Ok(merged)
        })
    }

