    #[cfg(feature = "test-support")]
    pub fn has_language_server_seed_for_worktree(&self, worktree_id: WorktreeId) -> bool {
        self.as_local().is_some_and(|local| {
            local
                .language_server_ids
                .keys()
                .any(|seed| seed.worktree_id == worktree_id)
        })
    }

    pub(super) fn did_rename_entry(
        &self,
        worktree_id: WorktreeId,
        old_path: &Path,
        new_path: &Path,
        is_dir: bool,
    ) {
        maybe!({
            let local_store = self.as_local()?;

            let old_uri = lsp::Uri::from_file_path(old_path)
                .ok()
                .map(|uri| uri.to_string())?;
            let new_uri = lsp::Uri::from_file_path(new_path)
                .ok()
                .map(|uri| uri.to_string())?;

            for language_server in local_store.language_servers_for_worktree(worktree_id) {
                let Some(filter) = local_store
                    .language_server_paths_watched_for_rename
                    .get(&language_server.server_id())
                else {
                    continue;
                };

                if filter.should_send_did_rename(&old_uri, is_dir) {
                    language_server
                        .notify::<DidRenameFiles>(RenameFilesParams {
                            files: vec![FileRename {
                                old_uri: old_uri.clone(),
                                new_uri: new_uri.clone(),
                            }],
                        })
                        .ok();
                }
            }
            Some(())
        });
    }

    pub(super) fn will_rename_entry(
        this: WeakEntity<Self>,
        worktree_id: WorktreeId,
        old_path: &Path,
        new_path: &Path,
        is_dir: bool,
        cx: AsyncApp,
    ) -> Task<ProjectTransaction> {
        let old_uri = lsp::Uri::from_file_path(old_path)
            .ok()
            .map(|uri| uri.to_string());
        let new_uri = lsp::Uri::from_file_path(new_path)
            .ok()
            .map(|uri| uri.to_string());
        cx.spawn(async move |cx| {
            let mut tasks = vec![];
            this.update(cx, |this, cx| {
                let local_store = this.as_local()?;
                let old_uri = old_uri?;
                let new_uri = new_uri?;
                for language_server in local_store.language_servers_for_worktree(worktree_id) {
                    let Some(filter) = local_store
                        .language_server_paths_watched_for_rename
                        .get(&language_server.server_id())
                    else {
                        continue;
                    };

                    if !filter.should_send_will_rename(&old_uri, is_dir) {
                        continue;
                    }
                    let request_timeout = ProjectSettings::get_global(cx)
                        .global_lsp_settings
                        .get_request_timeout();

                    let apply_edit = cx.spawn({
                        let old_uri = old_uri.clone();
                        let new_uri = new_uri.clone();
                        let language_server = language_server.clone();
                        async move |this, cx| {
                            let edit = language_server
                                .request::<WillRenameFiles>(
                                    RenameFilesParams {
                                        files: vec![FileRename { old_uri, new_uri }],
                                    },
                                    request_timeout,
                                )
                                .await
                                .into_response()
                                .context("will rename files")
                                .log_err()
                                .flatten()?;

                            LocalLspStore::deserialize_workspace_edit(
                                this.upgrade()?,
                                edit,
                                false,
                                language_server.clone(),
                                cx,
                            )
                            .await
                            .ok()
                        }
                    });
                    tasks.push(apply_edit);
                }
                Some(())
            })
            .ok()
            .flatten();
            let mut merged_transaction = ProjectTransaction::default();
            for task in tasks {
                // Await on tasks sequentially so that the order of application of edits is deterministic
                // (at least with regards to the order of registration of language servers)
                if let Some(transaction) = task.await {
                    for (buffer, buffer_transaction) in transaction.0 {
                        merged_transaction.0.insert(buffer, buffer_transaction);
                    }
                }
            }
            merged_transaction
        })
    }

    fn lsp_notify_abs_paths_changed(
        &mut self,
        server_id: LanguageServerId,
        changes: Vec<PathEvent>,
    ) {
        maybe!({
            let server = self.language_server_for_id(server_id)?;
            let changes = changes
                .into_iter()
                .filter_map(|event| {
                    let typ = match event.kind? {
                        PathEventKind::Created => lsp::FileChangeType::CREATED,
                        PathEventKind::Removed => lsp::FileChangeType::DELETED,
                        PathEventKind::Changed | PathEventKind::Rescan => {
                            lsp::FileChangeType::CHANGED
                        }
                    };
                    Some(lsp::FileEvent {
                        uri: file_path_to_lsp_url(&event.path).log_err()?,
                        typ,
                    })
                })
                .collect::<Vec<_>>();
            if !changes.is_empty() {
                server
                    .notify::<lsp::notification::DidChangeWatchedFiles>(
                        lsp::DidChangeWatchedFilesParams { changes },
                    )
                    .ok();
            }
            Some(())
        });
    }

    pub fn language_server_for_id(&self, id: LanguageServerId) -> Option<Arc<LanguageServer>> {
        self.as_local()?.language_server_for_id(id)
    }

    #[cfg(feature = "jvm-tools")]
    fn host_jvm_snapshot_provider(
        &self,
        project_id: u64,
        worktree_id: WorktreeId,
        provider_name: &'static str,
        label: &'static str,
        cx: &mut App,
    ) -> Result<(
        LanguageServerId,
        Arc<LanguageServer>,
        Entity<Worktree>,
        Duration,
    )> {
        ensure!(
            self.as_local().is_some(),
            "{label} snapshot requires a host"
        );
        ensure!(
            self.downstream_client
                .as_ref()
                .is_some_and(|(_, downstream_project_id)| *downstream_project_id == project_id),
            "{label} snapshot belongs to a different project"
        );
        let worktree = self
            .worktree_store
            .read(cx)
            .worktree_for_id(worktree_id, cx)
            .with_context(|| format!("{label} worktree is unavailable"))?;
        ensure!(
            worktree.read(cx).is_local() && worktree.read(cx).is_visible(),
            "{label} worktree is unavailable"
        );
        ensure!(
            TrustedWorktrees::try_get_global(cx).is_some_and(|trusted| {
                trusted.update(cx, |trusted, cx| {
                    trusted.can_trust(&self.worktree_store, worktree_id, cx)
                })
            }),
            "{label} worktree is restricted"
        );
        let server_id = self
            .language_server_statuses
            .iter()
            .find(|(_, status)| {
                status.name == LanguageServerName::new_static(provider_name)
                    && status.worktree == Some(worktree_id)
            })
            .map(|(server_id, _)| *server_id)
            .with_context(|| format!("{label} provider is unavailable"))?;
        let server = self
            .language_server_for_id(server_id)
            .with_context(|| format!("{label} provider is unavailable"))?;
        let request_timeout = ProjectSettings::get_global(cx)
            .global_lsp_settings
            .get_request_timeout();
        Ok((server_id, server, worktree, request_timeout))
    }

    #[cfg(feature = "jvm-tools")]
    fn ensure_host_jvm_snapshot_current(
        &self,
        project_id: u64,
        worktree_id: WorktreeId,
        original_worktree: &Entity<Worktree>,
        server_id: LanguageServerId,
        provider_name: &'static str,
        label: &'static str,
        cx: &mut App,
    ) -> Result<()> {
        let current_worktree = self
            .worktree_store
            .read(cx)
            .worktree_for_id(worktree_id, cx)
            .with_context(|| format!("{label} worktree changed during refresh"))?;
        ensure!(
            self.downstream_client
                .as_ref()
                .is_some_and(|(_, downstream_project_id)| *downstream_project_id == project_id)
                && current_worktree == *original_worktree
                && current_worktree.read(cx).is_local()
                && current_worktree.read(cx).is_visible()
                && TrustedWorktrees::try_get_global(cx).is_some_and(|trusted| {
                    trusted.update(cx, |trusted, cx| {
                        trusted.can_trust(&self.worktree_store, worktree_id, cx)
                    })
                })
                && self
                    .language_server_statuses
                    .get(&server_id)
                    .is_some_and(|status| {
                        status.name == LanguageServerName::new_static(provider_name)
                            && status.worktree == Some(worktree_id)
                    })
                && self.language_server_for_id(server_id).is_some(),
            "{label} changed during refresh"
        );
        Ok(())
    }

    #[cfg(feature = "jvm-tools")]
    async fn handle_get_jdtls_project_snapshot(
        this: Entity<Self>,
        envelope: TypedEnvelope<proto::GetJdtlsProjectSnapshot>,
        mut cx: AsyncApp,
    ) -> Result<proto::JdtlsProjectSnapshotResponse> {
        let request = envelope.payload;
        let response_limit = jvm_project::jdtls_snapshot_size_limit(request.protocol_version)?;
        let worktree_id = WorktreeId::from_proto(request.worktree_id);
        let (server_id, server, worktree, request_timeout) =
            this.update(&mut cx, |store, cx| {
                store.host_jvm_snapshot_provider(
                    request.project_id,
                    worktree_id,
                    "jdtls",
                    "Java project",
                    cx,
                )
            })?;
        let (cached_snapshot, host_generation) = this.update(&mut cx, |store, _| {
            let state = store.jdtls_projects.entry(worktree_id).or_default();
            ensure!(
                state.import_operation().is_none(),
                "Java project import is in progress; retry after it completes"
            );
            Ok((
                state
                    .snapshot()
                    .filter(|snapshot| {
                        state.snapshot_is_current() && snapshot.server_id == server_id
                    })
                    .cloned(),
                state.generation(),
            ))
        })?;
        if let Some(cached) = cached_snapshot {
            return this.update(&mut cx, |store, cx| {
                store.ensure_host_jvm_snapshot_current(
                    request.project_id,
                    worktree_id,
                    &worktree,
                    server_id,
                    "jdtls",
                    "Java project",
                    cx,
                )?;
                ensure!(
                    store
                        .jdtls_projects
                        .get(&worktree_id)
                        .is_some_and(|state| state.generation() == host_generation
                            && state.snapshot_is_current()),
                    "Java project inputs changed during refresh; retry"
                );
                let entries = worktree.read(cx).snapshot();
                let (projects, mut partial) = jvm_project::filter_provider_projects(
                    cached.projects,
                    cached.partial,
                    &entries,
                    true,
                );
                let had_selection = cached.metadata.is_some();
                let settings = ProjectSettings::get(
                    Some(SettingsLocation {
                        worktree_id,
                        path: RelPath::empty(),
                    }),
                    cx,
                );
                let maven_selection = cached
                    .metadata
                    .map(|facts| {
                        facts.admit_current_snapshot(
                            worktree_id,
                            &entries,
                            &projects,
                            settings
                                .jvm_builds
                                .as_ref()
                                .and_then(|settings| settings.maven.as_ref()),
                        )
                    })
                    .transpose()?
                    .flatten()
                    .map(|facts| {
                        facts.to_proto_for_version(
                            request.protocol_version,
                            worktree_id,
                            &entries,
                            &projects,
                        )
                    })
                    .transpose()?
                    .flatten();
                partial |= had_selection && maven_selection.is_none();
                let response = proto::JdtlsProjectSnapshotResponse {
                    protocol_version: request.protocol_version,
                    request_id: request.request_id,
                    worktree_id: request.worktree_id,
                    server_id: server_id.to_proto(),
                    projects: projects
                        .iter()
                        .map(|project| {
                            jvm_project::project_to_proto_for_version(
                                project,
                                request.protocol_version,
                            )
                        })
                        .collect::<Result<Vec<_>>>()?,
                    partial,
                    maven_selection,
                };
                ensure!(
                    response.encoded_len() <= response_limit,
                    "Java project snapshot exceeds the remote size limit"
                );
                Ok(response)
            });
        }
        let background_executor = cx.background_executor().clone();
        let (maven_root, imported_build_root) = this.read_with(&cx, |_, cx| {
            let worktree = worktree.read(cx);
            let maven_root = (request.protocol_version >= 2)
                .then(|| jvm_build_provider_roots(worktree).1)
                .flatten();
            let imported_build_root =
                (request.protocol_version >= 4).then(|| worktree.abs_path().as_ref().to_path_buf());
            (maven_root, imported_build_root)
        });
        let raw_projects = match jvm_project::query_jdtls_projects(
            server,
            request_timeout,
            background_executor,
            maven_root,
            imported_build_root,
        )
        .await
        {
            Ok(query) => query.projects,
            Err(error) => {
                log::warn!("Host JDTLS project query failed: {error:#}");
                return Err(anyhow!("Could not read host Java project data"));
            }
        };
        this.update(&mut cx, |store, cx| {
            store.ensure_host_jvm_snapshot_current(
                request.project_id,
                worktree_id,
                &worktree,
                server_id,
                "jdtls",
                "Java project",
                cx,
            )?;
            ensure!(
                store
                    .jdtls_projects
                    .get(&worktree_id)
                    .is_some_and(|state| state.generation() == host_generation),
                "Java project inputs changed during refresh; retry"
            );
            let worktree = worktree.read(cx);
            let snapshot = worktree.snapshot();
            let (projects, partial) = jvm_project::projects_from_provider(
                raw_projects,
                &worktree.abs_path(),
                worktree_id,
                worktree.path_style(),
                &snapshot,
                true,
            );
            let response = proto::JdtlsProjectSnapshotResponse {
                protocol_version: request.protocol_version,
                request_id: request.request_id,
                worktree_id: request.worktree_id,
                server_id: server_id.to_proto(),
                projects: projects
                    .iter()
                    .map(|project| {
                        jvm_project::project_to_proto_for_version(project, request.protocol_version)
                    })
                    .collect::<Result<Vec<_>>>()?,
                partial,
                maven_selection: None,
            };
            ensure!(
                response.encoded_len() <= response_limit,
                "Java project snapshot exceeds the remote size limit"
            );
            Ok(response)
        })
    }

    #[cfg(feature = "jvm-tools")]
    async fn handle_get_kotlin_workspace_snapshot(
        this: Entity<Self>,
        envelope: TypedEnvelope<proto::GetKotlinWorkspaceSnapshot>,
        mut cx: AsyncApp,
    ) -> Result<proto::KotlinWorkspaceSnapshotResponse> {
        const PROTOCOL_VERSION: u32 = 1;
        const MAX_RESPONSE_BYTES: usize = 1_048_576;
        let request = envelope.payload;
        ensure!(
            request.protocol_version == PROTOCOL_VERSION,
            "Kotlin workspace snapshot protocol mismatch"
        );
        let worktree_id = WorktreeId::from_proto(request.worktree_id);
        let (server_id, server, worktree, request_timeout, background_executor) =
            this.update(&mut cx, |store, cx| {
                let (server_id, server, worktree, request_timeout) = store
                    .host_jvm_snapshot_provider(
                        request.project_id,
                        worktree_id,
                        "kotlin-lsp",
                        "Kotlin project",
                        cx,
                    )?;
                Ok::<_, anyhow::Error>((
                    server_id,
                    server,
                    worktree,
                    request_timeout,
                    cx.background_executor().clone(),
                ))
            })?;
        let bytes =
            match jvm_project::query_kotlin_workspace(server, request_timeout, background_executor)
                .await
            {
                Ok(bytes) => bytes,
                Err(error) => {
                    log::warn!("Host Kotlin workspace query failed: {error:#}");
                    return Err(anyhow!("Could not read host Kotlin project data"));
                }
            };
        this.update(&mut cx, |store, cx| {
            store.ensure_host_jvm_snapshot_current(
                request.project_id,
                worktree_id,
                &worktree,
                server_id,
                "kotlin-lsp",
                "Kotlin project",
                cx,
            )?;
            let worktree = worktree.read(cx);
            let snapshot = worktree.snapshot();
            let (projects, partial) = jvm_project::projects_from_kotlin_workspace(
                &bytes,
                &worktree.abs_path(),
                worktree_id,
                worktree.path_style(),
                &snapshot,
                true,
            )?;
            let response = proto::KotlinWorkspaceSnapshotResponse {
                protocol_version: PROTOCOL_VERSION,
                request_id: request.request_id,
                worktree_id: request.worktree_id,
                server_id: server_id.to_proto(),
                projects: projects
                    .iter()
                    .map(jvm_project::kotlin_project_to_proto)
                    .collect(),
                partial,
            };
            ensure!(
                response.encoded_len() <= MAX_RESPONSE_BYTES,
                "Kotlin workspace snapshot exceeds the remote size limit"
            );
            Ok(response)
        })
    }

    #[cfg(feature = "jvm-tools")]
    pub fn prepare_reviewed_jvm_dependency_import(
        &self,
        module_root: ProjectPath,
        format: jvm_project::JvmReviewedDependencyFormat,
        cx: &App,
    ) -> Result<jvm_project::JvmReviewedDependencyImport> {
        ensure!(
            self.mode.is_local() && self.downstream_client.is_none(),
            "Reviewed JVM graphs require the local owned host; equivalent remote controls are unavailable"
        );
        ensure!(
            TrustedWorktrees::try_get_global(cx).and_then(|owner| owner
                .read(cx)
                .observed_worktree_trust(&self.worktree_store, module_root.worktree_id, cx))
                == Some(true),
            "Reviewed JVM collection requires current project trust"
        );
        ensure!(
            !self.buffer_store.read(cx).buffers().any(|buffer| {
                let buffer = buffer.read(cx);
                buffer.is_dirty()
                    && crate::File::from_dyn(buffer.file())
                        .is_some_and(|file| file.worktree_id(cx) == module_root.worktree_id)
            }),
            "Save or resolve pending JVM project edits separately before collection"
        );
        let tree = self
            .worktree_store
            .read(cx)
            .worktree_for_id(module_root.worktree_id, cx)
            .context("JVM worktree unavailable")?;
        let tree = tree.read(cx);
        ensure!(
            tree.is_visible() && tree.as_local().is_some(),
            "JVM host is not a visible local worktree"
        );
        let snapshot = tree.snapshot();
        let visible_input = |path: &RelPath| {
            let settings = crate::WorktreeSettings::get(
                Some(SettingsLocation {
                    worktree_id: module_root.worktree_id,
                    path,
                }),
                cx,
            );
            !settings.is_path_private(path) && !settings.is_path_excluded(path)
        };
        let names: &[&str] = match &format {
            jvm_project::JvmReviewedDependencyFormat::MavenSelectedTree => &["pom.xml"],
            jvm_project::JvmReviewedDependencyFormat::GradleResolution {
                project_path,
                configuration,
            } => {
                ensure!(
                    project_path.starts_with(':')
                        && project_path.len() <= 512
                        && project_path
                            .bytes()
                            .all(|byte| byte.is_ascii_alphanumeric() || b":._-".contains(&byte))
                        && !configuration.is_empty()
                        && configuration.len() <= 512
                        && configuration
                            .bytes()
                            .all(|byte| byte.is_ascii_alphanumeric() || b"._-".contains(&byte)),
                    "Choose an exact supported Gradle project and configuration"
                );
                &[
                    "build.gradle",
                    "build.gradle.kts",
                    "settings.gradle",
                    "settings.gradle.kts",
                ]
            }
        };
        ensure!(
            names.iter().any(|name| RelPath::from_unix_str(name)
                .ok()
                .and_then(|name| snapshot.entry_for_path(&module_root.path.join(name)))
                .is_some_and(crate::task_inventory::jvm_build_entry_is_available)),
            "Selected JVM build root is unavailable or not an ordinary visible input"
        );
        let mut files = Vec::new();
        let mut bytes = 0_u64;
        for entry in snapshot
            .files(false, 0)
            .filter(|entry| jvm_project::is_project_input(&entry.path))
        {
            ensure!(
                !entry.is_private
                    && visible_input(&entry.path)
                    && !entry.is_ignored
                    && !entry.is_external
                    && !entry.is_fifo
                    && entry.mtime.is_some(),
                "Relevant JVM input is private or cannot establish contained configuration"
            );
            bytes = bytes
                .checked_add(entry.size)
                .context("JVM input budget overflow")?;
            ensure!(
                files.len() < 4096 && bytes <= 2 * 1024 * 1024,
                "JVM collection input exceeds the two-MiB/4096-file limit"
            );
            files.push((entry.path.clone(), entry.inode, entry.mtime, entry.size));
        }
        let state = |jdtls: bool| {
            if jdtls {
                self.jdtls_projects
                    .get(&module_root.worktree_id)
                    .map(|state| {
                        (
                            Some(state.generation()),
                            state.snapshot().map(|snapshot| snapshot.server_id),
                            state.snapshot_is_current(),
                        )
                    })
            } else {
                self.kotlin_workspace_projects
                    .get(&module_root.worktree_id)
                    .map(|state| {
                        (
                            Some(state.generation()),
                            state.snapshot().map(|snapshot| snapshot.server_id),
                            state.snapshot_is_current(),
                        )
                    })
            }
            .unwrap_or((None, None, false))
        };
        Ok(jvm_project::JvmReviewedDependencyImport {
            owner_nonce: self.nonce,
            settings_revision: cx
                .global::<SettingsStore>()
                .observed_revision()
                .context("JVM settings unavailable")?,
            provider_generations: [state(true), state(false)],
            module_root,
            format,
            root: tree.abs_path().to_path_buf(),
            root_inode: snapshot.root_entry().context("JVM root unavailable")?.inode,
            files,
        })
    }

    #[cfg(feature = "jvm-tools")]
    pub fn revalidate_reviewed_jvm_dependency_import(
        &self,
        inputs: &jvm_project::JvmReviewedDependencyImport,
        cx: &App,
    ) -> Result<()> {
        let current = self.prepare_reviewed_jvm_dependency_import(
            inputs.module_root.clone(),
            inputs.format.clone(),
            cx,
        )?;
        ensure!(
            inputs.owner_nonce == current.owner_nonce
                && inputs.settings_revision == current.settings_revision
                && inputs.provider_generations == current.provider_generations
                && inputs.root == current.root
                && inputs.root_inode == current.root_inode
                && inputs.files == current.files,
            "Reviewed JVM owner, import generation, settings or sources changed"
        );
        Ok(())
    }

    #[cfg(feature = "jvm-tools")]
    pub fn reviewed_jvm_dependency_snapshot(
        &self,
        root: &ProjectPath,
        format: &jvm_project::JvmReviewedDependencyFormat,
        cx: &App,
    ) -> Option<&jvm_project::JvmDependencyGraph> {
        let key = (root.clone(), format!("{format:?}"));
        let snapshot = self.reviewed_jvm_dependencies.get(&key)?;
        self.revalidate_reviewed_jvm_dependency_import(&snapshot.inputs, cx)
            .ok()?;
        Some(&snapshot.graph)
    }

    #[cfg(feature = "jvm-tools")]
    pub fn admit_reviewed_jvm_dependency_import(
        &mut self,
        inputs: jvm_project::JvmReviewedDependencyImport,
        bytes: Vec<u8>,
        cx: &mut Context<Self>,
    ) -> Task<Result<jvm_project::JvmDependencyGraph>> {
        let prepared = self
            .revalidate_reviewed_jvm_dependency_import(&inputs, cx)
            .and_then(|()| {
                ensure!(
                    bytes.len() <= jvm_project::MAX_JVM_DEPENDENCY_REPORT_BYTES,
                    "JVM report exceeds the eight-MiB limit"
                );
                self.worktree_store
                    .read(cx)
                    .fs()
                    .context("Confined JVM filesystem unavailable")
            });
        let filesystem = match prepared {
            Ok(filesystem) => filesystem,
            Err(error) => return Task::ready(Err(error)),
        };
        let pending = cx.background_spawn({
            let inputs = inputs.clone();
            async move { inputs.interpret(&bytes, filesystem.as_ref()).await }
        });
        cx.spawn(async move |this, cx| {
            let graph = pending.await?;
            this.update(cx, |this, cx| {
                this.revalidate_reviewed_jvm_dependency_import(&inputs, cx)?;
                let key = (inputs.module_root.clone(), format!("{:?}", inputs.format));
                let new_retained_bytes = graph
                    .retained_field_bytes()?
                    .checked_add(inputs.retained_input_bytes()?)
                    .context("JVM input and graph budget overflow")?;
                let mut retained_bytes = new_retained_bytes;
                let mut retained_nodes = graph.nodes.len();
                let mut retained_edges = graph.edges.len();
                let mut retained_roots = 1_usize;
                for (other_key, snapshot) in &this.reviewed_jvm_dependencies {
                    if other_key == &key {
                        continue;
                    }
                    retained_roots = retained_roots
                        .checked_add(1)
                        .context("JVM cache root budget overflow")?;
                    retained_bytes = retained_bytes
                        .checked_add(snapshot.retained_bytes)
                        .context("JVM cache budget overflow")?;
                    retained_nodes = retained_nodes
                        .checked_add(snapshot.graph.nodes.len())
                        .context("JVM node budget overflow")?;
                    retained_edges = retained_edges
                        .checked_add(snapshot.graph.edges.len())
                        .context("JVM edge budget overflow")?;
                }
                ensure!(
                    retained_roots <= 128
                        && retained_bytes <= jvm_project::MAX_JVM_DEPENDENCY_REPORT_BYTES
                        && retained_nodes <= jvm_project::MAX_JVM_DEPENDENCY_NODES
                        && retained_edges <= jvm_project::MAX_JVM_DEPENDENCY_EDGES,
                    "Reviewed JVM aggregate cache limit exceeded; previous evidence preserved"
                );
                this.reviewed_jvm_dependencies.insert(
                    key,
                    ReviewedJvmDependencySnapshot {
                        inputs,
                        retained_bytes: new_retained_bytes,
                        graph: graph.clone(),
                    },
                );
                cx.notify();
                Ok(graph)
            })?
        })
    }

    #[cfg(feature = "jvm-tools")]
    pub fn jdtls_project_snapshot(
        &self,
        worktree_id: WorktreeId,
    ) -> Option<(&JdtlsProjectSnapshot, bool)> {
        let state = self.jdtls_projects.get(&worktree_id)?;
        let snapshot = state.snapshot()?;
        (snapshot.worktree_id == worktree_id
            && self.provider_project_server_is_live(
                snapshot.server_id,
                worktree_id,
                LanguageServerName::new_static("jdtls"),
            ))
        .then_some((snapshot, state.snapshot_is_current()))
    }

    #[cfg(feature = "jvm-tools")]
    fn provider_project_server_is_live(
        &self,
        server_id: LanguageServerId,
        worktree_id: WorktreeId,
        provider: LanguageServerName,
    ) -> bool {
        self.language_server_statuses
            .get(&server_id)
            .is_some_and(|status| status.name == provider && status.worktree == Some(worktree_id))
            && (self.language_server_for_id(server_id).is_some()
                || self.upstream_client().is_some())
    }

