    #[cfg(feature = "jvm-tools")]
    pub fn refresh_kotlin_workspace(&mut self, worktree_id: WorktreeId, cx: &mut Context<Self>) {
        let server_id = self
            .language_server_statuses
            .iter()
            .find(|(_, status)| {
                status.name == LanguageServerName::new_static("kotlin-lsp")
                    && status.worktree == Some(worktree_id)
            })
            .map(|(server_id, _)| *server_id);
        if let Some(server_id) = server_id {
            if self.as_remote().is_some() {
                self.schedule_remote_kotlin_workspace_refresh(server_id, worktree_id, cx);
            } else {
                self.schedule_kotlin_workspace_refresh(server_id, worktree_id, cx);
            }
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn on_kotlin_workspace_import_event(
        &mut self,
        server_id: LanguageServerId,
        event: kotlin_lsp_ext::KotlinImportEvent,
        cx: &mut Context<Self>,
    ) {
        let worktree_ids = self
            .as_local()
            .into_iter()
            .flat_map(|local| local.language_server_ids.iter())
            .filter(|(seed, server)| {
                seed.name == LanguageServerName::new_static("kotlin-lsp") && server.id == server_id
            })
            .map(|(seed, _)| seed.worktree_id)
            .collect::<Vec<_>>();
        for worktree_id in worktree_ids {
            let state = self
                .kotlin_workspace_projects
                .entry(worktree_id)
                .or_default();
            let update = match event {
                kotlin_lsp_ext::KotlinImportEvent::Finished { successful: false } => {
                    state.mark_import_failed(server_id)
                }
                kotlin_lsp_ext::KotlinImportEvent::Finished { successful: true } => {
                    state.mark_import_succeeded(server_id)
                }
                kotlin_lsp_ext::KotlinImportEvent::Started => state.mark_stale(),
            };
            if let Err(error) = update {
                log::warn!("Could not invalidate Kotlin workspace import: {error:#}");
                continue;
            }
            self.kotlin_workspace_refresh_tasks.remove(&worktree_id);
            cx.notify();
            if matches!(
                event,
                kotlin_lsp_ext::KotlinImportEvent::Finished { successful: true }
            ) {
                self.schedule_kotlin_workspace_refresh(server_id, worktree_id, cx);
            }
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn schedule_remote_kotlin_workspace_refresh(
        &mut self,
        server_id: LanguageServerId,
        worktree_id: WorktreeId,
        cx: &mut Context<Self>,
    ) {
        let Some((client, project_id)) = self.upstream_client() else {
            return;
        };
        let Some(worktree) = self
            .worktree_store
            .read(cx)
            .worktree_for_id(worktree_id, cx)
        else {
            return;
        };
        if !worktree.read(cx).is_visible()
            || TrustedWorktrees::try_get_global(cx).is_none_or(|trusted| {
                !trusted.update(cx, |trusted, cx| {
                    trusted.can_trust(&self.worktree_store, worktree_id, cx)
                })
            })
        {
            return;
        }
        let Ok(token) = self
            .kotlin_workspace_projects
            .entry(worktree_id)
            .or_default()
            .begin(server_id, worktree_id)
        else {
            log::warn!("Remote Kotlin workspace generation exhausted");
            return;
        };
        cx.notify();
        let refresh = cx.spawn(async move |this, cx| {
            let result = client
                .request(proto::GetKotlinWorkspaceSnapshot {
                    project_id,
                    worktree_id: worktree_id.to_proto(),
                    protocol_version: 1,
                    request_id: token.generation(),
                })
                .await;
            if let Err(error) = this.update(cx, |store, cx| {
                let server_is_current =
                    store
                        .language_server_statuses
                        .get(&server_id)
                        .is_some_and(|status| {
                            status.name == LanguageServerName::new_static("kotlin-lsp")
                                && status.worktree == Some(worktree_id)
                        })
                        && store.upstream_client().is_some();
                let worktree = store
                    .worktree_store
                    .read(cx)
                    .worktree_for_id(worktree_id, cx);
                let is_trusted = TrustedWorktrees::try_get_global(cx).is_some_and(|trusted| {
                    trusted.update(cx, |trusted, cx| {
                        trusted.can_trust(&store.worktree_store, worktree_id, cx)
                    })
                });
                if !server_is_current
                    || !is_trusted
                    || !worktree
                        .as_ref()
                        .is_some_and(|worktree| worktree.read(cx).is_visible())
                {
                    if let Some(state) = store.kotlin_workspace_projects.get_mut(&worktree_id) {
                        state.invalidate_server(server_id);
                    }
                    cx.notify();
                    return;
                }
                let Some(worktree) = worktree else {
                    return;
                };
                let Some(state) = store.kotlin_workspace_projects.get_mut(&worktree_id) else {
                    return;
                };
                let parsed = result.and_then(|response| {
                    ensure!(
                        response.protocol_version == 1
                            && response.request_id == token.generation()
                            && response.worktree_id == worktree_id.to_proto()
                            && response.server_id == server_id.to_proto(),
                        "Remote Kotlin workspace snapshot protocol mismatch"
                    );
                    ensure!(
                        response.encoded_len() <= 1_048_576,
                        "Remote Kotlin workspace snapshot exceeds the size limit"
                    );
                    let snapshot = worktree.read(cx).snapshot();
                    let projects = jvm_project::kotlin_projects_from_proto(
                        response.projects,
                        worktree_id,
                        &snapshot,
                    )?;
                    Ok((projects, response.partial))
                });
                match parsed {
                    Ok((projects, partial)) => {
                        if state.finish(token, projects, partial) {
                            cx.notify();
                        }
                    }
                    Err(error) => {
                        log::warn!("Could not refresh remote Kotlin workspace: {error:#}");
                        if state.fail(token) {
                            cx.notify();
                        }
                    }
                }
            }) {
                log::debug!("Remote Kotlin reply arrived after project teardown: {error:#}");
            }
        });
        self.kotlin_workspace_refresh_tasks
            .insert(worktree_id, refresh);
    }

    #[cfg(feature = "jvm-tools")]
    fn schedule_kotlin_workspace_refresh(
        &mut self,
        server_id: LanguageServerId,
        worktree_id: WorktreeId,
        cx: &mut Context<Self>,
    ) {
        let Some(server) = self.language_server_for_id(server_id) else {
            return;
        };
        let Some(worktree) = self
            .worktree_store
            .read(cx)
            .worktree_for_id(worktree_id, cx)
        else {
            return;
        };
        if !worktree.read(cx).is_local()
            || !worktree.read(cx).is_visible()
            || TrustedWorktrees::try_get_global(cx).is_none_or(|trusted| {
                !trusted.update(cx, |trusted, cx| {
                    trusted.can_trust(&self.worktree_store, worktree_id, cx)
                })
            })
        {
            return;
        }
        let Ok(token) = self
            .kotlin_workspace_projects
            .entry(worktree_id)
            .or_default()
            .begin(server_id, worktree_id)
        else {
            log::warn!("Kotlin workspace generation exhausted");
            return;
        };
        cx.notify();
        let request_timeout = ProjectSettings::get_global(cx)
            .global_lsp_settings
            .get_request_timeout();
        let background_executor = cx.background_executor().clone();
        let refresh = cx.spawn(async move |this, cx| {
            let result =
                jvm_project::query_kotlin_workspace(server, request_timeout, background_executor)
                    .await;
            if let Err(error) = this.update(cx, |store, cx| {
                let server_is_current = store.provider_project_server_is_live(
                    server_id,
                    worktree_id,
                    LanguageServerName::new_static("kotlin-lsp"),
                );
                let worktree = store
                    .worktree_store
                    .read(cx)
                    .worktree_for_id(worktree_id, cx);
                let is_trusted = TrustedWorktrees::try_get_global(cx).is_some_and(|trusted| {
                    trusted.update(cx, |trusted, cx| {
                        trusted.can_trust(&store.worktree_store, worktree_id, cx)
                    })
                });
                if !server_is_current
                    || !is_trusted
                    || !worktree
                        .as_ref()
                        .is_some_and(|worktree| worktree.read(cx).is_visible())
                {
                    if let Some(state) = store.kotlin_workspace_projects.get_mut(&worktree_id) {
                        state.invalidate_server(server_id);
                    }
                    cx.notify();
                    return;
                }
                let Some(worktree) = worktree else {
                    return;
                };
                let Some(state) = store.kotlin_workspace_projects.get_mut(&worktree_id) else {
                    return;
                };
                let parsed = result.and_then(|bytes| {
                    let worktree = worktree.read(cx);
                    jvm_project::projects_from_kotlin_workspace(
                        &bytes,
                        &worktree.abs_path(),
                        worktree_id,
                        worktree.path_style(),
                        &worktree.snapshot(),
                        false,
                    )
                });
                match parsed {
                    Ok((projects, partial)) => {
                        if state.finish(token, projects, partial) {
                            cx.notify();
                        }
                    }
                    Err(error) => {
                        log::warn!("Could not refresh Kotlin workspace data: {error:#}");
                        if state.fail(token) {
                            cx.notify();
                        }
                    }
                }
            }) {
                log::debug!("Kotlin workspace reply arrived after project teardown: {error:#}");
            }
        });
        self.kotlin_workspace_refresh_tasks
            .insert(worktree_id, refresh);
    }

    #[cfg(feature = "jvm-tools")]
    pub fn invalidate_remote_jvm_projects(&mut self, cx: &mut Context<Self>) {
        if self.as_remote().is_none() {
            return;
        }
        self.jdtls_refresh_tasks.clear();
        for (worktree_id, state) in &mut self.jdtls_projects {
            if let Err(error) = state.invalidate_remote_connection(*worktree_id) {
                log::error!("Could not advance JDTLS generation after disconnect: {error:#}");
            }
        }
        self.kotlin_workspace_refresh_tasks.clear();
        for (worktree_id, state) in &mut self.kotlin_workspace_projects {
            if let Err(error) = state.invalidate_remote_connection(*worktree_id) {
                log::error!("Could not advance Kotlin generation after disconnect: {error:#}");
            }
        }
        cx.notify();
    }

    #[cfg(feature = "jvm-tools")]
    pub fn refresh_jdtls_project(&mut self, worktree_id: WorktreeId, cx: &mut Context<Self>) {
        if self
            .jdtls_projects
            .get(&worktree_id)
            .is_some_and(|state| state.import_operation().is_some())
        {
            return;
        }
        let server_id = self
            .language_server_statuses
            .iter()
            .find(|(_, status)| {
                status.name == LanguageServerName::new_static("jdtls")
                    && status.worktree == Some(worktree_id)
            })
            .map(|(server_id, _)| *server_id);
        if let Some(server_id) = server_id {
            if self.as_local().is_some() {
                self.schedule_local_jdtls_project_refresh(
                    server_id,
                    worktree_id,
                    None,
                    true,
                    None,
                    cx,
                )
                .log_err();
            } else {
                if let Some(state) = self.jdtls_projects.get_mut(&worktree_id) {
                    if let Err(error) = state.mark_stale() {
                        log::error!("Could not advance Java project refresh generation: {error:#}");
                        return;
                    }
                }
                self.schedule_jdtls_project_refresh(server_id, worktree_id, cx);
            }
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn selected_jdtls_phase_provider(
        &self,
        worktree_id: WorktreeId,
        target: &SelectedJdtlsPhaseTarget,
        phase: Option<jvm_project::ProviderRefreshToken>,
        cx: &mut Context<Self>,
    ) -> Result<(
        LanguageServerId,
        Arc<LanguageServer>,
        Entity<Worktree>,
        PreparedJdtlsPhase,
    )> {
        let name = target.name();
        let operation = target.operation();
        ensure!(
            self.as_local().is_some(),
            "Selected {name} {operation} requires its local project host; remote import is not available yet"
        );
        let worktree = self
            .worktree_store
            .read(cx)
            .worktree_for_id(worktree_id, cx)
            .with_context(|| format!("{name} project folder is unavailable; reopen it"))?;
        ensure!(
            worktree.read(cx).is_local() && worktree.read(cx).is_visible(),
            "{name} project folder is unavailable; reopen it"
        );
        ensure!(
            TrustedWorktrees::try_get_global(cx).is_some_and(|trusted| {
                trusted.update(cx, |trusted, cx| {
                    trusted.can_trust(&self.worktree_store, worktree_id, cx)
                })
            }),
            "Selected {name} {operation} requires project trust; review and trust this folder first"
        );
        let server_id = self
            .language_server_statuses
            .iter()
            .find(|(_, status)| {
                status.name == LanguageServerName::new_static("jdtls")
                    && status.worktree == Some(worktree_id)
            })
            .map(|(server_id, _)| *server_id)
            .context(
                "Java language server is unavailable; open Java source and check extension setup",
            )?;
        let server = self
            .language_server_for_id(server_id)
            .context("Java language server is unavailable; check extension setup")?;
        let mut selection = match target {
            SelectedJdtlsPhaseTarget::Maven(poms) => {
                let worktree = worktree.read(cx);
                ensure!(
                    !poms.is_empty() && poms.len() <= 32,
                    "Select between one and 32 Maven POM files before importing"
                );
                let snapshot = worktree.snapshot();
                let mut paths = Vec::with_capacity(poms.len());
                for pom in poms {
                    ensure!(
                        pom.worktree_id == worktree_id
                            && snapshot.entry_for_path(&pom.path).is_some_and(|entry| entry
                                .is_file()
                                && !entry.is_private
                                && !entry.is_external
                                && !entry.is_fifo)
                            && !pom.path.ancestors().any(|ancestor| snapshot
                                .entry_for_path(ancestor)
                                .is_some_and(|entry| entry.is_private
                                    || entry.is_external
                                    || entry.is_fifo)),
                        "Selected Maven POM is missing, private or outside this project; select visible project files again"
                    );
                    paths.push(worktree.abs_path().join(pom.path.as_unix_str()));
                }
                PreparedJdtlsPhase::Maven(jvm_project::SelectedMavenImport::new(
                    worktree.abs_path().as_ref(),
                    &paths,
                )?)
            }
            SelectedJdtlsPhaseTarget::MavenGraph(pom) => {
                let worktree = worktree.read(cx);
                let entries = worktree.snapshot();
                ensure!(
                    project_input_is_visible(&entries, pom, worktree_id, false),
                    "Maven graph POM is missing, private or outside this project; select a visible imported POM and refresh"
                );
                let (snapshot, current) = self.jdtls_project_snapshot(worktree_id)
                    .context("Current imported Maven metadata is unavailable; refresh before collecting dependencies")?;
                ensure!(
                    current
                        || phase.is_some_and(|token| self
                            .jdtls_projects
                            .get(&worktree_id)
                            .is_some_and(|state| state.pending_query() == Some(token))),
                    "Maven graph metadata is stale or another query is active; refresh before retrying"
                );
                ensure!(
                    self.jdtls_ownership_covers_snapshot(
                        snapshot,
                        worktree.abs_path().as_ref(),
                        &entries
                    ),
                    "Complete current Java imported ownership is unavailable; refresh before collecting dependencies"
                );
                let mut projects = snapshot.projects.iter().filter(|project| {
                    project
                        .maven
                        .as_ref()
                        .is_some_and(|maven| maven.pom == *pom)
                });
                let project = projects.next().context("Selected POM has no current Maven metadata; import and refresh before retrying")?;
                ensure!(
                    projects.next().is_none()
                        && project.membership.is_imported()
                        && project.imported_build_kind
                            == jvm_project::JdtlsImportedBuildKind::Maven,
                    "Selected Maven graph identity is ambiguous or not imported; refresh before retrying"
                );
                PreparedJdtlsPhase::MavenGraph(jvm_project::SelectedMavenDependencyGraph::new(
                    worktree.abs_path().as_ref(),
                    &worktree.abs_path().join(pom.path.as_unix_str()),
                )?)
            }
            SelectedJdtlsPhaseTarget::MavenReactor {
                pom,
                excluded_projects,
                pom_masks,
            } => {
                let worktree = worktree.read(cx);
                let entries = worktree.snapshot();
                ensure!(
                    project_input_is_visible(&entries, pom, worktree_id, false)
                        && excluded_projects.len() <= 128
                        && excluded_projects.iter().all(|path| {
                            project_input_is_visible(&entries, path, worktree_id, true)
                        }),
                    "Selected Maven reactor POM or excluded directory is missing, private or outside this project; review selection and retry"
                );
                let root = worktree.abs_path();
                let pom = root.join(pom.path.as_unix_str());
                let excluded_directories = excluded_projects
                    .iter()
                    .map(|path| root.join(path.path.as_unix_str()))
                    .collect::<Vec<_>>();
                let selection = if let Some(patterns) = pom_masks {
                    jvm_project::MavenReactorImport::new_with_masks(
                        root.as_ref(),
                        &pom,
                        &excluded_directories,
                        Some(patterns),
                    )?
                } else {
                    jvm_project::MavenReactorImport::new(
                        root.as_ref(),
                        &pom,
                        &excluded_directories,
                    )?
                };
                PreparedJdtlsPhase::MavenReactor(selection)
            }
            SelectedJdtlsPhaseTarget::SavedMaven(intent) => {
                let pom_masks = intent.ignored_pom_patterns.clone();
                ensure!(
                    &self.effective_saved_maven_selection(worktree_id, cx)? == intent,
                    "Saved Maven selection changed during application; import may be partial, review settings and refresh before retrying"
                );
                let content = settings::JvmBuildSettingsContent {
                    maven: Some(intent.clone()),
                    gradle: None,
                };
                let settings = jvm_project::JvmBuildSelectionIntent::from_settings(Some(&content))?;
                let intent = settings
                    .maven
                    .as_ref()
                    .context("Saved Maven selection is unavailable; review settings")?;
                let snapshot = self.jdtls_project_snapshot(worktree_id);
                if !intent.ignored_projects.is_empty() {
                    ensure!(
                        snapshot.is_some_and(|(snapshot, current)| {
                            self.jdtls_ownership_covers_snapshot(
                                snapshot,
                                worktree.read(cx).abs_path().as_ref(),
                                &worktree.read(cx).snapshot(),
                            ) && (current
                                || phase.is_some_and(|token| {
                                    token.server_id() == snapshot.server_id
                                        && token.worktree_id() == worktree_id
                                        && self.jdtls_projects.get(&worktree_id).is_some_and(
                                            |state| state.import_operation() == Some(token),
                                        )
                                }))
                        }),
                        "Current complete Maven ownership is unavailable; refresh before applying ignored projects"
                    );
                }
                let entries = worktree.read(cx).snapshot();
                let default_inputs = (intent.selected_poms.is_none()
                    && (!intent.ignored_projects.is_empty()
                        || !intent.ignored_pom_patterns.is_empty()))
                .then(|| jvm_project::default_maven_import_inputs(&entries, worktree_id))
                .transpose()?;
                let projects = snapshot
                    .map(|(snapshot, _)| snapshot.projects.as_slice())
                    .unwrap_or_default();
                let plan = if default_inputs.is_some() {
                    jvm_project::SavedMavenSelection::with_default_snapshot(
                        intent,
                        worktree_id,
                        projects,
                        Some(&entries),
                    )?
                } else {
                    jvm_project::SavedMavenSelection::new(intent, worktree_id, projects)?
                };
                let mut targets = Vec::new();
                if let Some(plan) = plan {
                    ensure!(
                        plan.ignored_projects.iter().all(|path| {
                            project_input_is_visible(
                                &worktree.read(cx).snapshot(),
                                path,
                                worktree_id,
                                true,
                            )
                        }),
                        "Saved Maven ignored directory is missing, private or outside this project; review settings and retry"
                    );
                    if !plan.unlink_projects.is_empty() {
                        targets.push(SelectedJdtlsPhaseTarget::Unlink {
                            provider: jvm_project::JdtlsUnlinkProvider::Maven,
                            modules: plan.unlink_projects,
                        });
                    }
                    targets.extend(plan.selected_poms.into_iter().map(|pom| {
                        SelectedJdtlsPhaseTarget::MavenReactor {
                            pom,
                            excluded_projects: plan.ignored_projects.clone(),
                            pom_masks: pom_masks.clone(),
                        }
                    }));
                }
                let mut prepared = Vec::with_capacity(targets.len());
                for target in targets {
                    prepared.push(
                        self.selected_jdtls_phase_provider(worktree_id, &target, phase, cx)?
                            .3,
                    );
                }
                PreparedJdtlsPhase::SavedMaven {
                    phases: prepared,
                    default_inputs,
                }
            }
            SelectedJdtlsPhaseTarget::GradleGraph {
                module,
                configuration,
            } => {
                let worktree = worktree.read(cx);
                let entries = worktree.snapshot();
                ensure!(
                    project_input_is_visible(&entries, module, worktree_id, true),
                    "Gradle graph module is missing, private or outside this project; select a visible imported module and refresh"
                );
                let (snapshot, current) = self.jdtls_project_snapshot(worktree_id).context("Current imported Gradle metadata is unavailable; refresh before collecting dependencies")?;
                ensure!(
                    current
                        || phase.is_some_and(|token| self
                            .jdtls_projects
                            .get(&worktree_id)
                            .is_some_and(|state| state.pending_query() == Some(token))),
                    "Gradle graph metadata is stale or another query is active; refresh before retrying"
                );
                ensure!(
                    self.jdtls_ownership_covers_snapshot(
                        snapshot,
                        worktree.abs_path().as_ref(),
                        &entries
                    ),
                    "Complete current Java imported ownership is unavailable; refresh before collecting dependencies"
                );
                let mut projects = snapshot
                    .projects
                    .iter()
                    .filter(|project| project.module_root == *module && project.gradle.is_some());
                let project = projects.next().context("Selected module has no current Gradle metadata; import and refresh before retrying")?;
                ensure!(
                    projects.next().is_none()
                        && project.membership.is_imported()
                        && project.imported_build_kind
                            == jvm_project::JdtlsImportedBuildKind::Gradle,
                    "Selected Gradle graph identity is ambiguous or not imported; refresh before retrying"
                );
                let gradle = project
                    .gradle
                    .as_ref()
                    .context("Current Gradle metadata is unavailable; refresh before retrying")?;
                ensure!(
                    project_input_is_visible(&entries, &gradle.build_root, worktree_id, true),
                    "Gradle graph build root is missing or private; refresh before retrying"
                );
                let mut configurations = gradle
                    .configurations
                    .iter()
                    .filter(|candidate| candidate.name == *configuration);
                ensure!(
                    gradle.configurations_known
                        && configurations
                            .next()
                            .is_some_and(|candidate| candidate.resolvable)
                        && configurations.next().is_none(),
                    "Selected Gradle configuration is unknown, ambiguous or not resolvable; refresh and select a resolvable configuration"
                );
                let mut input_present = false;
                for name in [
                    "settings.gradle",
                    "settings.gradle.kts",
                    "build.gradle",
                    "build.gradle.kts",
                ] {
                    let input = ProjectPath {
                        worktree_id,
                        path: gradle
                            .build_root
                            .path
                            .join(RelPath::from_unix_str(name)?)
                            .into(),
                    };
                    if entries.entry_for_path(&input.path).is_some() {
                        ensure!(
                            project_input_is_visible(&entries, &input, worktree_id, false),
                            "Gradle graph build input is missing, private or outside this project; review settings and refresh"
                        );
                        input_present = true;
                    }
                }
                ensure!(
                    input_present,
                    "Gradle graph build input is unavailable; refresh before retrying"
                );
                PreparedJdtlsPhase::GradleGraph(jvm_project::SelectedGradleDependencyGraph::new(
                    worktree.abs_path().as_ref(),
                    &worktree.abs_path().join(module.path.as_unix_str()),
                    configuration,
                )?)
            }
            SelectedJdtlsPhaseTarget::GradleModules(intent) => {
                let mut ignored = Vec::new();
                let mut ignored_root = false;
                let mut default_roots = None;
                ensure!(
                    &self.effective_saved_gradle_selection(worktree_id, cx)? == intent,
                    "Saved Gradle settings changed during import; refresh and retry with the current build selection"
                );
                let default_settings = settings::GradleBuildSettingsContent::default();
                let settings = intent.as_ref().unwrap_or(&default_settings);
                let scoped = if settings.selected_build_files.is_none()
                    && jvm_project::ScopedGradleImports::supports_default_policy(&server)
                {
                    Some(jvm_project::ScopedGradleImports::for_default(
                        &worktree.read(cx).snapshot(),
                        worktree_id,
                        settings,
                    )?)
                } else {
                    intent
                        .as_ref()
                        .map(|intent| {
                            jvm_project::ScopedGradleImports::for_selection(
                                &worktree.read(cx).snapshot(),
                                worktree_id,
                                intent,
                            )
                        })
                        .transpose()?
                        .flatten()
                };
                if let Some(scoped) = scoped {
                    PreparedJdtlsPhase::GradleScoped(Box::new(scoped))
                } else {
                    if let Some(intent) = intent {
                        if intent.selected_build_files.is_none()
                            && intent
                                .ignored_projects
                                .as_ref()
                                .is_some_and(|paths| !paths.is_empty())
                        {
                            default_roots =
                                Some(Box::new(jvm_project::GradleDefaultImportRootsQuery::new(
                                    &worktree.read(cx).snapshot(),
                                    worktree_id,
                                )?));
                            for directory in intent.ignored_projects.iter().flatten() {
                                let path = RelPath::from_unix_str(directory)?;
                                if path.is_empty() {
                                    ignored_root = true;
                                } else {
                                    ignored.push(
                                        worktree.read(cx).abs_path().join(path.as_unix_str()),
                                    );
                                }
                            }
                        } else {
                            let selection = jvm_project::SavedGradleSelection::new(
                                &jvm_project::GradleSelectionIntent {
                                    selected_build_files: intent.selected_build_files.as_deref(),
                                    ignored_projects: intent
                                        .ignored_projects
                                        .as_deref()
                                        .unwrap_or_default(),
                                },
                                worktree_id,
                                &[],
                            )?;
                            if let Some(selection) = selection {
                                ignored_root = selection
                                    .ignored_projects
                                    .iter()
                                    .any(|path| path.path.is_empty());
                                ignored = selection
                                    .ignored_projects
                                    .iter()
                                    .filter(|path| !path.path.is_empty())
                                    .map(|path| {
                                        worktree.read(cx).abs_path().join(path.path.as_unix_str())
                                    })
                                    .collect();
                                ensure!(
                                    if ignored_root {
                                        intent.selected_build_files.as_ref().is_some_and(|files| {
                                            !files.is_empty()
                                                && files.iter().all(|file| {
                                                    RelPath::from_unix_str(file).ok().is_some_and(
                                                        |file| {
                                                            file.parent().is_some_and(|parent| {
                                                                parent.is_empty()
                                                            })
                                                        },
                                                    )
                                                })
                                        })
                                    } else {
                                        selection.selected_roots.len() == 1
                                            && selection.selected_roots.first().is_some_and(
                                                |root| {
                                                    root.worktree_id == worktree_id
                                                        && root.path.is_empty()
                                                },
                                            )
                                    },
                                    "Saved Gradle selection does not select only this build root; keep the settings and wait for nested-root import support, or select this root and refresh before explicitly importing"
                                );
                                let entries = worktree.read(cx).snapshot();
                                for build_file in intent.selected_build_files.iter().flatten() {
                                    let build_file = ProjectPath {
                                        worktree_id,
                                        path: RelPath::from_unix_str(build_file)?.into(),
                                    };
                                    ensure!(
                                        project_input_is_visible(
                                            &entries,
                                            &build_file,
                                            worktree_id,
                                            false,
                                        ),
                                        "Saved Gradle build input is unavailable or restricted; review selected build files and refresh before importing"
                                    );
                                }
                            }
                        }
                    }
                    let worktree = worktree.read(cx);
                    let mut input_present = false;
                    for name in [
                        "settings.gradle",
                        "settings.gradle.kts",
                        "build.gradle",
                        "build.gradle.kts",
                    ] {
                        let path = RelPath::from_unix_str(name)?;
                        if let Some(entry) = worktree.entry_for_path(path) {
                            ensure!(
                                entry.is_file()
                                    && !entry.is_private
                                    && !entry.is_external
                                    && !entry.is_fifo,
                                "Selected Gradle build input must be a visible regular file inside this project; review build files and retry"
                            );
                            input_present = true;
                        }
                    }
                    ensure!(
                        input_present,
                        "No visible Gradle build exists in this project folder; open its build root"
                    );
                    let import =
                        jvm_project::SelectedGradleImport::new(worktree.abs_path().as_ref())?;
                    PreparedJdtlsPhase::GradleModules {
                        default_roots,
                        root_query: jvm_project::GradleRootStateQuery::new(
                            worktree.abs_path().as_ref(),
                        )?,
                        ignored_root,
                        query: jvm_project::GradleModuleStateQuery::new(
                            worktree.abs_path().as_ref(),
                        )?,
                        ignored,
                        import,
                    }
                }
            }
            SelectedJdtlsPhaseTarget::Unlink { provider, modules } => {
                ensure!(
                    !modules.is_empty() && modules.len() <= 128,
                    "Select between one and 128 current imported {name} projects before unlinking"
                );
                let (snapshot, current) = self.jdtls_project_snapshot(worktree_id)
                    .with_context(|| format!("Current {name} project identities are unavailable; refresh before unlinking"))?;
                let owns_phase = phase.is_some_and(|token| {
                    token.server_id() == snapshot.server_id
                        && token.worktree_id() == worktree_id
                        && self
                            .jdtls_projects
                            .get(&worktree_id)
                            .is_some_and(|state| state.import_operation() == Some(token))
                });
                ensure!(
                    current || owns_phase,
                    "{name} project identities are stale; refresh before unlinking"
                );
                let worktree = worktree.read(cx);
                let entries = worktree.snapshot();
                let mut paths = Vec::with_capacity(modules.len());
                for module in modules {
                    let imported = snapshot
                        .projects
                        .iter()
                        .find(|project| project.module_root == *module);
                    ensure!(
                        module.worktree_id == worktree_id
                            && imported.is_some_and(|project| project.membership.is_imported())
                            && entries
                                .entry_for_path(&module.path)
                                .is_some_and(|entry| entry.is_dir()
                                    && !entry.is_private
                                    && !entry.is_external
                                    && !entry.is_fifo)
                            && !module.path.ancestors().any(|ancestor| entries
                                .entry_for_path(ancestor)
                                .is_some_and(|entry| entry.is_private
                                    || entry.is_external
                                    || entry.is_fifo)),
                        "Selected {name} project is missing, private or no longer imported; refresh and select current projects again"
                    );
                    let expected_kind = match provider {
                        jvm_project::JdtlsUnlinkProvider::Maven => {
                            jvm_project::JdtlsImportedBuildKind::Maven
                        }
                        jvm_project::JdtlsUnlinkProvider::Gradle => {
                            jvm_project::JdtlsImportedBuildKind::Gradle
                        }
                    };
                    ensure!(
                        imported
                            .is_some_and(|project| project.imported_build_kind == expected_kind),
                        "Selected {name} unlink provider ownership is unavailable or different; check provider setup and refresh before retrying"
                    );
                    paths.push(worktree.abs_path().join(module.path.as_unix_str()));
                }
                PreparedJdtlsPhase::Unlink(jvm_project::SelectedProjectUnlink::new(
                    *provider,
                    worktree.abs_path().as_ref(),
                    &paths,
                )?)
            }
        };
        ensure!(
            selection.default_maven_inputs().is_none()
                || server
                    .capabilities()
                    .execute_command_provider
                    .as_ref()
                    .is_some_and(|provider| provider
                        .commands
                        .iter()
                        .any(|command| { command == "groovy.maven.defaultImportRoots" })),
            "Maven default-root discovery provider is unavailable; check extension setup or select explicit POM roots and refresh before retrying"
        );
        ensure!(
            !matches!(
                &selection,
                PreparedJdtlsPhase::GradleModules {
                    default_roots: Some(_),
                    ..
                }
            ) || server
                .capabilities()
                .execute_command_provider
                .as_ref()
                .is_some_and(|provider| {
                    provider
                        .commands
                        .iter()
                        .any(|command| command == "groovy.gradle.defaultImportRoots")
                }),
            "Gradle default-root discovery provider is unavailable; check extension setup or select explicit build files and refresh before retrying"
        );
        ensure!(
            matches!(target, SelectedJdtlsPhaseTarget::SavedMaven(_))
                || matches!(&selection, PreparedJdtlsPhase::GradleScoped(_))
                || server
                    .capabilities()
                    .execute_command_provider
                    .as_ref()
                    .is_some_and(|provider| {
                        provider
                            .commands
                            .iter()
                            .any(|command| command == target.command())
                    }),
            "Selected {name} {operation} provider is unavailable; check extension setup and retry"
        );
        if matches!(&selection, PreparedJdtlsPhase::GradleModules { .. }) {
            ensure!(
                server
                    .capabilities()
                    .execute_command_provider
                    .as_ref()
                    .is_some_and(|provider| [
                        "groovy.gradle.rootState",
                        "groovy.gradle.applyRootState",
                        "groovy.gradle.moduleStates",
                        "groovy.gradle.applyModuleStates",
                        "groovy.gradle.importSelected"
                    ]
                    .iter()
                    .all(|command| provider
                        .commands
                        .iter()
                        .any(|advertised| advertised.as_str() == *command))),
                "Gradle module policy provider is unavailable; check extension setup and refresh before retrying"
            );
        }
        if let PreparedJdtlsPhase::GradleScoped(plan) = &mut selection {
            ensure!(
                server
                    .capabilities()
                    .execute_command_provider
                    .as_ref()
                    .is_some_and(|provider| {
                        plan.required_commands().iter().all(|required| {
                            provider.commands.iter().any(|command| command == required)
                        })
                    }),
                "Scoped Gradle import provider is unavailable; check extension setup and refresh before retrying"
            );
            plan.bind_initialized_folders(&server)?;
            ensure!(
                !plan.requires_policy() || plan.supports_policy(&server),
                "Scoped Gradle module/root policy provider is unavailable; preserve settings, check extension setup and refresh before retrying"
            );
            let (snapshot, current) = self.jdtls_project_snapshot(worktree_id).context(
                "Current Java imported ownership is unavailable; refresh before importing",
            )?;
            ensure!(
                snapshot.server_id == server_id
                    && (current
                        || phase.is_some_and(|token| {
                            self.jdtls_projects
                                .get(&worktree_id)
                                .is_some_and(|state| state.import_operation() == Some(token))
                        }))
                    && self.jdtls_namespace_covers_snapshot(
                        snapshot,
                        worktree.read(cx).abs_path().as_ref(),
                        &worktree.read(cx).snapshot()
                    )
                    && plan.covers_imported_projects(&snapshot.projects),
                "Complete current Java imported ownership is unavailable or outside initialized folders; refresh before importing"
            );
        }
        if matches!(
            target,
            SelectedJdtlsPhaseTarget::MavenGraph(_) | SelectedJdtlsPhaseTarget::GradleGraph { .. }
        ) {
            ensure!(
                self.jdtls_project_snapshot(worktree_id)
                    .is_some_and(|(snapshot, _)| snapshot.server_id == server_id),
                "{name} graph provider changed; refresh before retrying"
            );
        }
        if matches!(target, SelectedJdtlsPhaseTarget::Unlink { .. }) {
            ensure!(
                self.jdtls_project_snapshot(worktree_id)
                    .is_some_and(|(snapshot, _)| snapshot.server_id == server_id),
                "{name} imported project provider changed; refresh before unlinking"
            );
        }
        Ok((server_id, server, worktree, selection))
    }

    #[cfg(feature = "jvm-tools")]
    fn jdtls_ownership_covers_snapshot(
        &self,
        snapshot: &JdtlsProjectSnapshot,
        root: &Path,
        entries: &worktree::Snapshot,
    ) -> bool {
        self.jdtls_namespace_covers_snapshot(snapshot, root, entries)
            && matches!(self.as_local().and_then(|local| local.language_servers.get(&snapshot.server_id)),
                Some(LanguageServerState::Running { imported_ownership: Some((_, coverage)), .. }) if coverage.complete)
    }

    #[cfg(feature = "jvm-tools")]
    fn jdtls_namespace_covers_snapshot(
        &self,
        snapshot: &JdtlsProjectSnapshot,
        root: &Path,
        entries: &worktree::Snapshot,
    ) -> bool {
        match self
            .as_local()
            .and_then(|local| local.language_servers.get(&snapshot.server_id))
        {
            Some(LanguageServerState::Running {
                imported_ownership: Some((token, coverage)),
                server,
                ..
            }) => {
                coverage.namespace_complete
                    && token.server_id() == snapshot.server_id
                    && token.worktree_id() == snapshot.worktree_id
                    && token.generation() == snapshot.generation
                    && coverage.scope_is_current(root, server)
                    && coverage.imported_count
                        == snapshot
                            .projects
                            .iter()
                            .filter(|project| project.membership.is_imported())
                            .count()
                    && snapshot
                        .projects
                        .iter()
                        .filter(|project| project.membership.is_imported())
                        .all(|project| {
                            project_input_is_visible(
                                entries,
                                &project.module_root,
                                snapshot.worktree_id,
                                true,
                            )
                        })
            }
            _ => false,
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn saved_maven_startup_intent(
        worktree_id: WorktreeId,
        cx: &App,
    ) -> Option<Result<settings::MavenBuildSettingsContent, &'static str>> {
        let location = SettingsLocation {
            worktree_id,
            path: RelPath::empty(),
        };
        let settings = ProjectSettings::get(Some(location), cx);
        let maven = settings.jvm_builds.as_ref()?.maven.as_ref()?;
        if maven.selected_poms.is_none()
            && maven.ignored_projects.as_ref().is_none_or(Vec::is_empty)
            && maven
                .ignored_pom_patterns
                .as_ref()
                .is_none_or(Vec::is_empty)
        {
            return None;
        }
        Some(
            settings
                .jvm_build_selection_intent(SettingsStore::global(cx), location)
                .map(|_| maven.clone())
                .map_err(|_| "Saved Maven startup settings are invalid; review settings and refresh before retrying"),
        )
    }

    #[cfg(feature = "jvm-tools")]
    fn saved_gradle_startup_intent(
        worktree_id: WorktreeId,
        cx: &App,
    ) -> Option<Result<settings::GradleBuildSettingsContent, &'static str>> {
        let location = SettingsLocation {
            worktree_id,
            path: RelPath::empty(),
        };
        let settings = ProjectSettings::get(Some(location), cx);
        let gradle = settings.jvm_builds.as_ref()?.gradle.as_ref()?;
        if gradle.selected_build_files.is_none()
            && gradle.ignored_projects.as_ref().is_none_or(Vec::is_empty)
        {
            return None;
        }
        Some(
            settings
                .jvm_build_selection_intent(SettingsStore::global(cx), location)
                .map(|_| gradle.clone())
                .map_err(|_| "Saved Gradle startup settings are invalid; review settings and refresh before retrying"),
        )
    }

    #[cfg(feature = "jvm-tools")]
    fn clear_pending_jvm_startup(
        &mut self,
        server_id: LanguageServerId,
        target: Option<&SelectedJdtlsPhaseTarget>,
    ) {
        if let Some(LanguageServerState::Running {
            pending_maven_startup,
            pending_gradle_startup,
            ..
        }) = self
            .as_local_mut()
            .and_then(|local| local.language_servers.get_mut(&server_id))
        {
            if target.is_none_or(|target| matches!(target, SelectedJdtlsPhaseTarget::SavedMaven(_)))
            {
                *pending_maven_startup = None;
            }
            if target
                .is_none_or(|target| matches!(target, SelectedJdtlsPhaseTarget::GradleModules(_)))
            {
                *pending_gradle_startup = None;
            }
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn apply_pending_jvm_startup(
        &mut self,
        server_id: LanguageServerId,
        worktree_id: WorktreeId,
        cx: &mut Context<Self>,
    ) {
        if self
            .language_server_statuses
            .get(&server_id)
            .is_none_or(|status| status.worktree != Some(worktree_id))
        {
            return;
        }
        // Empty Maven selection completes without a phase or follow-up read.
        for _ in 0..2 {
            if self.jdtls_projects.get(&worktree_id).is_none_or(|state| {
                !state.snapshot_is_current()
                    || state
                        .snapshot()
                        .is_none_or(|snapshot| snapshot.server_id != server_id)
                    || state.import_operation().is_some()
                    || state.failed_import() == Some(server_id)
            }) {
                return;
            }
            let target = match self
                .as_local_mut()
                .and_then(|local| local.language_servers.get_mut(&server_id))
            {
                Some(LanguageServerState::Running {
                    pending_maven_startup,
                    pending_gradle_startup,
                    ..
                }) => pending_maven_startup
                    .take()
                    .map(|intent| intent.map(SelectedJdtlsPhaseTarget::SavedMaven))
                    .or_else(|| {
                        pending_gradle_startup.take().map(|intent| {
                            intent
                                .map(|intent| SelectedJdtlsPhaseTarget::GradleModules(Some(intent)))
                        })
                    }),
                _ => None,
            };
            let Some(target) = target else {
                return;
            };
            let result = target.map_err(anyhow::Error::msg).and_then(|target| {
                self.execute_selected_local_jdtls_phase(worktree_id, target, cx)
            });
            match result {
                Ok(application) => application.detach_and_log_err(cx),
                Err(error) => {
                    if let Some(state) = self.jdtls_projects.get_mut(&worktree_id) {
                        state.mark_import_failed(server_id).log_err();
                    }
                    self.clear_pending_jvm_startup(server_id, None);
                    log::warn!("Could not apply saved JVM startup selection: {error:#}");
                    cx.notify();
                    return;
                }
            }
        }
    }

    #[cfg(feature = "jvm-tools")]
    fn effective_saved_maven_selection(
        &self,
        worktree_id: WorktreeId,
        cx: &App,
    ) -> Result<settings::MavenBuildSettingsContent> {
        let location = SettingsLocation {
            worktree_id,
            path: RelPath::empty(),
        };
        let settings = ProjectSettings::get(Some(location), cx);
        settings.jvm_build_selection_intent(SettingsStore::global(cx), location)?;
        settings
            .jvm_builds
            .as_ref()
            .and_then(|settings| settings.maven.clone())
            .context("Saved Maven settings are absent; select build roots or use provider defaults")
    }

    #[cfg(feature = "jvm-tools")]
    fn effective_saved_gradle_selection(
        &self,
        worktree_id: WorktreeId,
        cx: &App,
    ) -> Result<Option<settings::GradleBuildSettingsContent>> {
        let location = SettingsLocation {
            worktree_id,
            path: RelPath::empty(),
        };
        let settings = ProjectSettings::get(Some(location), cx);
        settings.jvm_build_selection_intent(SettingsStore::global(cx), location)?;
        Ok(settings
            .jvm_builds
            .as_ref()
            .and_then(|settings| settings.gradle.clone()))
    }

    #[cfg(feature = "jvm-tools")]
    pub fn apply_saved_local_maven_selection(
        &mut self,
        worktree_id: WorktreeId,
        cx: &mut Context<Self>,
    ) -> Result<Task<Result<()>>> {
        let intent = self.effective_saved_maven_selection(worktree_id, cx)?;
        self.execute_selected_local_jdtls_phase(
            worktree_id,
            SelectedJdtlsPhaseTarget::SavedMaven(intent),
            cx,
        )
    }

