    #[cfg(feature = "jvm-tools")]
    fn query_local_jdtls_dependency_graph(
        &mut self,
        worktree_id: WorktreeId,
        target: SelectedJdtlsPhaseTarget,
        cx: &mut Context<Self>,
    ) -> Result<Task<Result<()>>> {
        let name = target.name();
        let (server_id, server, worktree, prepared) =
            self.selected_jdtls_phase_provider(worktree_id, &target, None, cx)?;
        ensure!(
            matches!(
                prepared,
                PreparedJdtlsPhase::MavenGraph(_) | PreparedJdtlsPhase::GradleGraph(_)
            ),
            "{name} graph selection changed; refresh before retrying"
        );
        let snapshot = self
            .jdtls_projects
            .get(&worktree_id)
            .and_then(|state| state.snapshot())
            .cloned()
            .with_context(|| {
                format!("Current {name} metadata is unavailable; refresh before retrying")
            })?;
        let root = worktree.read(cx).abs_path();
        let token = self
            .jdtls_projects
            .get_mut(&worktree_id)
            .with_context(|| {
                format!("Current {name} metadata is unavailable; refresh before retrying")
            })?
            .begin_with_metadata(server_id, worktree_id, snapshot.metadata.clone())?;
        let request_timeout = ProjectSettings::get_global(cx)
            .global_lsp_settings
            .get_request_timeout();
        let (sender, receiver) = oneshot::channel();
        let query = cx.spawn(async move |this, cx| {
            let authorization = this
                .update(cx, |store, cx| {
                    let (current_server, _, current_worktree, _) = store
                        .selected_jdtls_phase_provider(worktree_id, &target, Some(token), cx)?;
                    ensure!(
                        current_server == server_id
                            && current_worktree == worktree
                            && current_worktree.read(cx).abs_path() == root,
                        "{name} graph host changed; refresh before retrying"
                    );
                    Ok(())
                })
                .map_err(|_| {
                    anyhow!("{name} graph project closed; reopen and refresh before retrying")
                });
            let result = match authorization {
                Ok(Ok(())) => match prepared {
                    PreparedJdtlsPhase::MavenGraph(selection) => selection.query(server, request_timeout).await.map(|graph| SelectedJdtlsDependencyGraph::Maven(Arc::new(graph))),
                    PreparedJdtlsPhase::GradleGraph(selection) => selection.query(server, request_timeout).await.map(|graph| SelectedJdtlsDependencyGraph::Gradle(Arc::new(graph))),
                    _ => Err(anyhow!("{name} graph selection changed; refresh before retrying")),
                },
                Ok(Err(error)) | Err(error) => Err(error),
            };
            let admission = this.update(cx, |store, cx| {
                let result = (|| {
                    let (current_server, _, current_worktree, _) = store
                        .selected_jdtls_phase_provider(worktree_id, &target, Some(token), cx)?;
                    ensure!(
                        current_server == server_id
                            && current_worktree == worktree
                            && current_worktree.read(cx).abs_path() == root,
                        "{name} graph host changed; refresh before retrying"
                    );
                    let graph = result?;
                    let mut projects = snapshot.projects;
                    let mut partial = snapshot.partial;
                    match (graph, &target) {
                        (SelectedJdtlsDependencyGraph::Maven(graph), SelectedJdtlsPhaseTarget::MavenGraph(pom)) => {
                            let maven = projects.iter_mut().find_map(|project| project.maven.as_mut().filter(|maven| maven.pom == *pom))
                                .context("Maven graph project changed; refresh before retrying")?;
                            ensure!(graph.components.iter().any(|component| component.id == graph.root_component && component.group_id == maven.group_id && component.artifact_id == maven.artifact_id && component.version == maven.version),
                                "Maven graph coordinates changed; reimport and refresh before retrying");
                            partial |= !graph.structural_coverage_known;
                            maven.dependency_graph = Some(graph);
                        }
                        (SelectedJdtlsDependencyGraph::Gradle(graph), SelectedJdtlsPhaseTarget::GradleGraph { module, configuration }) => {
                            let gradle = projects.iter_mut().find(|project| project.module_root == *module).and_then(|project| project.gradle.as_mut())
                                .context("Gradle graph project changed; refresh before retrying")?;
                            ensure!(graph.matches_project(root.as_ref(), gradle) && graph.resolution.configuration == *configuration,
                                "Gradle graph build or configuration changed; reimport and refresh before retrying");
                            partial |= !graph.resolution.structural_coverage_known || !graph.resolution.resolution_complete;
                            gradle.dependency_graph = Some(graph);
                        }
                        _ => anyhow::bail!("Dependency graph selection changed; refresh before retrying"),
                    }
                    let (projects, mut partial) = jvm_project::filter_provider_projects(
                        projects,
                        partial,
                        &current_worktree.read(cx).snapshot(),
                        false,
                    );
                    let had_selection = snapshot.metadata.is_some();
                    let location = SettingsLocation { worktree_id, path: RelPath::empty() };
                    let settings = ProjectSettings::get(Some(location), cx);
                    let metadata = snapshot.metadata.map(|facts| facts.admit_current_snapshot(
                        worktree_id, &current_worktree.read(cx).snapshot(), &projects,
                        settings.jvm_builds.as_ref().and_then(|settings| settings.maven.as_ref()),
                    )).transpose()?.flatten();
                    partial |= had_selection && metadata.is_none();
                    let state = store.jdtls_projects.get_mut(&worktree_id).with_context(|| format!("{name} graph was cancelled or project changed; refresh before retrying"))?;
                    ensure!(
                        state.finish_with_metadata(token, projects, partial, metadata),
                        "{name} graph was cancelled or superseded; refresh before retrying"
                    );
                    if let Some(LanguageServerState::Running {
                        imported_ownership: Some((ownership_token, _)),
                        ..
                    }) = store
                        .as_local_mut()
                        .and_then(|local| local.language_servers.get_mut(&server_id))
                    {
                        *ownership_token = token;
                    }
                    Ok(())
                })();
                if result.is_err()
                    && let Some(state) = store.jdtls_projects.get_mut(&worktree_id)
                {
                    state.fail(token);
                }
                cx.notify();
                if sender.send(result).is_err() {
                    log::debug!("{name} graph caller no longer awaits its result");
                }
            });
            if admission.is_err() {
                log::debug!("{name} graph lost its project binding");
            }
        });
        self.jdtls_refresh_tasks.insert(worktree_id, query);
        cx.notify();
        Ok(cx.background_spawn(async move {
            receiver.await.map_err(|_| {
                anyhow!("{name} graph cancelled or project changed; refresh before retrying")
            })?
        }))
    }

    #[cfg(feature = "jvm-tools")]
    pub fn cancel_local_jdtls_project_query(
        &mut self,
        worktree_id: WorktreeId,
        cx: &mut Context<Self>,
    ) -> Result<bool> {
        ensure!(
            self.as_local().is_some(),
            "Cancel Java project queries on their owning host"
        );
        let Some(token) = self
            .jdtls_projects
            .get(&worktree_id)
            .and_then(|state| state.pending_query())
        else {
            return Ok(false);
        };
        self.cancel_local_jdtls_project_query_for_token(token, cx)
    }

    #[cfg(feature = "jvm-tools")]
    pub fn cancel_local_jdtls_project_query_for_token(
        &mut self,
        token: jvm_project::ProviderRefreshToken,
        cx: &mut Context<Self>,
    ) -> Result<bool> {
        ensure!(
            self.as_local().is_some(),
            "Cancel Java project queries on their owning host"
        );
        let Some(state) = self
            .jdtls_projects
            .get_mut(&token.worktree_id())
            .filter(|state| state.pending_query() == Some(token))
        else {
            return Ok(false);
        };
        state.mark_stale()?;
        self.jdtls_refresh_tasks.remove(&token.worktree_id());
        cx.notify();
        Ok(true)
    }

