#[cfg(feature = "jvm-tools")]
enum SelectedJdtlsPhaseTarget {
    Maven(Vec<ProjectPath>),
    MavenGraph(ProjectPath),
    GradleGraph {
        module: ProjectPath,
        configuration: String,
    },
    SavedMaven(settings::MavenBuildSettingsContent),
    MavenReactor {
        pom: ProjectPath,
        excluded_projects: Vec<ProjectPath>,
        pom_masks: Option<Vec<String>>,
    },
    GradleModules(Option<settings::GradleBuildSettingsContent>),
    Unlink {
        provider: jvm_project::JdtlsUnlinkProvider,
        modules: Vec<ProjectPath>,
    },
}

#[cfg(feature = "jvm-tools")]
impl SelectedJdtlsPhaseTarget {
    fn name(&self) -> &'static str {
        match self {
            Self::Maven(_)
            | Self::MavenGraph(_)
            | Self::MavenReactor { .. }
            | Self::SavedMaven(_) => "Maven",
            Self::GradleModules(_) | Self::GradleGraph { .. } => "Gradle",
            Self::Unlink { provider, .. } => provider.name(),
        }
    }

    fn operation(&self) -> &'static str {
        match self {
            Self::Unlink { .. } => "unlink",
            Self::MavenGraph(_) | Self::GradleGraph { .. } => "dependency graph",
            _ => "import",
        }
    }

    fn command(&self) -> &'static str {
        match self {
            Self::Maven(_) => "groovy.maven.importSelected",
            Self::MavenGraph(_) => "groovy.maven.dependencyGraph",
            Self::GradleGraph { .. } => "groovy.gradle.dependencyGraph",
            Self::SavedMaven(_) => "",
            Self::MavenReactor {
                pom_masks: Some(_), ..
            } => "groovy.maven.importReactorWithMasks",
            Self::MavenReactor { .. } => "groovy.maven.importReactor",
            Self::GradleModules(_) => "groovy.gradle.moduleStates",
            Self::Unlink { provider, .. } => provider.command(),
        }
    }
}

#[cfg(feature = "jvm-tools")]
enum SelectedJdtlsDependencyGraph {
    Maven(Arc<jvm_project::MavenDependencyGraph>),
    Gradle(Arc<jvm_project::GradleDependencyGraph>),
}

#[cfg(feature = "jvm-tools")]
enum PreparedJdtlsPhase {
    Maven(jvm_project::SelectedMavenImport),
    MavenGraph(jvm_project::SelectedMavenDependencyGraph),
    GradleGraph(jvm_project::SelectedGradleDependencyGraph),
    MavenReactor(jvm_project::MavenReactorImport),
    GradleScoped(Box<jvm_project::ScopedGradleImports>),
    GradleModules {
        default_roots: Option<Box<jvm_project::GradleDefaultImportRootsQuery>>,
        root_query: jvm_project::GradleRootStateQuery,
        ignored_root: bool,
        query: jvm_project::GradleModuleStateQuery,
        ignored: Vec<PathBuf>,
        import: jvm_project::SelectedGradleImport,
    },
    Unlink(jvm_project::SelectedProjectUnlink),
    SavedMaven {
        phases: Vec<PreparedJdtlsPhase>,
        default_inputs: Option<Vec<ProjectPath>>,
    },
}

#[cfg(feature = "jvm-tools")]
fn project_input_is_visible(
    entries: &worktree::Snapshot,
    path: &ProjectPath,
    worktree_id: WorktreeId,
    directory: bool,
) -> bool {
    path.worktree_id == worktree_id
        && entries.entry_for_path(&path.path).is_some_and(|entry| {
            (if directory {
                entry.is_dir()
            } else {
                entry.is_file()
            }) && !entry.is_private
                && !entry.is_external
                && !entry.is_fifo
        })
        && !path.path.ancestors().any(|ancestor| {
            entries
                .entry_for_path(ancestor)
                .is_some_and(|entry| entry.is_private || entry.is_external || entry.is_fifo)
        })
}

#[cfg(feature = "jvm-tools")]
fn validate_gradle_module_targets(
    entries: &worktree::Snapshot,
    root: &Path,
    worktree_id: WorktreeId,
    paths: &[PathBuf],
) -> Result<()> {
    for module in paths {
        let path = module
            .strip_prefix(root)
            .ok()
            .and_then(|path| RelPath::new(path, PathStyle::local()).ok())
            .context("Gradle module is outside the current project; refresh before retrying")?;
        ensure!(
            !path.is_empty()
                && project_input_is_visible(
                    entries,
                    &ProjectPath {
                        worktree_id,
                        path: path.into()
                    },
                    worktree_id,
                    true
                ),
            "Gradle module target is missing, private or restricted; import may be partial, review project selection and refresh before retrying"
        );
    }
    Ok(())
}

#[cfg(feature = "jvm-tools")]
fn validate_current_maven_reactor_inputs(
    entries: &worktree::Snapshot,
    root: &Path,
    worktree_id: WorktreeId,
    poms: &[PathBuf],
) -> Result<()> {
    for pom in poms {
        let path = pom.strip_prefix(root).ok()
            .and_then(|path| RelPath::new(path, PathStyle::local()).ok())
            .context("Maven reactor identity is outside the current project; import may be partial, refresh before retrying")?;
        ensure!(
            project_input_is_visible(
                entries,
                &ProjectPath {
                    worktree_id,
                    path: path.into()
                },
                worktree_id,
                false
            ),
            "Maven reactor module input is missing, private or changed; import may be partial, refresh before retrying"
        );
    }
    Ok(())
}

#[cfg(feature = "jvm-tools")]
impl PreparedJdtlsPhase {
    fn default_maven_inputs(&self) -> Option<&[ProjectPath]> {
        match self {
            Self::SavedMaven { default_inputs, .. } => default_inputs.as_deref(),
            _ => None,
        }
    }

    fn maven_reactor_pom(&self) -> Option<&Path> {
        match self {
            Self::MavenReactor(selection) => Some(selection.root_pom()),
            _ => None,
        }
    }

    async fn execute_phase(
        self,
        server: Arc<LanguageServer>,
        request_timeout: Duration,
    ) -> Result<Option<jvm_project::MavenReactorPhaseFacts>> {
        match self {
            Self::SavedMaven { .. } => {
                anyhow::bail!("Saved Maven phase preparation changed; refresh before retrying")
            }
            Self::GradleScoped(_) | Self::GradleModules { .. } => {
                anyhow::bail!(
                    "Gradle module policy requires its owned phase sequence; refresh before retrying"
                )
            }
            Self::MavenGraph(_) | Self::GradleGraph(_) => {
                anyhow::bail!(
                    "Dependency graph requires an explicit snapshot query; refresh before retrying"
                )
            }
            Self::Maven(selection) => selection
                .execute_phase(server, request_timeout)
                .await
                .map(|()| None),
            Self::MavenReactor(selection) => selection
                .execute_phase(server, request_timeout)
                .await
                .map(Some),
            Self::Unlink(selection) => selection
                .execute_phase(server, request_timeout)
                .await
                .map(|()| None),
        }
    }
}

#[cfg(feature = "jvm-tools")]
fn jvm_build_provider_roots(worktree: &Worktree) -> (Option<PathBuf>, Option<PathBuf>) {
    let available = |name| {
        RelPath::from_unix_str(name)
            .ok()
            .and_then(|path| worktree.entry_for_path(path))
            .is_some_and(crate::task_inventory::jvm_build_entry_is_available)
    };
    let root = worktree.abs_path().as_ref().to_path_buf();
    let gradle = [
        "settings.gradle",
        "settings.gradle.kts",
        "build.gradle",
        "build.gradle.kts",
    ]
    .into_iter()
    .any(available)
    .then(|| root.clone());
    let maven = available("pom.xml").then_some(root);
    (gradle, maven)
}

#[cfg(feature = "jvm-tools")]
fn jdtls_import_work(progress: &LanguageServerProgress) -> bool {
    !progress.is_disk_based_diagnostics_progress
        && [progress.title.as_deref(), progress.message.as_deref()]
            .into_iter()
            .flatten()
            .any(|text| {
                text.contains("Importing Maven")
                    || text.contains("Importing Gradle")
                    || text.contains("Importing project")
            })
}

#[derive(Copy, Clone, Debug, Default, PartialEq, Serialize)]
pub struct DiagnosticSummary {
    pub error_count: usize,
    pub warning_count: usize,
}

impl DiagnosticSummary {
    pub fn new<'a, T: 'a>(diagnostics: impl IntoIterator<Item = &'a DiagnosticEntry<T>>) -> Self {
        let mut this = Self {
            error_count: 0,
            warning_count: 0,
        };

        for entry in diagnostics {
            if entry.diagnostic.is_primary {
                match entry.diagnostic.severity {
                    DiagnosticSeverity::ERROR => this.error_count += 1,
                    DiagnosticSeverity::WARNING => this.warning_count += 1,
                    _ => {}
                }
            }
        }

        this
    }

    pub fn is_empty(&self) -> bool {
        self.error_count == 0 && self.warning_count == 0
    }

    pub fn to_proto(
        self,
        language_server_id: LanguageServerId,
        path: &RelPath,
    ) -> proto::DiagnosticSummary {
        proto::DiagnosticSummary {
            path: path.as_unix_str().to_owned(),
            language_server_id: language_server_id.0 as u64,
            error_count: self.error_count as u32,
            warning_count: self.warning_count as u32,
        }
    }
}

#[derive(Clone, Debug)]
pub enum CompletionDocumentation {
    /// There is no documentation for this completion.
    Undocumented,
    /// A single line of documentation.
    SingleLine(SharedString),
    /// Multiple lines of plain text documentation.
    MultiLinePlainText(SharedString),
    /// Markdown documentation.
    MultiLineMarkdown(SharedString),
    /// Both single line and multiple lines of plain text documentation.
    SingleLineAndMultiLinePlainText {
        single_line: SharedString,
        plain_text: Option<SharedString>,
    },
}

impl CompletionDocumentation {
    #[cfg(any(test, feature = "test-support"))]
    pub fn text(&self) -> SharedString {
        match self {
            CompletionDocumentation::Undocumented => "".into(),
            CompletionDocumentation::SingleLine(s) => s.clone(),
            CompletionDocumentation::MultiLinePlainText(s) => s.clone(),
            CompletionDocumentation::MultiLineMarkdown(s) => s.clone(),
            CompletionDocumentation::SingleLineAndMultiLinePlainText { single_line, .. } => {
                single_line.clone()
            }
        }
    }
}

impl From<lsp::Documentation> for CompletionDocumentation {
    fn from(docs: lsp::Documentation) -> Self {
        match docs {
            lsp::Documentation::String(text) => {
                if text.lines().count() <= 1 {
                    CompletionDocumentation::SingleLine(text.trim().to_string().into())
                } else {
                    CompletionDocumentation::MultiLinePlainText(text.into())
                }
            }

            lsp::Documentation::MarkupContent(lsp::MarkupContent { kind, value }) => match kind {
                lsp::MarkupKind::PlainText => {
                    if value.lines().count() <= 1 {
                        CompletionDocumentation::SingleLine(value.into())
                    } else {
                        CompletionDocumentation::MultiLinePlainText(value.into())
                    }
                }

                lsp::MarkupKind::Markdown => {
                    CompletionDocumentation::MultiLineMarkdown(value.into())
                }
            },
        }
    }
}

pub enum ResolvedHint {
    Resolved(InlayHint),
    Resolving(Shared<Task<()>>),
}

pub fn glob_literal_prefix(glob: &Path) -> PathBuf {
    glob.components()
        .take_while(|component| match component {
            path::Component::Normal(part) => !part.to_string_lossy().contains(['*', '?', '{', '}']),
            _ => true,
        })
        .collect()
}

