    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn remote_jvm_client_intent_timeout_and_old_host_are_sanitized(
        cx: &mut gpui::TestAppContext,
    ) {
        use proto::EnvelopedMessage as _;
        let mut fixture = RemoteJvmClientFixture::new(cx).await;
        let notices = cx.new(|_| Vec::<String>::new());
        let _subscription = cx.update(|cx| {
            cx.subscribe(&fixture.store, {
                let notices = notices.clone();
                move |_, event, cx| {
                    if let LspStoreEvent::Notification(message) = event {
                        notices.update(cx, |notices, _| notices.push(message.clone()));
                    }
                }
            })
        });
        fixture.trust(true, cx);
        fixture.enable(true, cx);
        let timed_out = fixture.latest_intent();
        cx.executor().advance_clock(Duration::from_secs(16));
        cx.run_until_parked();
        fixture.assert_accepted(false, cx);
        let withdrawal = fixture.latest_intent();
        assert!(
            matches!(withdrawal.payload, Some(proto::envelope::Payload::SetJvmProjectConsumers(ref request)) if request.roots.is_empty())
        );
        fixture.respond(&timed_out, false, cx);
        fixture.assert_accepted(false, cx);
        fixture.enable(true, cx);
        let failed = fixture.latest_intent();
        fixture
            .input
            .unbounded_send(
                proto::Error {
                    message: "private-provider-error-canary".into(),
                    ..Default::default()
                }
                .into_envelope(3000, Some(failed.id), None),
            )
            .expect("old-host failure");
        cx.run_until_parked();
        fixture.assert_accepted(false, cx);
        assert!(
            !fixture.take_intents().is_empty(),
            "failure sends a fresh withdrawal"
        );
        notices.read_with(cx, |notices, _| {
            assert!(!notices.is_empty());
            assert!(notices.iter().all(|message| message.len() < 512
                && !message.contains("private-provider-error-canary")
                && message.contains("host")));
        });
        fixture.enable(true, cx);
        let recovered = fixture.latest_intent();
        fixture.respond(&recovered, false, cx);
        fixture.assert_accepted(true, cx);
    }

    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn remote_jvm_client_intent_drop_withdraws_without_retaining_owner(
        cx: &mut gpui::TestAppContext,
    ) {
        let mut fixture = RemoteJvmClientFixture::new(cx).await;
        fixture.trust(true, cx);
        fixture.enable(true, cx);
        let request = fixture.latest_intent();
        let Some(proto::envelope::Payload::SetJvmProjectConsumers(request)) = request.payload
        else {
            panic!("current startup request");
        };
        let owner = fixture.store.downgrade();
        let RemoteJvmClientFixture {
            store,
            mut output,
            worktrees,
            input,
            _local: local,
            language_loads,
            binary_requested,
            ..
        } = fixture;
        drop(store);
        // Entity retirement runs at the app effect boundary, not an executor-only pump.
        cx.update(|_| {});
        cx.run_until_parked();
        assert!(
            owner.upgrade().is_none(),
            "pending task cannot retain its LSP owner"
        );
        let mut withdrawals = Vec::new();
        while let Some(Some(envelope)) = output.next().now_or_never() {
            if let Some(proto::envelope::Payload::SetJvmProjectConsumers(intent)) = envelope.payload
            {
                withdrawals.push(intent);
            }
        }
        assert_eq!(
            withdrawals.len(),
            1,
            "teardown withdraws through the existing live connection"
        );
        let withdrawal = withdrawals.first().expect("teardown withdrawal");
        assert!(withdrawal.roots.is_empty() && withdrawal.generation > request.generation);
        assert_eq!(language_loads.load(std::sync::atomic::Ordering::SeqCst), 0);
        assert!(
            binary_requested
                .iter()
                .all(|requested| !requested.load(std::sync::atomic::Ordering::SeqCst))
        );
        drop((worktrees, input, local));
    }

