    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn remote_jvm_client_intent_refuses_unmatched_or_oversized_scope(
        cx: &mut gpui::TestAppContext,
    ) {
        use proto::EnvelopedMessage as _;
        let mut fixture = RemoteJvmClientFixture::new(cx).await;
        fixture.trust(true, cx);
        assert!(
            fixture.take_intents().is_empty(),
            "inactive Copper/shared owner sends no JVM intent"
        );
        for invalid in 0..3 {
            fixture.enable(true, cx);
            let request = fixture.latest_intent();
            let Some(proto::envelope::Payload::SetJvmProjectConsumers(intent)) =
                request.payload.as_ref()
            else {
                panic!("current bounded intent");
            };
            let mut response = proto::JvmProjectConsumersResponse {
                protocol_version: 1,
                generation: intent.generation,
                accepted_roots: intent.roots.clone(),
            };
            match invalid {
                0 => response.protocol_version = 2,
                1 => {
                    response.accepted_roots = vec![proto::ProjectPath {
                        worktree_id: 9999,
                        path: "foreign".into(),
                    }]
                }
                _ => {
                    response.accepted_roots = vec![proto::ProjectPath {
                        worktree_id: fixture.root.worktree_id.to_proto(),
                        path: "private-ack-canary".repeat(65_536),
                    }]
                }
            }
            let reply = response.into_envelope(request.id + 1000, Some(request.id), None);
            let reply = proto::Envelope::decode(reply.encode_to_vec().as_slice())
                .expect("framed invalid scope");
            fixture
                .input
                .unbounded_send(reply)
                .expect("invalid host reply");
            cx.run_until_parked();
            fixture.assert_accepted(false, cx);
            let withdrawal = fixture.latest_intent();
            assert!(
                matches!(withdrawal.payload, Some(proto::envelope::Payload::SetJvmProjectConsumers(ref current)) if current.roots.is_empty() && current.generation>intent.generation)
            );
        }
        fixture.enable(true, cx);
        let repaired = fixture.latest_intent();
        fixture.respond(&repaired, false, cx);
        fixture.assert_accepted(true, cx);
    }

