    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn jvm_initial_unreadable_settings_never_acquires_a_binary(
        cx: &mut gpui::TestAppContext,
    ) {
        cx.update(|cx| {
            let settings = SettingsStore::test(cx);
            cx.set_global(settings);
            release_channel::init(semver::Version::new(0, 0, 0), cx);
        });
        let fs = fs::FakeFs::new(cx.executor());
        let root = Path::new(util::path!("/unreadable-jvm-settings"));
        fs.insert_tree(
            root,
            serde_json::json!({".zed": {}, "Main.java":"class Main {}"}),
        )
        .await;
        fs.insert_file(root.join(".zed/settings.json"), vec![0xff])
            .await;
        let project = crate::Project::test(fs, [root], cx).await;
        let languages = project.read_with(cx, |project, _| project.languages().clone());
        languages.add(Arc::new(language::Language::new(
            language::LanguageConfig {
                name: "Java".into(),
                matcher: language::LanguageMatcher {
                    path_suffixes: vec!["java".into()],
                    ..Default::default()
                }
                .into(),
                ..Default::default()
            },
            None,
        )));
        let requested = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let (_release, received) = oneshot::channel();
        languages.register_lsp_adapter(
            "Java".into(),
            Arc::new(HeldProjectLanguageAdapter {
                name: "jdtls",
                release: Mutex::new(Some(received)),
                requested: requested.clone(),
            }),
        );
        let mut statuses = languages.language_server_binary_statuses();
        let _buffer = project
            .update(cx, |project, cx| {
                project.open_local_buffer_with_lsp(root.join("Main.java"), cx)
            })
            .await
            .expect("Java buffer with unreadable settings");
        for _ in 0..20 {
            cx.run_until_parked();
            cx.executor().advance_clock(Duration::from_millis(50));
        }
        assert!(
            !requested.load(std::sync::atomic::Ordering::SeqCst),
            "an unreadable initial settings file cannot authorize binary acquisition"
        );
        let failures = std::iter::from_fn(|| statuses.next().now_or_never().flatten())
            .filter_map(|(_, status)| match status {
                BinaryStatus::Failed { error } => Some(error),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            failures
                .iter()
                .any(|message| message.contains("settings could not be read")
                    && message.contains("retry")
                    && message.len() < 256)
        );
    }

    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    struct HeldProjectLanguageAdapter {
        name: &'static str,
        release: Mutex<Option<oneshot::Receiver<()>>>,
        requested: Arc<std::sync::atomic::AtomicBool>,
    }

    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[async_trait(?Send)]
    impl LspAdapter for HeldProjectLanguageAdapter {
        fn name(&self) -> LanguageServerName {
            LanguageServerName::new_static(self.name)
        }

        fn is_extension(&self) -> bool {
            true
        }
    }

    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[async_trait(?Send)]
    impl language::DynLspInstaller for HeldProjectLanguageAdapter {
        async fn try_fetch_server_binary(
            &self,
            _delegate: &Arc<dyn LspAdapterDelegate>,
            _container_dir: PathBuf,
            _pre_release: bool,
            _cx: &mut AsyncApp,
        ) -> Result<LanguageServerBinary> {
            anyhow::bail!("The held fixture must not request a server download")
        }

        fn get_language_server_command(
            self: Arc<Self>,
            _delegate: Arc<dyn LspAdapterDelegate>,
            _toolchain: Option<Toolchain>,
            _binary_options: LanguageServerBinaryOptions,
            _cached_binary: futures::lock::OwnedMutexGuard<Option<(bool, LanguageServerBinary)>>,
            _cx: AsyncApp,
        ) -> language::LanguageServerBinaryLocations {
            self.requested
                .store(true, std::sync::atomic::Ordering::SeqCst);
            let release = self.release.lock().take();
            async move {
                let binary = async {
                    release
                        .context("Held fixture acquisition was already used")?
                        .await
                        .context("Held fixture acquisition was cancelled")?;
                    Ok(LanguageServerBinary {
                        path: PathBuf::from("/fake/lsp").join(self.name),
                        arguments: Vec::new(),
                        env: None,
                    })
                }
                .await;
                (binary, None)
            }
            .boxed_local()
        }
    }

