    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn host_jvm_restart_rechecks_held_shutdown(cx: &mut gpui::TestAppContext) {
        for change in [
            "stop-all",
            "stop-provider",
            "restart",
            "session",
            "trust",
            "selection",
            "intent",
            "provider",
            "cancel",
        ] {
            let mut fixture = ProjectLanguageFixture::new(cx).await;
            fixture.settings(
                r#"{"languages":{"Kotlin":{"enable_language_server":false}}}"#,
                cx,
            );
            configure_host_jvm_fixture(&fixture, cx);
            host_jvm_fixture_intent(&fixture, 1, true, cx)
                .await
                .expect("current lease");
            let server = fixture.servers.next().await.expect("leased provider");
            ProjectLanguageFixture::pump(cx);
            let (started, observed) = oneshot::channel();
            let (release, held) = oneshot::channel();
            let mut gate = Some((started, held));
            let _responses = server.set_request_handler::<lsp::Shutdown, _, _>(move |_, _| {
                let (started, held) = gate.take().expect("one shutdown");
                async move {
                    started.send(()).expect("observe shutdown");
                    held.await.context("shutdown gate was cancelled")?;
                    Ok(())
                }
            });
            let mut restart = Box::pin(LspStore::handle_restart_language_servers(
                fixture.store.clone(),
                host_jvm_fixture_restart_envelope(),
                cx.to_async(),
            ));
            assert!(restart.as_mut().now_or_never().is_none());
            observed.await.expect("shutdown actually waits");
            assert!(fixture.running_ids(cx).is_empty());
            match change {
                "stop-all" => fixture.store.update(cx, |store, cx| store.stop_all_language_servers(cx)),
                "stop-provider" => fixture.store.update(cx, |store, cx| {
                    store.stop_language_servers_for_buffers(vec![], HashSet::from_iter([
                        LanguageServerSelector::Name("jdtls".into())
                    ]), cx)
                }).await.expect("newer selected stop"),
                "restart" => fixture.store.update(cx, |store, cx| {
                    store.restart_language_servers_for_buffers(vec![], HashSet::default(), true, cx)
                }),
                "session" => fixture.store.update(cx, |store, cx| {
                    store.set_host_jvm_session(Some(proto::PeerId { owner_id: 0, id: 2 }), cx)
                }).expect("replacement receiving scope"),
                "trust" => fixture.trust(cx, false),
                "selection" => fixture.settings(r#"{"jvm_builds":{"maven":{"selected_poms":[]},"gradle":{"selected_build_files":[]}}}"#, cx),
                "intent" => { host_jvm_fixture_intent(&fixture, 2, false, cx).await.expect("newer withdrawal"); },
                "provider" => fixture.project.read_with(cx, |project, _| {
                    project.languages().remove_lsp_adapter(&fixture.language.name(), &LanguageServerName::new_static("jdtls"));
                }),
                "cancel" => {
                    drop(restart);
                    if release.send(()).is_err() { log::debug!("cancelled restart already released its shutdown gate"); }
                    ProjectLanguageFixture::pump(cx);
                    assert!(fixture.servers.next().now_or_never().is_none());
                    assert!(fixture.running_ids(cx).is_empty());
                    assert!(fixture.store.read_with(cx, |store, _| store.as_local().expect("host").manual_language_server_action.upgrade().is_none()));
                    continue;
                }
                _ => panic!("unknown fixture mutation"),
            }
            release.send(()).expect("finish only held shutdown");
            let error = restart
                .await
                .expect_err("obsolete global restart is rejected")
                .to_string();
            assert!(
                !error.contains("/project-consumer") && !error.contains("private"),
                "{change}: {error}"
            );
            ProjectLanguageFixture::pump(cx);
            assert!(
                fixture.servers.next().now_or_never().is_none(),
                "{change}: no obsolete replacement"
            );
            assert!(fixture.running_ids(cx).is_empty(), "{change}: no startup");
        }
    }

    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn host_jvm_restart_recovers_current_scope_without_buffers(
        cx: &mut gpui::TestAppContext,
    ) {
        let mut fixture = ProjectLanguageFixture::new(cx).await;
        fixture.settings(
            r#"{"languages":{"Kotlin":{"enable_language_server":false}}}"#,
            cx,
        );
        configure_host_jvm_fixture(&fixture, cx);
        host_jvm_fixture_intent(&fixture, 1, true, cx)
            .await
            .expect("current lease");
        let original = fixture.servers.next().await.expect("leased provider");
        ProjectLanguageFixture::pump(cx);
        assert!(fixture.project.read_with(cx, |project, cx| {
            project.buffer_store().read(cx).buffers().next().is_none()
        }));
        for refusal in ["relayed", "old-peer", "mixed", "isolated"] {
            let mut envelope = host_jvm_fixture_restart_envelope();
            match refusal {
                "relayed" => {
                    envelope.original_sender_id = Some(proto::PeerId { owner_id: 9, id: 1 })
                }
                "old-peer" => envelope.sender_id.id = 2,
                "mixed" => envelope.payload.buffer_ids.push(17),
                "isolated" => fixture
                    .store
                    .update(cx, |store, _| store.isolated_recipe_test = true),
                _ => panic!("unknown fixture mutation"),
            }
            let denied = LspStore::handle_restart_language_servers(
                fixture.store.clone(),
                envelope,
                cx.to_async(),
            )
            .await
            .expect_err("invalid authority");
            assert!(!denied.to_string().contains("/project-consumer"));
            fixture
                .store
                .update(cx, |store, _| store.isolated_recipe_test = false);
            assert_eq!(fixture.running_ids(cx), [original.server.server_id()]);
            assert!(fixture.servers.next().now_or_never().is_none());
        }
        LspStore::handle_restart_language_servers(
            fixture.store.clone(),
            host_jvm_fixture_restart_envelope(),
            cx.to_async(),
        )
        .await
        .expect("current global restart");
        let restarted = fixture
            .servers
            .next()
            .await
            .expect("bufferless replacement");
        ProjectLanguageFixture::pump(cx);
        assert_ne!(original.server.server_id(), restarted.server.server_id());
        assert_eq!(fixture.running_ids(cx), [restarted.server.server_id()]);
        fixture
            .store
            .update(cx, |store, cx| store.stop_all_language_servers(cx));
        ProjectLanguageFixture::pump(cx);
        assert!(fixture.running_ids(cx).is_empty());
        fixture.trust(cx, false);
        LspStore::handle_restart_language_servers(
            fixture.store.clone(),
            host_jvm_fixture_restart_envelope(),
            cx.to_async(),
        )
        .await
        .expect_err("untrusted restart cannot clear stop");
        assert!(fixture.store.read_with(cx, |store, _| {
            store.as_local().expect("host").all_language_servers_stopped
        }));
        fixture.trust(cx, true);
        LspStore::handle_restart_language_servers(
            fixture.store.clone(),
            host_jvm_fixture_restart_envelope(),
            cx.to_async(),
        )
        .await
        .expect("current trust restores restart admission");
        host_jvm_fixture_intent(&fixture, 2, true, cx)
            .await
            .expect("fresh current intent after stop");
        let recovered = fixture.servers.next().await.expect("recovered provider");
        ProjectLanguageFixture::pump(cx);
        assert_eq!(fixture.running_ids(cx), [recovered.server.server_id()]);
    }

