    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn host_jvm_consumer_rechecks_held_binary_for_both_languages(
        cx: &mut gpui::TestAppContext,
    ) {
        use fs::Fs as _;
        for (language_name, provider) in [("Java", "jdtls"), ("Kotlin", "kotlin-lsp")] {
            for loss in [
                "withdraw", "session", "trust", "input", "provider", "settings",
            ] {
                let mut fixture = ProjectLanguageFixture::new(cx).await;
                let languages = fixture
                    .project
                    .read_with(cx, |project, _| project.languages().clone());
                let mut servers = if language_name == "Kotlin" {
                    languages.add(Arc::new(Language::new(
                        language::LanguageConfig {
                            name: "Kotlin".into(),
                            ..Default::default()
                        },
                        None,
                    )));
                    languages.register_fake_lsp(
                        "Kotlin",
                        language::FakeLspAdapter {
                            name: "kotlin-lsp",
                            ..Default::default()
                        },
                    )
                } else {
                    std::mem::replace(&mut fixture.servers, futures::channel::mpsc::unbounded().1)
                };
                let disabled = if language_name == "Java" {
                    "Kotlin"
                } else {
                    "Java"
                };
                fixture.settings(
                    &serde_json::json!({"languages":{disabled:{"enable_language_server":false}}})
                        .to_string(),
                    cx,
                );
                let mut statuses = languages.language_server_binary_statuses();
                languages.remove_lsp_adapter(
                    &language_name.into(),
                    &LanguageServerName::new_static(provider),
                );
                let (release, receiver) = oneshot::channel();
                let requested = Arc::new(std::sync::atomic::AtomicBool::new(false));
                languages.register_lsp_adapter(
                    language_name.into(),
                    Arc::new(HeldProjectLanguageAdapter {
                        name: provider,
                        release: Mutex::new(Some(receiver)),
                        requested: requested.clone(),
                    }),
                );
                configure_host_jvm_fixture(&fixture, cx);
                host_jvm_fixture_intent(&fixture, 1, true, cx)
                    .await
                    .expect("admit current host scope");
                ProjectLanguageFixture::pump(cx);
                assert!(
                    requested.load(std::sync::atomic::Ordering::SeqCst),
                    "{language_name}/{loss}: held actual binary lookup"
                );
                assert!(servers.next().now_or_never().is_none());
                match loss {
                    "withdraw" => {
                        host_jvm_fixture_intent(&fixture, 2, false, cx)
                            .await
                            .expect("withdraw");
                    }
                    "session" => fixture
                        .store
                        .update(cx, |store, cx| store.set_host_jvm_session(None, cx))
                        .expect("disconnect"),
                    "trust" => fixture.trust(cx, false),
                    "provider" => languages.remove_lsp_adapter(&language_name.into(), &LanguageServerName::new_static(provider)),
                    "settings" => fixture.settings(&serde_json::json!({"languages":{disabled:{"enable_language_server":false},language_name:{"enable_language_server":false}}}).to_string(), cx),
                    "input" => {
                        fixture.fs.pause_events();
                        for path in [
                            "/project-consumer/pom.xml",
                            "/project-consumer/nested/pom.xml",
                        ] {
                            fixture
                                .fs
                                .remove_file(Path::new(path), Default::default())
                                .await
                                .expect("remove current input");
                        }
                    }
                    _ => unreachable!(),
                }
                if release.send(()).is_err() {
                    log::debug!("The revoked owned binary lookup was already cancelled");
                }
                ProjectLanguageFixture::pump(cx);
                assert!(
                    servers.next().now_or_never().is_none(),
                    "{language_name}/{loss}: obsolete lookup cannot start a server"
                );
                assert!(fixture.running_ids(cx).is_empty());
                if loss == "input" {
                    let mut failures = Vec::new();
                    while let Some(Some((_, status))) = statuses.next().now_or_never() {
                        if let BinaryStatus::Failed { error } = status {
                            failures.push(error);
                        }
                    }
                    assert!(
                        !failures.is_empty(),
                        "input changes have actionable startup failure"
                    );
                    assert!(
                        failures
                            .iter()
                            .all(|error| !error.contains("/project-consumer"))
                    );
                    fixture.fs.unpause_events_and_flush();
                }
                fixture
                    .store
                    .update(cx, |store, cx| store.set_host_jvm_session(None, cx))
                    .expect("retire only fixture session");
                ProjectLanguageFixture::pump(cx);
            }
        }
    }

    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn default_project_language_consumer_rechecks_after_held_binary_acquisition(
        cx: &mut gpui::TestAppContext,
    ) {
        use fs::Fs as _;
        for replacement in [
            None,
            Some("removed"),
            Some("public.txt"),
            Some(".env/private-acquisition-canary"),
        ] {
            let mut fixture = ProjectLanguageFixture::new(cx).await;
            let languages = fixture
                .project
                .read_with(cx, |project, _| project.languages().clone());
            let mut statuses = languages.language_server_binary_statuses();
            languages.remove_lsp_adapter(
                &fixture.language.name(),
                &LanguageServerName::new_static("jdtls"),
            );
            let (release, receiver) = oneshot::channel();
            let requested = Arc::new(std::sync::atomic::AtomicBool::new(false));
            languages.register_lsp_adapter(
                fixture.language.name(),
                Arc::new(HeldProjectLanguageAdapter {
                    name: "jdtls",
                    release: Mutex::new(Some(receiver)),
                    requested: requested.clone(),
                }),
            );
            fixture.trust(cx, true);
            fixture.defaults(true, cx).expect("default intent");
            ProjectLanguageFixture::pump(cx);
            assert!(
                requested.load(std::sync::atomic::Ordering::SeqCst),
                "binary lookup is actually pending"
            );
            assert!(fixture.servers.next().now_or_never().is_none());
            if let Some(replacement) = replacement {
                fixture.fs.pause_events();
                for path in [
                    "/project-consumer/pom.xml",
                    "/project-consumer/nested/pom.xml",
                ] {
                    fixture
                        .fs
                        .remove_file(Path::new(path), Default::default())
                        .await
                        .expect("remove during held acquisition");
                }
                if replacement != "removed" {
                    fixture.fs.insert_tree("/project-consumer", serde_json::json!({"public.txt":"<project/>",".env":{"private-acquisition-canary":"<project/>"}})).await;
                    fixture
                        .fs
                        .create_symlink(
                            Path::new("/project-consumer/pom.xml"),
                            PathBuf::from("/project-consumer").join(replacement),
                        )
                        .await
                        .expect("replace input while acquisition waits");
                }
            }
            release.send(()).expect("release current binary lookup");
            ProjectLanguageFixture::pump(cx);
            if replacement.is_some() {
                assert!(
                    fixture.servers.next().now_or_never().is_none(),
                    "removed inputs cannot start even before watcher delivery"
                );
                assert!(fixture.running_ids(cx).is_empty());
                let mut failures = Vec::new();
                while let Some(Some((_, status))) = statuses.next().now_or_never() {
                    if let BinaryStatus::Failed { error } = status {
                        failures.push(error);
                    }
                }
                assert!(!failures.is_empty(), "stale setup is actionable");
                assert!(failures.iter().all(|error| error.contains("refresh")
                    && !error.contains("/project-consumer")
                    && !error.contains("private-acquisition-canary")));
                fixture.fs.unpause_events_and_flush();
                ProjectLanguageFixture::pump(cx);
            } else {
                let server = fixture
                    .servers
                    .next()
                    .await
                    .expect("current held acquisition starts normally");
                ProjectLanguageFixture::pump(cx);
                assert_eq!(fixture.running_ids(cx), [server.server.server_id()]);
            }
        }
    }

    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn default_project_language_consumer_refuses_invalid_saved_masks_then_recovers_after_clearing(
        cx: &mut gpui::TestAppContext,
    ) {
        let mut fixture = ProjectLanguageFixture::new(cx).await;
        fixture.trust(cx, true);
        let languages = fixture
            .project
            .read_with(cx, |project, _| project.languages().clone());
        let mut statuses = languages.language_server_binary_statuses();
        fixture.settings(r#"{"jvm_builds":{"maven":{"ignored_pom_patterns":["*/private-mask-canary/pom.xml\n"]},"gradle":{"selected_build_files":[]}}}"#, cx);
        let startup_error = cx
            .update(|cx| LspStore::saved_maven_startup_intent(fixture.root.worktree_id, cx))
            .expect("Mask-only settings retain pending admission")
            .expect_err("Invalid masks cannot bypass startup validation");
        assert!(startup_error.contains("settings") && startup_error.contains("refresh"));
        assert!(!startup_error.contains("private-mask-canary"));
        fixture
            .defaults(true, cx)
            .expect("Retained opt-in reports invalid settings");
        ProjectLanguageFixture::pump(cx);
        assert!(
            fixture.servers.next().now_or_never().is_none(),
            "Invalid masks cannot silently launch default import"
        );
        assert!(fixture.running_ids(cx).is_empty());
        let mut failures = Vec::new();
        while let Some(Some((_, status))) = statuses.next().now_or_never() {
            if let BinaryStatus::Failed { error } = status {
                failures.push(error);
            }
        }
        assert!(
            failures
                .iter()
                .any(|error| error.contains("ignored_pom_patterns") && error.contains("refresh")),
            "Invalid saved intent is actionable"
        );
        assert!(
            failures
                .iter()
                .all(|error| !error.contains("private-mask-canary")
                    && !error.contains("/project-consumer"))
        );
        fixture.settings(r#"{"jvm_builds":{"maven":{"ignored_pom_patterns":[]},"gradle":{"selected_build_files":[]}}}"#, cx);
        assert!(
            cx.update(|cx| LspStore::saved_maven_startup_intent(fixture.root.worktree_id, cx))
                .is_none(),
            "Explicitly cleared masks preserve ordinary startup"
        );
        let recovered = fixture
            .servers
            .next()
            .await
            .expect("Explicit clearing permits ordinary default startup");
        ProjectLanguageFixture::pump(cx);
        assert_eq!(fixture.running_ids(cx), [recovered.server.server_id()]);
    }

