    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn project_language_consumer_initializes_joint_controls_and_restores_defaults(
        cx: &mut gpui::TestAppContext,
    ) {
        let mut fixture = ProjectLanguageFixture::new(cx).await;
        let languages = fixture
            .project
            .read_with(cx, |project, _| project.languages().clone());
        languages.remove_lsp_adapter(
            &fixture.language.name(),
            &LanguageServerName::new_static("jdtls"),
        );
        let requests = Arc::new(std::sync::Mutex::new(Vec::new()));
        fixture.servers = languages.register_fake_lsp("Java", language::FakeLspAdapter {
            name: "jdtls",
            initialization_options: Some(serde_json::json!({"bundles":["fixture-bundle"],"settings":{"java":{"import":{"maven":{"enabled":true},"gradle":{"enabled":true}}}},"fixture":"retained"})),
            initializer: Some(Box::new({
                let requests = requests.clone();
                move |server| {
                    server.set_request_handler::<lsp::request::Initialize, _, _>({
                        let requests = requests.clone();
                        move |parameters, _| {
                            requests.lock().expect("initialize requests").push(parameters.initialization_options.expect("adapter options"));
                            async { Ok(lsp::InitializeResult { capabilities: Default::default(), server_info: None }) }
                        }
                    });
                }
            })),
            ..Default::default()
        });
        fixture.settings(
            r#"{"jvm_builds":{"maven":{"selected_poms":[]},"gradle":{"selected_build_files":[]}}}"#,
            cx,
        );
        fixture.register(cx).expect("retained untrusted intent");
        ProjectLanguageFixture::pump(cx);
        assert!(requests.lock().expect("initialize requests").is_empty());
        assert!(
            fixture.servers.next().now_or_never().is_none(),
            "trust precedes startup"
        );
        fixture.trust(cx, true);
        let original = fixture.servers.next().await.expect("trusted joint startup");
        ProjectLanguageFixture::pump(cx);
        let first = requests
            .lock()
            .expect("initialize requests")
            .last()
            .expect("joint initialization")
            .clone();
        assert_eq!(first["projectConfigurations"], serde_json::json!([]));
        assert_eq!(
            first["settings"]["java"]["import"]["maven"]["enabled"],
            false
        );
        assert_eq!(
            first["settings"]["java"]["import"]["gradle"]["enabled"],
            false
        );
        let mut previous = original.server.server_id();
        for (settings, maven, gradle) in [
            (
                r#"{"jvm_builds":{"maven":{"selected_poms":[]}}}"#,
                true,
                false,
            ),
            (
                r#"{"jvm_builds":{"gradle":{"selected_build_files":[]}}}"#,
                false,
                true,
            ),
            ("{}", false, false),
            (
                r#"{"jvm_builds":{"maven":{"selected_poms":[]},"gradle":{"selected_build_files":[]}}}"#,
                true,
                true,
            ),
        ] {
            let count = requests.lock().expect("initialize requests").len();
            fixture.settings(settings, cx);
            let server = fixture.servers.next().await.expect("settings replacement");
            ProjectLanguageFixture::pump(cx);
            assert_ne!(server.server.server_id(), previous);
            previous = server.server.server_id();
            let requests = requests.lock().expect("initialize requests");
            assert_eq!(requests.len(), count + 1);
            let options = requests.last().expect("current initialize");
            assert_eq!(
                options.get("projectConfigurations"),
                (maven && gradle).then(|| serde_json::json!([])).as_ref()
            );
            assert_eq!(
                options["settings"]["java"]["import"]["maven"]["enabled"],
                !maven
            );
            assert_eq!(
                options["settings"]["java"]["import"]["gradle"]["enabled"],
                !gradle
            );
            assert_eq!(options["bundles"], serde_json::json!(["fixture-bundle"]));
            assert_eq!(options["fixture"], "retained");
        }
    }

    #[cfg(all(feature = "jvm-tools", feature = "test-support"))]
    #[gpui::test]
    async fn project_language_consumer_startup_failure_uses_shared_sanitized_status_and_retry(
        cx: &mut gpui::TestAppContext,
    ) {
        let mut fixture = ProjectLanguageFixture::new(cx).await;
        fixture.trust(cx, true);
        let languages = fixture
            .project
            .read_with(cx, |project, _| project.languages().clone());
        let mut statuses = languages.language_server_binary_statuses();
        fixture.settings(r#"{"jvm_builds":{"maven":{"selected_poms":["pom.xml"]}},"lsp":{"jdtls":{"initialization_options":{"projectConfigurations":["private-startup-canary"]}}}}"#, cx);
        fixture
            .register(cx)
            .expect("accepted intent; startup reports failure");
        ProjectLanguageFixture::pump(cx);
        assert!(fixture.running_ids(cx).is_empty());
        assert!(fixture.servers.next().now_or_never().is_none());
        let mut failure = None;
        while let Some(Some((_, status))) = statuses.next().now_or_never() {
            if let BinaryStatus::Failed { error } = status {
                failure = Some(error);
            }
        }
        let error = failure.expect("shared failure status");
        assert!(error.contains("restart the language server"));
        assert!(!error.contains("private-startup-canary"));
        fixture.settings("{}", cx);
        let repaired = fixture
            .servers
            .next()
            .await
            .expect("repaired settings retry");
        ProjectLanguageFixture::pump(cx);
        assert_eq!(fixture.running_ids(cx), [repaired.server.server_id()]);
    }

